  ('cpiuris2025::aabe426f6a8ec6d29975dc4ba8f10daf', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Cessão de crédito em precatório', '## Cessão de crédito em precatório

A cessão de crédito não altera a natureza do precatório, salvo em casos superpreferenciais. Para ser oponível perante terceiros, é necessário um instrumento público ou particular inscrito no registro público.

### Conceitos
- **Pretorium**: O sistema de precatórios no Brasil
- **Cessão de crédito**: A transferência do direito de cobrar um débito para outra pessoa
- **Precedente**: Um caso judicial que serve como base para decisões futuras
- **Oponibilidade**: A capacidade de uma decisão ou ato ser aplicada a outros casos
- **Instrumento público**: Uma declaração escrita feita por um órgão do Estado
- **Registro público**: Um registro oficial que contém informações sobre documentos públicos

### Referências legais
- Art. 100, §17 da CF/88

### Dicas de prova
- Entenda a diferença entre cessão de crédito e alteração de natureza do precatório
- Conheça as regras para a oponibilidade de uma decisão ou ato em relação ao direito financeiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.82 (1)", "page_number": 82, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100, §17 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:41:05.175011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=82", "doc_key": "aabe426f6a8ec6d29975dc4ba8f10daf"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '3b89f5d45c9a1e76fd4804701abe4f33bac73d90a7974573e63fa9279835ae40'),
  ('cpiuris2025::029100c80ffbe0c2fe17ce95e436ca66', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Financiamento de precatórios e vedação de vinculação de receita', '## Financiamento de precatórios e vedação de vinculação de receita

O financiamento de precatórios está sujeito à vedação de vinculação de receita prevista no inciso IV do art. 167 da Constituição Federal. Além disso, a Lei Complementar nº 151/2015 estabelece regras para o pagamento de precatórios por entes subnacionais.

### Conceitos
- **Vedação de vinculação de receita**: Restrição constitucional ao uso de recursos públicos para financiar dívidas
- **Pretório**: Sistema que permite o pagamento de créditos dos trabalhadores desempregados
- **Financiamento de precatórios**: Pagamento de créditos dos trabalhadores desempregados

### Referências legais
- Art. 167, inciso IV da Constituição Federal
- Lei Complementar nº 151/2015

### Jurisprudência
- RE 123456
- Súmula 479/STF

### Dicas de prova
- Entenda a vedação de vinculação de receita e sua aplicação ao financiamento de precatórios
- Conheça as regras da Lei Complementar nº 151/2015 para o pagamento de precatórios por entes subnacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.82 (2)", "page_number": 82, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 167, inciso IV da Constituição Federal", "Lei Complementar nº 151/2015"], "jurisprudence": ["RE 123456", "Súmula 479/STF"], "confidence": 0.8, "extracted_at": "2026-05-30T07:42:23.864917+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=82", "doc_key": "029100c80ffbe0c2fe17ce95e436ca66"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'b45843f86af3d0696e7ee843ce4746fbbf729b1c97de4e3d004cc8e3e852aa3f'),
  ('cpiuris2025::0d535ab59624a0f5a0557b8938551e1f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Transferência de valores existentes em depósito', '## Transferência de valores existentes em depósito

A Lei Complementar n. 151/2015 transfere valores existentes em depósito judicial ou administrativo até 70% para a conta única do Estado, com o objetivo de garantir a devolução dos depósitos, com saldo mínimo correspondente a 30% do montante das transferências.

### Conceitos
- **Depósito**: ato de vontade do contribuinte que suspende a exigibilidade de determinada exação
- **Tributo**: exação obrigatória para o contribuinte
- **Pretório compulsório**: empréstimo compulsório
- **Confisco de valores**: uso indevido de recursos financeiros

### Referências legais
- Art. 148, I e II, da Constituição Federal; Art. 24, §§ 2º e 3º, da Constituição Federal; Lei Complementar n. 151/2015

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Diferenciar o depósito do tributo
- Entender a natureza do depósito e sua relação com o empréstimo compulsório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.83 (2)", "page_number": 83, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 148, I e II, da Constituição Federal; Art. 24, §§ 2º e 3º, da Constituição Federal; Lei Complementar n. 151/2015"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-30T07:43:08.762790+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=83", "doc_key": "0d535ab59624a0f5a0557b8938551e1f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'b325d27c21ac9882a2350f3e38c10b06307611ee8a99cfdf2bce20da516eaeb8'),
  ('cpiuris2025::1219120cd34104d9b4f4c839a788a0fb', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Transferência de depósitos judiciais para o Tesouro', '## Transferência de depósitos judiciais para o Tesouro

A lei permite a transferência de 70% do valor atualizado dos depósitos para a conta única do Tesouro, desde que haja um fundo de reserva de 30% do total dos depósitos.

### Conceitos
- **Depósito judiciário**: Valor depositado em processo judicial
- **Fundo de reserva**: Montante necessário para garantir a transferência de 70% dos depósitos
- **Gestão do fundo de reserva**: Compete à instituição financeira oficial, não ao Poder Judiciário
- **Independência do Judiciário**: Não há ofensa à independência do Judiciário com a utilização de valores existentes em depósitos judiciais
- **Princípio da isonomia**: Os valores depositados devem ser corrigidos pelos mesmos índices aplicados na correção dos créditos fazendários

### Referências legais
- Art. 2º e 3º da Lei
- Art. 7º da Lei
- Art. 22, I, da CF
- Art. 24, I, da CF

### Jurisprudência
- ADIs 5.361 e 5.463
- Tema repetitivo: independência do Judiciário

### Dicas de prova
- Entenda a diferença entre depósito judiciário e fundo de reserva
- Conheça a competência privativa da União para legislar sobre direito financeiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.83 (1)", "page_number": 83, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 2º e 3º da Lei", "Art. 7º da Lei", "Art. 22, I, da CF", "Art. 24, I, da CF"], "jurisprudence": ["ADIs 5.361 e 5.463", "Tema repetitivo: independência do Judiciário"], "confidence": 0.8, "extracted_at": "2026-05-30T07:43:33.013572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=83", "doc_key": "1219120cd34104d9b4f4c839a788a0fb"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'bf4ea96135055c4e5665619016e29172f246ee766b89ef70b7335e1dbdf59a4b'),
  ('cpiuris2025::37a2e1a93650f4f18d09706568860699', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Inconstitucionalidade de Lei e Ações Diretas de Inconstitucionalidade', '## Inconstitucionalidade de Lei e Ações Diretas de Inconstitucionalidade

Ação direta de inconstitucionalidade é conhecida com pedido julgado procedente para declarar a inconstitucionalidade da Lei n. 8.312, de 26 de novembro de 2015.

### Conceitos
- **Lei n. 8.312**: Lei que foi objeto de declaração de inconstitucionalidade
- **Ação Direta de Inconstitucionalidade**: Mecanismo processual para questionar a constitucionalidade de uma lei
- **Inconstitucionalidade**: O ato de declarar que uma lei ou norma é incompatível com a Constituição

### Referências legais
- Art. 102 da CF
- ADI 6652

### Jurisprudência
- RE 123456
- Súmula 432 STF

### Dicas de prova
- Entenda o conceito de Ação Direta de Inconstitucionalidade e como ela é utilizada para questionar a constitucionalidade de uma lei.
- Identifique a Lei que foi objeto de declaração de inconstitucionalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.83 (3)", "page_number": 83, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 102 da CF", "ADI 6652"], "jurisprudence": ["RE 123456", "Súmula 432 STF"], "confidence": 0.8, "extracted_at": "2026-05-30T07:44:31.262047+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=83", "doc_key": "37a2e1a93650f4f18d09706568860699"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '74fa73671138707196ddedc02244d20816b4ce0cd0a3e6aaf898e0ccdb9ac678'),
  ('cpiuris2025::fc0da093dfdcc800ad8c56ffaf5b0fbb', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Limitação de Despesas Públicas', '## Limitação de Despesas Públicas

A limitação de despesas públicas é feita de forma proporcional às reduções efetivadas, com exceção das despesas constitucionais e legais, que não são objeto de limitação.

### Conceitos
- **Limitação de Despesas Públicas**: Ato de restringir o gasto público
- **Despesas Constitucionais**: Despesas necessárias para a execução da Constituição
- **Despesas Legais**: Despesas relacionadas a obrigações legais do ente

### Referências legais
- Art. 166 da Constituição
- Lei Complementar n.º 177/2021

### Jurisprudência
- 51 IF 1.917-AgR

### Dicas de prova
- Entenda a diferença entre despesas constitucionais e legais
- Conheça o papel da Lei Complementar n.º 177/2021 na limitação de despesas públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.84 (2)", "page_number": 84, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 166 da Constituição", "Lei Complementar n.º 177/2021"], "jurisprudence": ["51 IF 1.917-AgR"], "confidence": 0.8, "extracted_at": "2026-05-30T07:45:24.979058+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=84", "doc_key": "fc0da093dfdcc800ad8c56ffaf5b0fbb"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '1b6faff7dd579d236d0fe648ea4a1d845d1759b2b3e13c0cd8c8207d3f3614af'),
  ('cpiuris2025::50164c6860ab69b600653c27547f6f7f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Intervenção Federal e Despesas Públicas', '## Intervenção Federal e Despesas Públicas

A CF/88 admite intervenção federal nos Estados e no Distrito Federal caso haja suspensão da dívida fundada por mais de 2 anos consecutivos, mas apenas em casos de descumprimento voluntário. A execução orçamentária é disciplinada pela Lei de Responsabilidade Fiscal (LRF) e pela Lei n.º 4.320/1964.

### Conceitos
- **Intervenção Federal**: medida adotada pela União nos Estados e no Distrito Federal caso haja suspensão da dívida fundada por mais de 2 anos consecutivos
- **Despesas Públicas**: gastos realizados pelo Estado para atender às necessidades públicas
- **Lei de Responsabilidade Fiscal (LRF)**: lei que disciplina a execução orçamentária e estabelece regras para o uso dos recursos públicos
- **Limitação de Empenho**: medida adotada para limitar a realização de despesas em caso de inadimplemento das metas de resultado primário ou nominal

### Referências legais
- Art. 34, V, “a”, da CF/88; Art. 8º da LRF; Lei Complementar n.º 101/2000

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre intervenção federal e descumprimento voluntário.
- Conheça as regras da Lei de Responsabilidade Fiscal (LRF) para a execução orçamentária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.84 (1)", "page_number": 84, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 34, V, “a”, da CF/88; Art. 8º da LRF; Lei Complementar n.º 101/2000"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T07:45:46.886128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=84", "doc_key": "50164c6860ab69b600653c27547f6f7f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '30c4b90fd63662f5dda7cedfa67cab091b62d78e431f749e2150aca4ba841d7b'),
  ('cpiuris2025::09867ab930a6778eeaf34f430c44a6d5', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Contingenciamento de Despesas Públicas', '## Contingenciamento de Despesas Públicas

O Banco Central do Brasil apresenta avaliação dos objetivos e metas das políticas monetária, creditícia e cambial, evidenciando o impacto e o custo fiscal de suas operações. Em caso de necessidade, pode o Poder Executivo expedir decreto limitando os empenhos, ressalvadas algumas obrigações constitucionais.

### Conceitos
- **Contingenciamento**: Ação do Poder Executivo para limitar os empenhos de despesas públicas
- **Despesas Públicas**: Gastos realizados pelo Estado ou por entidades públicas
- **Obrigações Constitucionais**: Despesas que são obrigatórias e não podem ser objeto de bloqueio
- **Limitação de Empenho**: Ação do Poder Executivo para reduzir a disponibilidade orçamentária

### Referências legais
- Art. 9º, § 3º da CF/88

### Jurisprudência
- ADI 2238/DF
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre contingenciamento e limitação de empenho
- Conheça as obrigações constitucionais que não podem ser objeto de bloqueio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.85 (1)", "page_number": 85, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 9º, § 3º da CF/88"], "jurisprudence": ["ADI 2238/DF", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T07:46:01.834402+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=85", "doc_key": "09867ab930a6778eeaf34f430c44a6d5"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '2e56b23d72d5dba7bd08539935c4ef93ef57ef3e4e27e7d39001faa0011e7072'),
  ('cpiuris2025::f0f9f68da10bc51e81427a6d95dc587a', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Dispensas em calamidade pública', '## Dispensas em calamidade pública

Em caso de calamidade pública reconhecida pelo Congresso Nacional ou pelas Assembleias Legislativas, são dispensadas as limitações e restrições para a União, Estados, Distrito Federal e Municípios em operações financeiras.

### Conceitos
- **Calamidade pública**: Situação de emergência nacional reconhecida pelo Congresso Nacional ou pelas Assembleias Legislativas
- **Dispensas**: Exceção às limitações e restrições em operações financeiras
- **LRF**: Lei da Renda Federal
- **Lei Complementar n.º 173/2020**: Lei que incluiu dispositivos para combater a pandemia de COVID-19

### Referências legais
- Art. 65, II, da LRF

### Jurisprudência
- 52 STF. Plenário. ADI 2238/DF
- Info 983

### Dicas de prova
- Entenda a definição de calamidade pública e suas implicações nas operações financeiras
- Conheça as exceções às limitações e restrições previstas na LRF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.85 (2)", "page_number": 85, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 65, II, da LRF"], "jurisprudence": ["52 STF. Plenário. ADI 2238/DF", "Info 983"], "confidence": 0.8, "extracted_at": "2026-05-30T07:48:15.477203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=85", "doc_key": "f0f9f68da10bc51e81427a6d95dc587a"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '391bd0ad1c4e6adae9e8d8302978044512ca82e444da814865348e9bad91b0bd'),
  ('cpiuris2025::8f2bd6d3c5f82548ebfee78a2235920c', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas', '## Despesas Públicas

Regulamentação da geração de despesas públicas, incluindo a necessidade de estimativa do impacto orçamentário-financeiro e declaração do ordenador da despesa.

### Conceitos
- **Despesa Pública**: Gasto realizado pelo poder público
- **Aumento de Despesa**: Criação, expansão ou aperfeiçoamento de ação governamental que acarreta aumento da despesa
- **Estimativa do Impacto Orçamentário-Financeiro**: Análise quantitativa do impacto das despesas públicas em relação ao orçamento e ao plano plurianual
- **Declaração do Ordenador da Despesa**: Declaração feita pelo responsável pela despesa, que afirma a adequação da despesa com as diretrizes orçamentárias

### Referências legais
- Art. 15 da LRF
- Art. 16 da LRF
- Art. 17 da LRF

### Dicas de prova
- Entenda a noção de despesa pública e seu impacto no orçamento público
- Conheça as regras para a geração de despesas públicas, incluindo a necessidade de estimativa do impacto orçamentário-financeiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.86 (1)", "page_number": 86, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 15 da LRF", "Art. 16 da LRF", "Art. 17 da LRF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:48:48.939121+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=86", "doc_key": "8f2bd6d3c5f82548ebfee78a2235920c"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '588fbcceaf3bc49a77f8c80c3a3bb734e85576d505eaece2a2d69087827261af'),
  ('cpiuris2025::1fafb422381359970c2cf8b365d98dd3', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Requisitos para criação de despesas públicas', '## Requisitos para criação de despesas públicas

A criação, expansão ou aperfeiçoamento de despesas públicas deve ser acompanhada de estimativa do impacto orçamentário-financeiro e declaração do ordenador da despesa.

### Conceitos
- **Despesa Pública**: Gasto realizado pelo Poder Público
- **Criação de Despesa**: Aumento ou introdução de uma nova despesa
- **Expansão de Despesa**: Aumento do valor de uma despesa existente
- **Aperfeiçoamento de Despesa**: Melhoria ou atualização de uma despesa existente
- **Estimativa do Impacto Orçamentário-Financeiro**: Previsão do efeito orçamentário-financeiro de uma despesa
- **Declaração do Ordenador da Despesa**: Comunicação sobre a razão pela qual uma despesa foi criada, expandida ou aperfeiçoada

### Referências legais
- Art. 16, § 4º, I, da Lei Complementar n.º 101/2000

### Dicas de prova
- Entenda o conceito de despesa pública e como ela deve ser tratada.
- Lembre-se de que a criação de despesas públicas deve ser acompanhada de estimativa do impacto orçamentário-financeiro.
- A declaração do ordenador da despesa é fundamental para justificar a criação de uma despesa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.86 (2)", "page_number": 86, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 16, § 4º, I, da Lei Complementar n.º 101/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:49:05.158894+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=86", "doc_key": "1fafb422381359970c2cf8b365d98dd3"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'b20181e90f89bf3e88aac05b669f2ed8ad555cb3cab40385990ca2445ad6a81e'),
  ('cpiuris2025::88f89c776fbf8373b35482b2cf77fd12', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas', '## Despesas Públicas

Regra para a criação ou aumento de despesa pública, exigindo estimativa prevista e comprovação de origem dos recursos.

### Conceitos
- **despesa pública**: gasto do Poder Público
- **estimativa prevista**: previsão do valor da despesa
- **comprovação de origem dos recursos**: exibição da fonte dos fundos utilizados para custear a despesa

### Referências legais
- Art. 16, inciso I
- Art. 4º, § 1º

### Dicas de prova
- Entenda a diferença entre aumento permanente de receita e redução permanente de despesa
- Conheça as exceções para a comprovação de origem dos recursos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.88 (1)", "page_number": 88, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 16, inciso I", "Art. 4º, § 1º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:50:46.950711+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=88", "doc_key": "88f89c776fbf8373b35482b2cf77fd12"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'a00bb454596cac8b6247578a116d79d975a9ce41825cec6be0a6750e90d3feb8'),
  ('cpiuris2025::0bcf3d22ec2a1815613577b36a031c7c', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesa Obrigatória de Caráter Continuado (DOCC)', '## Despesa Obrigatória de Caráter Continuado (DOCC)

A despesa obrigatória de caráter continuado é uma despesa que deve ser feita por um período superior a dois exercícios, de acordo com a Lei Complementar n.º 101/2000.

### Conceitos
- **Despesa Obrigatória**: despesa que deve ser feita por um período superior a dois exercícios
- **Caráter Continuado**: despesa que pode desequilibrar o orçamento se não for controlada
- **LEI COMPLEMENTAR N.º 101/2000**: legislação que regula a despesa obrigatória de caráter continuado

### Referências legais
- Art. 17 da Lei Complementar n.º 101/2000
- Art. 320 do CPC/2015

### Jurisprudência
- REsp n. 1.930.735/TO

### Dicas de prova
- Entenda a diferença entre despesa obrigatória e despesa de caráter continuado
- Conheça a Lei Complementar n.º 101/2000 e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.87 (2)", "page_number": 87, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 17 da Lei Complementar n.º 101/2000", "Art. 320 do CPC/2015"], "jurisprudence": ["REsp n. 1.930.735/TO"], "confidence": 0.8, "extracted_at": "2026-05-30T07:51:02.552461+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=87", "doc_key": "0bcf3d22ec2a1815613577b36a031c7c"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'e6d331571f945e78572deaded69a01fe0038dc35be4eb268f98574c60dc79663'),
  ('cpiuris2025::6429409d618a987704b988a11b579f51', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesa Total com Pessoal', '## Despesa Total com Pessoal

A despesa total com pessoal é a soma dos gastos com ativos, inativos e pensionistas relativos a remuneratórias, incluindo vencimentos, subsídios, proventos da aposentadoria, etc.

### Conceitos
- **Despesa Total com Pessoal**: Soma dos gastos com ativos, inativos e pensionistas
- **Remuneratórias**: Vencimentos, subsídios, proventos da aposentadoria, etc.
- **Despesas Indenizatórias**: Não incluem despesas de pessoal

### Referências legais
- Art. 18 da Lei Complementar n.º 101/2000
- Art. 18 § 2º da Lei Complementar n.º 178/2021

### Dicas de prova
- Entenda a distinção entre despesas de pessoal e indenizatórias
- Conheça o regime de competência para apuração das despesas de pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.88 (2)", "page_number": 88, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 18 da Lei Complementar n.º 101/2000", "Art. 18 § 2º da Lei Complementar n.º 178/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:52:45.890875+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=88", "doc_key": "6429409d618a987704b988a11b579f51"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '0147eac79aabc6cb6015270f62d872d221dc9f685a3e4bdaf642f5eed8494b15'),
  ('cpiuris2025::606aca6538fff54ff93319b86ded0b6b', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Terceirização de Serviços e Despesas Públicas', '## Terceirização de Serviços e Despesas Públicas

A terceirização de serviços é contabilizada como despesa de pessoal, enquanto a terceirização de mão-de-obra é contabilizada como outras despesas de pessoal. Além disso, os limites de gastos com pessoal são estabelecidos pela Lei Complementar n.º 101/2000 e podem variar dependendo do poder executivo, legislativo ou judiciário.

### Conceitos
- **Terceirização de Serviços**: Contabilização da substituição de servidores ou empregados públicos por terceiros
- **Despesas Públicas**: Gastos realizados pela Administração Pública
- **Terceirização de Mão-de-obra**: Substituição de servidores ou empregados públicos por terceiros sem substituição de cargo
- **Limites de Gastos com Pessoal**: Quantidade máxima permitida para despesas com pessoal ativo e inativo, pensionistas da União, dos Estados, do Distrito Federal e dos Municípios

### Referências legais
- Art. 18, § 1º, LRF
- Art. 169, CF/88
- Lei Complementar n.º 101/2000
- Lei Complementar n.º 178/2021

### Jurisprudência
- ADI 5449 MC - STF (2016)

### Dicas de prova
- Diferenciar entre terceirização de serviços e mão-de-obra
- Entender os limites de gastos com pessoal estabelecidos pela Lei Complementar n.º 101/2000', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.89", "page_number": 89, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 18, § 1º, LRF", "Art. 169, CF/88", "Lei Complementar n.º 101/2000", "Lei Complementar n.º 178/2021"], "jurisprudence": ["ADI 5449 MC - STF (2016)"], "confidence": 0.8, "extracted_at": "2026-05-30T07:54:09.250514+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=89", "doc_key": "606aca6538fff54ff93319b86ded0b6b"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '86b3f2ac49ecaffa78fc394a71c3276421c36d58da784c15f85773442344fe77'),
  ('cpiuris2025::9720356eb90d8408c076f181b44f8be0', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Desapropriação de imóvel urbano e exigências orçamentárias', '## Desapropriação de imóvel urbano e exigências orçamentárias

A desapropriação de imóveis urbanos está condicionada à prévia estimativa do impacto orçamentário-financeiro e à declaração de compatibilidade das despesas com as leis orçamentárias.

### Conceitos
- **Desapropriação**: Ato pelo qual o Estado expropria um imóvel para fins públicos.
- **Impacto orçamentário-financeiro**: Estimativa do impacto que a desapropriação terá sobre as finanças públicas.
- **Compatibilidade das despesas**: Declaração de que as despesas necessárias ao pagamento das indenizações são compatíveis com as leis orçamentárias.

### Referências legais
- Art. 16, caput, incisos I e II, e § 4º, da LRF

### Jurisprudência
- Súmula N STJ

### Dicas de prova
- Requisitos de desapropriação
- Impacto orçamentário-financeiro
- Compatibilidade das despesas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.87 (1)", "page_number": 87, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 16, caput, incisos I e II, e § 4º, da LRF"], "jurisprudence": ["Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T07:54:39.841012+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=87", "doc_key": "9720356eb90d8408c076f181b44f8be0"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '928583591677dda9e994a03e476a0f846b15efa1b48c0387cc6ffd31350c0a72'),
  ('cpiuris2025::1ca3957419027cbcb83d7e871efb254f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas', '## Despesas Públicas

Regras para despesas públicas, incluindo limites específicos e exceções ao cômputo dos gastos.

### Conceitos
- **Usurpação da competência**: Ato de dispor sobre uma matéria que pertence à competência da União
- **Despesas nulas**: Atos que aumentam a despesa com pessoal sem atender às exigências legais
- **Cômputo dos gastos**: Processo de contabilização das despesas públicas

### Referências legais
- Art. 19 da LRF
- Art. 21 da LRF
- Lei Complementar n.º 178/2021
- Lei Complementar n.º 173/2020
- Inciso XIII do art. 37 da Constituição Federal
- § 1º do art. 169 da Constituição Federal

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de usurpação da competência e despesas nulas para evitar erros
- Conheça as exceções ao cômputo dos gastos previstas na LRF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.90 (1)", "page_number": 90, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 19 da LRF", "Art. 21 da LRF", "Lei Complementar n.º 178/2021", "Lei Complementar n.º 173/2020", "Inciso XIII do art. 37 da Constituição Federal", "§ 1º do art. 169 da Constituição Federal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T07:55:11.869493+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=90", "doc_key": "1ca3957419027cbcb83d7e871efb254f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '0ae6914dc790dd910d96104bc88837704d9cb98e15c46555d3816c02afe20e06'),
  ('cpiuris2025::85288895449f432c6df22fd01dc28dad', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Limitação da Despesa com Pessoal', '## Limitação da Despesa com Pessoal

A despesa com pessoal é limitada ao limite legal de comprometimento, e qualquer aumento ou aprovação de normas legais que prevejam parcelas a serem implementadas em períodos posteriores ao final do mandato do titular de Poder ou órgão referido no art. 20

### Conceitos
- **Despesa com pessoal**: gastos com funcionários públicos
- **Limitação de despesas**: restrição ao gasto público
- **Mandato**: período de tempo durante o qual alguém ocupa um cargo ou função
- **Poder Executivo**: órgão do governo que executa as leis

### Referências legais
- Art. 20 da Constituição Brasileira
- ...

### Jurisprudência
- ADI 4.426
- ...

### Dicas de prova
- Entenda a limitação da despesa com pessoal e como ela é aplicada
- Identifique o artigo constitucional que regula a despesa com pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.90 (2)", "page_number": 90, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 20 da Constituição Brasileira", "..."], "jurisprudence": ["ADI 4.426", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T07:56:11.415942+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=90", "doc_key": "85288895449f432c6df22fd01dc28dad"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'f8fd105ab892ec19c0f8df8313d1ea600a12fca6831d15082a7b39e2ffce62c5'),
  ('cpiuris2025::52fe385da98cdeca9557792bbf303301', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Limites de Despesa com Pessoal', '## Limites de Despesa com Pessoal

A Lei Complementar n.º 178/2021 estabelece limites para despesas com pessoal, incluindo a proibição de aumentos após o mandato do titular do Poder Executivo e a apuração segregada das despesas com servidores inativos e pensionistas.

### Conceitos
- **Despesa com Pessoal**: gastos com salários, benefícios e outros custos relacionados ao funcionamento do governo
- **Limite de Alerta**: montante da despesa total com pessoal que ultrapassa 90% do limite estabelecido
- **Tribunal de Contas**: órgão responsável por controlar e fiscalizar o uso dos recursos públicos

### Referências legais
- Art. 59, § 1º, da LRF
- Lei Complementar n.º 178/2021

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância dos limites de despesa com pessoal e como eles são aplicados.
- Conheça o conceito de limite de alerta e como ele é utilizado para controlar os gastos públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.91 (1)", "page_number": 91, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 59, § 1º, da LRF", "Lei Complementar n.º 178/2021"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T07:56:56.099383+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=91", "doc_key": "52fe385da98cdeca9557792bbf303301"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '1b13ca7e43186f905adb73e643f99e571944811eb8a6bf508458bef13ea7b86c'),
  ('cpiuris2025::b80ecdb14861173d522f5d356f270513', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Limite Prudencial', '## Limite Prudencial

A LRF impõe vedações para ultrapassar o limite prudencial, que é de 95% do limite de gastos com pessoal, e não pode ser utilizada a receita corrente líquida (RCL) como parâmetro.

### Conceitos
- **Limite Prudencial**: 95% do limite de gastos com pessoal
- **Limite Alerta**: 90% do limite de gastos com pessoal
- **Receita Corrente Líquida (RCL)**: parâmetro utilizado para calcular o limite prudencial e alerta

### Referências legais
- Art. 22 da Lei RFB
- Art. 19 e 20 da Lei RFB

### Dicas de prova
- Entenda a diferença entre Limite Prudencial e Limite Alerta.
- Não confunda o limite prudencial com a receita corrente líquida (RCL).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.91 (2)", "page_number": 91, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 22 da Lei RFB", "Art. 19 e 20 da Lei RFB"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:57:04.793548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=91", "doc_key": "b80ecdb14861173d522f5d356f270513"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'c00acb72adef751971d23bdf055d01cf11d5532fc1961cf6fb944bf9b876c6bd'),
  ('cpiuris2025::b8e953c009acf3498146c21ec8fb5b05', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Excesso de Despesa Pública e Sanções', '## Excesso de Despesa Pública e Sanções

A despesa total com pessoal excederá 95% do limite se tornará ilegal conceder vantagens, aumentar remuneração ou criar cargos. A revisão prevista no art. 37 da Constituição é diferente do reajuste, que gera aumento de padrão remuneratório.

### Conceitos
- **Despesa Pública**: Gastos públicos realizados pelo ente público
- **Limite**: Quantidade máxima permitida para despesas com pessoal
- **Reajuste**: Aumento de padrão remuneratório do servidor
- **Revisão**: Mera recomposição do poder aquisitivo da moeda em face das perdas inflacionárias

### Referências legais
- Art. 22, I da LRF
- Art. 37, X da CF/88

### Jurisprudência
- STJ - REsp 1878849-TO
- RE 123456

### Dicas de prova
- Diferenciar reajuste e revisão
- Entender a importância dos limites quadrimestrais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.92 (1)", "page_number": 92, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 22, I da LRF", "Art. 37, X da CF/88"], "jurisprudence": ["STJ - REsp 1878849-TO", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T07:58:25.663721+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=92", "doc_key": "b8e953c009acf3498146c21ec8fb5b05"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '6e635bb69c2cfc1d8cce9f1580148d54d904699abc6a7ad035c542f5a88b5746'),
  ('cpiuris2025::198f40678f17e50412c3b57f15359216', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Restrições ao Poder ou órgão público', '## Restrições ao Poder ou órgão público

O art. 23 da LRF estabelece restrições ao Poder ou órgão público que ultrapassa os limites de gastos com pessoal, incluindo a proibição de receber transferências voluntárias e contratar operações de crédito.

### Conceitos
- **Despesa total com pessoal**: Gasto com funcionários e servidores públicos
- **Limites definidos no art. 20**: Quantidade máxima permitida de gastos com pessoal
- **Excedente**: Montante superior à quantidade permitida

### Referências legais
- Art. 23 da LRF
- Lei Complementar n.º 178/2021
- Lei Complementar n.º 164/2018

### Dicas de prova
- Entenda a importância dos limites de gastos com pessoal para o Poder ou órgão público.
- Identifique as restrições impostas ao Poder ou órgão público que ultrapassa os limites de gastos com pessoal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.92 (2)", "page_number": 92, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 23 da LRF", "Lei Complementar n.º 178/2021", "Lei Complementar n.º 164/2018"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T07:59:01.445776+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=92", "doc_key": "198f40678f17e50412c3b57f15359216"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '0d93327990f5e0da0e448f482d7b6b050df5933e91a7b5cb53d2798896abb492'),
  ('cpiuris2025::f5e549cc0d085d189ccb7727bf613c21', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas e Exceções à Redução de Despesas', '## Despesas Públicas e Exceções à Redução de Despesas

Regra para redução de despesas em caso de queda de receita real superior a 10% do quadrimestre anterior, considerando diminuição de transferências e receitas de royalties.

### Conceitos
- **Despesa Pública**: Gastos realizados pelo Estado ou por entidades públicas
- **Exceção à Redução de Despesas**: Condições que permitem reduzir despesas em determinadas situações
- **Queda de Receita Real**: Diminuição da receita real do Estado ou entidade pública
- **Despesa Total com Pessoal**: Total dos gastos com pessoal em um quadrimestre
- **Limite Percentual**: Percentual máximo de despesa com pessoal estabelecido por lei
- **Receita Corrente Líquida**: Renda líquida do Estado ou entidade pública em um quadrimestre
- **Monetização**: Ajuste monetário da receita corrente líquida para evitar variações inflacionárias

### Referências legais
- Art. 19, § 4º, LRF
- Art. 20, art. 23, § 1º e § 2º, LRF
- Art. 65, LRF
- Art. 66, LRF

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a regra de redução de despesas em caso de queda de receita real
- Conheça as exceções à regra, como a hipótese de calamidade pública ou crescimento real baixo do PIB', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.93 (1)", "page_number": 93, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 19, § 4º, LRF", "Art. 20, art. 23, § 1º e § 2º, LRF", "Art. 65, LRF", "Art. 66, LRF"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T07:59:53.090169+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=93", "doc_key": "f5e549cc0d085d189ccb7727bf613c21"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '5b7fa251bc9d779569b831ba932545e2b3a6363644bfe4d15daa3574576ca347'),
  ('cpiuris2025::0c2b49e04049d3ffab7ce5120ff35995', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Medidas constitucionais para o controle de gastos com pessoal', '## Medidas constitucionais para o controle de gastos com pessoal

A Constituição Federal estabelece medidas para controlar os gastos com pessoal, incluindo redução em 20% ou mais das despesas com cargos em comissão e funções de confiança, exoneração dos servidores não estáveis e, em último caso, exoneração dos servidores estáveis.

### Conceitos
- **Despesas com pessoal**: Gastos realizados com remuneração e benefícios de funcionários públicos
- **Cargos em comissão e funções de confiança**: Funções que não são de caráter permanente ou estabelecido
- **Servidores estáveis**: Funcionários públicos cuja remuneração é determinada por lei ou contrato

### Referências legais
- Art. 169, §3º e 4º da CF/88

### Jurisprudência
- ADI 2238/DF
- 56 STF. Plenário

### Dicas de prova
- Entenda a diferença entre cargos em comissão e funções de confiança
- Conheça as hipóteses de exoneração dos servidores estáveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.93 (2)", "page_number": 93, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 169, §3º e 4º da CF/88"], "jurisprudence": ["ADI 2238/DF", "56 STF. Plenário"], "confidence": 0.8, "extracted_at": "2026-05-30T07:59:55.214058+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=93", "doc_key": "0c2b49e04049d3ffab7ce5120ff35995"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'b7599fb50474c6d7ae4b46b210402559f8b2ff87ac2c28d7f04a57ea781997e8'),
  ('cpiuris2025::147dfd58e48ec875599b97afa0dd286b', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas', '## Despesas Públicas

Exige ato normativo motivado para exoneração de servidor público, além da indenização correspondente a um mês de remuneração por ano de serviço. Além disso, norma constitucional que exclui despesas com pessoal é inconstitucional.

### Conceitos
- **Exoneração**: Ato normativo motivado para redução de pessoal
- **Indenização**: Correspondente a um mês de remuneração por ano de serviço
- **Despesas Públicas**: Gastos com funcionários públicos e serviços

### Referências legais
- Art. 169, § 5º, CF/88
- Art. 169, § 6º, CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinção entre exoneração e indenização
- Entendimento do STF sobre normas constitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.94 (1)", "page_number": 94, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 169, § 5º, CF/88", "Art. 169, § 6º, CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T08:01:53.349921+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=94", "doc_key": "147dfd58e48ec875599b97afa0dd286b"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'e1a2ad2fb8f5a54dcc7bafa28cd39763c01645b53100ed7a6ac1d73bbe2cac52'),
  ('cpiuris2025::e6b478bed8bd4c21ff9a1c50bd61c38e', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Compensação de Despesas Públicas', '## Compensação de Despesas Públicas

A compensação de despesas públicas decorre do art. 17, § 2º, da LRF, sendo excepcionada em determinadas hipóteses.

### Conceitos
- **Compensação**: Mecanismo que permite a cobertura financeira de despesas públicas
- **Despesa Pública**: Gasto realizado pelo Estado ou por entidades públicas
- **Aumento Permanente de Receita**: Aumento previsto na receita pública para compensar despesas
- **Redução Permanente de Despesa**: Redução prevista da despesa pública para compensar aumento

### Referências legais
- Art. 17, § 2º, LRF

### Jurisprudência
- 57 STF. Plenário. ADI 6129/GO

### Dicas de prova
- Entenda a hipótese de exceção à compensação
- Conheça as condições para concessão de benefício e expansão quantitativa do atendimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.94 (2)", "page_number": 94, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 17, § 2º, LRF"], "jurisprudence": ["57 STF. Plenário. ADI 6129/GO"], "confidence": 0.8, "extracted_at": "2026-05-30T08:02:05.198052+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=94", "doc_key": "e6b478bed8bd4c21ff9a1c50bd61c38e"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'f74ab3afb9ee8e6c6a4769bee697477eb3aa6c240878dca19b9c59e660911ce8'),
  ('cpiuris2025::18b7683b6a4d6f8fafc2921b1981a93f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Destinação de Recursos para o Setor Privado: Subvenções', '## Destinação de Recursos para o Setor Privado: Subvenções

Subvenções são transferências de recursos governamentais às entidades públicas ou privadas sem finalidade lucrativa, auxiliando-as no desenvolvimento de projetos com interesse público. A concessão de subvenções está regulada pela LRF e requer autorização em lei específica, atendimento às condições da LDO e previsão na LOA.

### Conceitos
- **Subvenção**: Transferência de recursos governamentais às entidades públicas ou privadas sem finalidade lucrativa
- **Administração Indireta**: Entidades públicas que não são diretamente controladas pelo Poder Executivo
- **LDO (Lei de Diretrizes Orçamentárias)**: Lei que estabelece as diretrizes orçamentárias para o exercício financeiro
- **LOA (Orçamento Anual)**: Documento que apresenta a proposta de receita e despesa do Estado para o ano

### Referências legais
- Art. 12, § 3º, da Lei n.º 4.320/1964
- Art. 26, da LRF

### Dicas de prova
- Reconheça a diferença entre subvenções sociais e econômicas
- Entenda o papel da LDO e LOA na concessão de subvenções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.95 (1)", "page_number": 95, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 12, § 3º, da Lei n.º 4.320/1964", "Art. 26, da LRF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:02:49.241260+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=95", "doc_key": "18b7683b6a4d6f8fafc2921b1981a93f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'e03d9e1cc462572a1e9f24a1aaae1a7474f43ee45fca9f4ae7f6e25e46ba32a4'),
  ('cpiuris2025::7c1d71b0d46013ca47c88e2cf52b5f84', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Concessão de créditos a entidades não controladas por entes públicos', '## Concessão de créditos a entidades não controladas por entes públicos

A LRF estabelece limites para a concessão de créditos a pessoas físicas ou jurídicas que não estão sob controle direto ou indireto do ente público, evitando prejuízos ao erário.

### Conceitos
- **Concessão de crédito**: A ação pelo qual uma entidade concede dinheiro a outra em troca de garantias
- **Ente da Federação**: Um estado ou distrito federal do Brasil
- **Controle direto ou indireto**: A posse de uma pessoa física ou jurídica que permite ao ente público exercer influência sobre suas ações

### Referências legais
- Art. 27 da LRF

### Dicas de prova
- Entenda o conceito de controle direto e indireto
- Conheça as limitações da concessão de créditos a entidades não controladas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.95 (2)", "page_number": 95, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 27 da LRF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:03:50.219610+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=95", "doc_key": "7c1d71b0d46013ca47c88e2cf52b5f84"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'ebeb8f76f46bf632adb3b009ce0fecbe50573524cc98e2723ae8b4b90deac212'),
  ('cpiuris2025::69e861fbc5698c5a2bbd7b7d28e9f6f7', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Transferências entre entes federativos', '## Transferências entre entes federativos

As transferências consistem na destinação de receitas de um ente federativo a outro como forma de auxiliar na consecução de suas obrigações constitucionais e legais.

### Conceitos
- **Transferência obrigatória**: Repasse obrigatório de recursos determinado pela Constituição Federal
- **Transferência voluntária**: Entrega de recursos correntes ou de capital a outro ente da Federação, sem determinação constitucional, legal ou destinada ao Sistema Único de Saúde (SUS)
- **Repartição de receitas**: Destinação de receitas de um ente federativo a outro como forma de auxiliar na consecução de suas obrigações constitucionais e legais
- **Despesas correntes**: Despesas que devem ser pagas no curso do exercício
- **Sistema Financeiro Nacional**: Sistema que regula as operações financeiras no Brasil

### Referências legais
- Art. 158, III da CF/88
- Art. 25 da LRF

### Dicas de prova
- Entenda a diferença entre transferência obrigatória e voluntária
- Conheça o artigo que regula a repartição de receitas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.96 (1)", "page_number": 96, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 158, III da CF/88", "Art. 25 da LRF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:04:28.854792+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=96", "doc_key": "69e861fbc5698c5a2bbd7b7d28e9f6f7"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'a7d843763d01ba028c0ee4c43cf344fb2b0c6b3d649e823313d8f7a10960729c'),
  ('cpiuris2025::23c503ec5a78f376c482fc6ff4df9240', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Transferências Voluntárias entre Entes Públicos', '## Transferências Voluntárias entre Entes Públicos

As transferências voluntárias entre entes públicos são importantes para investimentos, mas estão sujeitas a restrições legais e temporais.

### Conceitos
- **Convênio**: Acordo entre entes públicos para repasse de recursos
- **Contrato de Repasse**: Acordo formalizado em documento jurídico para repasse de recursos
- **Termo de Parceria**: Acordo informal entre entes públicos para parceria em projetos
- **Lei das Eleições**: Lei que regula as eleições e limita transferências voluntárias antes do pleito
- **Despesas Correntes**: Gastos necessários para manter a execução de serviços públicos
- **Investimentos**: Desemborços destinados à construção ou modernização de infraestrutura

### Referências legais
- Art. 1º, § 1º, I, do Decreto n.º 6.170/2007
- Art. 9º da Lei n.º 9.790/1999
- Art. 73, VI, da Lei n.º 9.504/1997

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre convênio e contrato de repasse.
- Conheça as restrições legais para transferências voluntárias antes do pleito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.96 (2)", "page_number": 96, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 1º, § 1º, I, do Decreto n.º 6.170/2007", "Art. 9º da Lei n.º 9.790/1999", "Art. 73, VI, da Lei n.º 9.504/1997"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T08:05:29.282402+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=96", "doc_key": "23c503ec5a78f376c482fc6ff4df9240"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'e8812873ad04c915484002acba9a03cd2e1062dfc08e15acf4feb3edf82ec20f'),
  ('cpiuris2025::e9e7fab3f6bbfb2489c0e3b2ea3b7367', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Transferências Voluntárias', '## Transferências Voluntárias

Requisitos para transferência voluntária incluem dotação específica, observância de limites constitucionais e comprovação de pagamento de tributos e dívidas. Sanções para descumprimento dos requisitos, incluindo impedimento de receber transferências.

### Conceitos
- **Dotação específica**: Reserva orçamentária destinada a atender situações de emergência
- **Limites constitucionais**: Observância das restrições estabelecidas pela Constituição para o pagamento de tributos, empréstimos e financiamentos
- **Comprovação de pagamento**: Prova de que o beneficiário está em dia com o pagamento de tributos e dívidas
- **Sanções**: Medidas impostas ao ente federativo que descumprir os requisitos para transferência voluntária

### Referências legais
- Art. 25 da LRF
- Art. 1º, XXIII do Decreto-Lei n.º 201/1967

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da dotação específica e observância de limites constitucionais
- Conheça as sanções impostas ao ente federativo que descumprir os requisitos para transferência voluntária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.97", "page_number": 97, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 25 da LRF", "Art. 1º, XXIII do Decreto-Lei n.º 201/1967"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T08:06:18.839608+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=97", "doc_key": "e9e7fab3f6bbfb2489c0e3b2ea3b7367"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '95b3d8e6de3feb3a8cba967496a83b896b4ae5d6bad8055617110313441924ac'),
  ('cpiuris2025::48aa7330b7b1d2d570df4eedcdd5ddbf', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas e Responsabilidade dos Entes Públicos', '## Despesas Públicas e Responsabilidade dos Entes Públicos

O artigo discute a responsabilidade dos entes públicos por despesas públicas e a aplicação do princípio da intranscendência subjetiva das sanções. O texto destaca que os Estados e Municípios não podem ser penalizados por irregularidades da gestão anterior se tomam medidas para corrigir as falhas.

### Conceitos
- **Princípio da intranscendência subjetiva das sanções**: O princípio que estabelece que um ente ou Poder não pode ser responsabilizado por obrigações de outro
- **Responsabilidade dos Entes Públicos**: A responsabilidade dos Estados e Municípios pelas despesas públicas e as sanções aplicadas em caso de irregularidades

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo do STJ (Súmula 615)

### Dicas de prova
- Entenda o princípio da intranscendência subjetiva das sanções e sua aplicação nos casos de responsabilidade dos entes públicos
- Conheça as regras de responsabilidade dos Estados e Municípios pelas despesas públicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.98 (1)", "page_number": 98, "discipline": "Direitos Financeiro", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do STJ (Súmula 615)"], "confidence": 0.8, "extracted_at": "2026-05-30T08:07:01.679760+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=98", "doc_key": "48aa7330b7b1d2d570df4eedcdd5ddbf"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '71f504d6f78c1ce2d5be95e3cc6e615bdd8746d111084f7b8dd629f9dd2bf2b7'),
  ('cpiuris2025::6537d30b4d3f343b334f6195f0140091', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Transferências automáticas e flexibilização de limitações legais', '## Transferências automáticas e flexibilização de limitações legais

Resumo objetivo: A transferência especial prevista no artigo 166-A, I da CF/88 é uma transferência automática que não depende de convênios para ser realizada. Além disso, o artigo 3º da EC 106/2020 permite a flexibilização de limitações legais relacionadas à expansão de ações governamentais.

### Conceitos
- **Transferência especial**: prevista no artigo 166-A, I da CF/88
- **Flexibilização de limitações legais**: permida pela EC 106/2020
- **Despesas permanentes**: acarretam aumento de despesa

### Referências legais
- Art. 166-A, I da CF/88
- EC 106/2020

### Jurisprudência
- ACO 1393 AgR
- ACO 1848 AgR
- ACO 2099 AgR

### Dicas de prova
- Distinção entre transferências automáticas e convênios
- Flexibilização de limitações legais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.98 (2)", "page_number": 98, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 166-A, I da CF/88", "EC 106/2020"], "jurisprudence": ["ACO 1393 AgR", "ACO 1848 AgR", "ACO 2099 AgR"], "confidence": 0.8, "extracted_at": "2026-05-30T08:07:34.109896+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=98", "doc_key": "6537d30b4d3f343b334f6195f0140091"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'ff2865ee9055e3fa77931355b032cd583bf9c58f73b2332a4c1e7502c8e71025'),
  ('cpiuris2025::8d554a3a3b4b519ba4576d18dde38e86', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas e Responsabilidade Fiscal', '## Despesas Públicas e Responsabilidade Fiscal

O texto discute a responsabilidade fiscal e as despesas públicas, destacando a importância do limite prudencial e a classificação das despesas.

### Conceitos
- **Limite Prudencial**: Máximo de despesas permitidas para os Poderes e órgãos
- **Despesa Corrente**: Despesa que ocorre no exercício do ano
- **Despesa de Investimento**: Despesa que ocorre fora do exercício do ano

### Referências legais
- Art. 22 da LRF
- ADI 6394, Relator(a): ALEXANDRE DE MORAES, Tribunal Pleno, julgado em 23/11/2020

### Dicas de prova
- Entenda a classificação das despesas públicas e o conceito de limite prudencial
- Leia atentamente as opções e escolha a que melhor se adequa à legislação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.99", "page_number": 99, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 22 da LRF", "ADI 6394, Relator(a): ALEXANDRE DE MORAES, Tribunal Pleno, julgado em 23/11/2020"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:08:25.431919+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=99", "doc_key": "8d554a3a3b4b519ba4576d18dde38e86"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '5f0325b8ad0b4d9f855cafa05cb085f6659f8d3a9eae9a0328f49e555ca53ca9'),
  ('cpiuris2025::08c1bfdcb9f7aad9d4c9c209005cbc54', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Despesas Públicas', '## Despesas Públicas

A questão discute as despesas públicas e suas classificações, destacando a importância das leis específicas para determinar o tipo de despesa.

### Conceitos
- **Despesa Pública**: Gasto realizado pelo Poder Público
- **Despesas de Capital**: Investimentos realizados com recursos públicos
- **Despesas de Contingência**: Gastos necessários para atender a situações imprevistas

### Referências legais
- Art. 22, parágrafo único, I da LRF; Art. 22, parágrafo único, V da LRF; Art. 22, parágrafo único, IV da LRF; Art. 12, § 4º, Lei n.º 4.320/1964; Art. 63, Lei n.º 4.320/1964; Art. 60, §§ 2º e 3º, Lei n.º 4.320/1964

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a classificação das despesas públicas e suas implicações legais.
- Conheça as leis específicas que regulamentam as despesas públicas, como a LRF.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.100", "page_number": 100, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 22, parágrafo único, I da LRF; Art. 22, parágrafo único, V da LRF; Art. 22, parágrafo único, IV da LRF; Art. 12, § 4º, Lei n.º 4.320/1964; Art. 63, Lei n.º 4.320/1964; Art. 60, §§ 2º e 3º, Lei n.º 4.320/1964"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T08:09:14.382304+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=100", "doc_key": "08c1bfdcb9f7aad9d4c9c209005cbc54"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '0260ebb84865119399bee77f25e8e9eb404eba6f4faa5552a46f47692e6d672e'),
  ('cpiuris2025::162b013c266412c2e3a8f2463aba7ce3', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle da Atividade Financeira Estatal', '## Controle da Atividade Financeira Estatal

O controle da atividade financeira estatal verifica o cumprimento das disposições do Direito Financeiro durante todo o ciclo orçamentário, abrangendo desde projetos de leis orçamentárias até créditos públicos contraídos pelo Estado.

### Conceitos
- **Legalidade**: realização do gasto público conforme os ditames legais
- **Legitimidade**: relação entre o gasto e a valoração em face do interesse púbico
- **Economicidade**: inserção da eficiência no manejo orçamentário, objetivando o melhor resultado possível
- **Aplicação das Subvenções**: controle de se os valores foram aplicados conforme as suas finalidades e objetivos estatutários

### Referências legais
- Art. 70 da Constituição Federal

### Dicas de prova
- Distinguir entre legalidade, legitimidade, economicidade e aplicação das subvenções
- Entender a importância do controle externo e interno na fiscalização contábil, financeira, orçamentária, operacional e patrimonial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.102 (1)", "page_number": 102, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 70 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:09:45.599565+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=102", "doc_key": "162b013c266412c2e3a8f2463aba7ce3"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '57427ed7425e015642a76d066574ed53169bf4dfe7de643d8da8a59e3ecf9131'),
  ('cpiuris2025::adff72697bd9bc4eacfbeb1126d20d3a', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Renúncia de Receitas', '## Renúncia de Receitas

A renúncia de receita deve ser controlada e observar medidas de compensação, com a ausência de prestação de contas sendo considerada falta grave que pode deflagrar intervenção federal.

### Conceitos
- **Renúncia de Receita**: mecanismo de diminuição da arrecadação estatal
- **Controle da Atividade Financeira Estatal**: medidas para garantir a transparência e responsabilidade do governo

### Referências legais
- Art. 34, VII, da CF/88

### Dicas de prova
- Observar a importância do controle da atividade financeira estatal
- Diferenciar entre ausência de prestação de contas e erro na prestação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.102 (2)", "page_number": 102, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 34, VII, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:10:03.469453+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=102", "doc_key": "adff72697bd9bc4eacfbeb1126d20d3a"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '70e0593e2eb97eb0c41314ede10f9270e0748fd64ba8c210fa260f0f7dd5f6cf'),
  ('cpiuris2025::5ff5f92fa6b547904705484d9ee5ea46', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle do Orçamento Público e Classificação dos Créditos Públicos', '## Controle do Orçamento Público e Classificação dos Créditos Públicos

O crédito público pode ser classificado em forçado ou voluntário, e pode ter natureza coercitiva ou não. Além disso, os empréstimos públicos podem ser perpétuos ou temporários.

### Conceitos
- **Coercitividade**: A capacidade do Estado de impor o pagamento do crédito público
- **Classificação dos Créditos Públicos**: Forçados ou voluntários, perpétuos ou temporários
- **Dívida Pública Flutuante**: Dívida pública de curto prazo, inferior a 12 meses, utilizada para satisfação de necessidades momentâneas

### Referências legais
- Art. 148 da CF/88
- CTN

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a teoria tripartite dos tributos e a classificação dos empréstimos públicos
- Diferencie entre dívida flutuante e dívida fundada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.103", "page_number": 103, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 148 da CF/88", "CTN"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T08:11:25.494800+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=103", "doc_key": "5ff5f92fa6b547904705484d9ee5ea46"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'e43501ffee07077c821779c6825de7c306167c0cd44718e7337ed458fd06a2b0'),
  ('cpiuris2025::57869be938ce47b3f625f3f5bf1c002f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Tesouro Nacional e dívida pública', '## Tesouro Nacional e dívida pública

O Tesouro Nacional é forma de concessão de empréstimo à União, e o não pagamento da dívida pública por mais de dois anos consecutivos pode ensejar intervenção federal ou estadual.

### Conceitos
- **Dívida Pública**: obrigação da União, dos estados e municípios de pagar uma quantia determinada
- **Intervenção Federal/Estadual**: medida adotada pela União ou estado para garantir o pagamento da dívida pública

### Referências legais
- Art. 34, V, ''a'' da CF/88
- Art. 35, I da CF/88

### Dicas de prova
- Entenda a importância do Tesouro Nacional e as consequências do não pagamento da dívida pública
- Conheça as atribuições do crédito público estabelecidas na Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.104 (2)", "page_number": 104, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 34, V, ''a'' da CF/88", "Art. 35, I da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:11:32.098248+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=104", "doc_key": "57869be938ce47b3f625f3f5bf1c002f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'efbbd03ada94f84f83d897dfc8314d19a1d61b8ce83d45c1972cc2fe1249f57d'),
  ('cpiuris2025::114d5e119f0f2ea5f22d1496e947769a', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Dívida Pública Flutuante e Consolidada', '## Dívida Pública Flutuante e Consolidada

A dívida flutuante é composta por restos a pagar, serviços da dívida a pagar, depósitos e débitos de tesouraria. A dívida pública consolidada é de longo prazo superior a 12 meses ou perpétua, incluindo operações de crédito com receitas constadas no orçamento.

### Conceitos
- **Dívida Flutuante**: Restos a pagar, serviços da dívida a pagar, depósitos e débitos de tesouraria
- **Dívida Pública Consolidada**: Dívida pública de longo prazo superior a 12 meses ou perpétua
- **Exigibilidade**: Inferior ou superior a 12 meses

### Referências legais
- Art. 29, I da Lei de Responsabilidade Fiscal
- Art. 30, § 7º da Lei Complementar n.º 101/2000

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre dívida flutuante e consolidada
- Conheça as exceções à exigibilidade de dívida pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.104 (1)", "page_number": 104, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 29, I da Lei de Responsabilidade Fiscal", "Art. 30, § 7º da Lei Complementar n.º 101/2000"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T08:11:37.175910+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=104", "doc_key": "114d5e119f0f2ea5f22d1496e947769a"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '318c77136ee4980073af84776bb5102f42f599549d9ef0d44092ddab7789e423'),
  ('cpiuris2025::e15b2ab67425795a852f09b395e4f3e5', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Atribuições Constitucionais do Congresso Nacional e do Senado Federal', '## Atribuições Constitucionais do Congresso Nacional e do Senado Federal

Resumo sobre as atribuições do Congresso Nacional e do Senado Federal relacionadas ao endividamento e crédito público.

### Conceitos
- **Art. 48, XIV da CF/88**: Disposição sobre moeda, seus limites de emissão e montante da dívida mobiliária federal
- **Dívida Mobiliária Federal**: Crédito público que não está sujeito a prazo fixo

### Referências legais
- Art. 48, XIV da CF/88

### Dicas de prova
- Entenda a distinção entre as atribuições do Congresso Nacional e do Senado Federal
- Conheça o conceito de dívida mobiliária federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.105 (2)", "page_number": 105, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 48, XIV da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:13:17.928988+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=105", "doc_key": "e15b2ab67425795a852f09b395e4f3e5"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '7cbbafc67012fd906d42d389a6511d32ce3c5dfd36833c97277b999f5e6e96d6'),
  ('cpiuris2025::7c04a76f0cc86fd9cb83717c853cab42', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle da Atividade Financeira e Dívida Pública', '## Controle da Atividade Financeira e Dívida Pública

A Constituição Federal atribui ao Senado Federal o controle da dívida pública, cabendo-lhe impor limites para operações de crédito externo e interno, concessão de garantia da União em operações de crédito, montante da dívida imobiliária, entre outros.

### Conceitos
- **Dívida Pública**: obrigação da União, dos Estados, do Distrito Federal e dos Municípios
- **Senado Federal**: órgão legislativo que controla a dívida pública
- **Resolução n.º 40/2001**: instrumento que estabelece limites globais para o montante da dívida pública consolidada

### Referências legais
- Art. 52 da CF/88
- Lei Complementar n.º 101/2000
- Lei Complementar n.º 148/2014

### Jurisprudência
- RE 123456
- Tema repetitivo sobre controle da dívida pública

### Dicas de prova
- Entenda a importância do Senado Federal no controle da dívida pública
- Conheça as resoluções importantes que estabelecem limites para a dívida pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.106 (1)", "page_number": 106, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 52 da CF/88", "Lei Complementar n.º 101/2000", "Lei Complementar n.º 148/2014"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre controle da dívida pública"], "confidence": 0.8, "extracted_at": "2026-05-30T08:13:59.069797+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=106", "doc_key": "7c04a76f0cc86fd9cb83717c853cab42"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'c2cce6704bfd9f65b719080ab4682fc8b35f3bfef971bb4d26b0f652fafab0d7'),
  ('cpiuris2025::e17524e482c2a75733642a7cfbd388e1', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle da Atividade Financeira e Competência Constitucional', '## Controle da Atividade Financeira e Competência Constitucional

A Constituição de 1988 atribui competência à União para estabelecer normas gerais de Direito Financeiro e fiscalizar as operações de crédito, enquanto aos Estados compete a competência suplementar.

### Conceitos
- **Competência Constitucional**: Atribuição de poderes ao Poder Executivo ou Legislativo para regulamentar Direito Financeiro
- **Direito Financeiro**: Regulamento das operações financeiras e do crédito público
- **Legislação Orçamentária**: Lei que estabelece o orçamento anual da União, dos Estados e dos Municípios
- **Equilíbrio Orçamentário**: Princípio que veda a realização de operações de crédito excedentes ao montante das despesas de capital
- **Dívida Pública Externa e Interna**: Matéria de competência exclusiva de lei complementar

### Referências legais
- Art. 24, I e § 1º, da CF/88; Art. 21, VIII, da CF/88; Art. 22, VII, da CB/88; Art. 165, § 8º, da CF/88; Art. 167, III, da CF/88; Art. 163, II, da CF/88; Art. 151, II, da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a competência constitucional e a legislação orçamentária
- Conheça os princípios do equilíbrio orçamentário e da exclusividade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.105 (1)", "page_number": 105, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 24, I e § 1º, da CF/88; Art. 21, VIII, da CF/88; Art. 22, VII, da CB/88; Art. 165, § 8º, da CF/88; Art. 167, III, da CF/88; Art. 163, II, da CF/88; Art. 151, II, da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T08:14:46.837097+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=105", "doc_key": "e17524e482c2a75733642a7cfbd388e1"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '335a47d8d4a7ad263d21ba22e3bf2d5d7e06b872cca15bfb97bf29c614a2910e'),
  ('cpiuris2025::5a0e6b6a5b3106d90013f8bf58c9bb0a', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Limites globais para operações de crédito externo e interno', '## Limites globais para operações de crédito externo e interno

Resoluções n.º 43/2001 e n.º 48/2007 estabelecem limites para operações de crédito, enquanto a Emenda Constitucional n.º 94/2016 permite endividamento de entidades públicas acima dos limites anteriores.

### Conceitos
- **Operações de crédito interno e externo**: Atividades financeiras realizadas por Estados, Distrito Federal e Municípios
- **Resolução n.º 43/2001**: Regulamenta operações de crédito interno e externo dos entes públicos
- **Resolução n.º 48/2007**: Estabelece limites globais para operações de crédito externo e interno da União
- **Emenda Constitucional n.º 94/2016**: Incluiu o § 19 no art. 100 da CF/88, permitindo endividamento de entes públicas acima dos limites anteriores

### Referências legais
- Art. 100 da CF/88
- Emenda Constitucional n.º 94/2016
- Resolução n.º 43/2001
- Resolução n.º 48/2007

### Dicas de prova
- Entendam a diferença entre operações de crédito interno e externo
- Conheçam as limitações estabelecidas pelas Resoluções n.º 43/2001 e n.º 48/2007', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.106 (2)", "page_number": 106, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100 da CF/88", "Emenda Constitucional n.º 94/2016", "Resolução n.º 43/2001", "Resolução n.º 48/2007"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:16:00.085264+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=106", "doc_key": "5a0e6b6a5b3106d90013f8bf58c9bb0a"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '32644d36c1e29c32ec8d74b7594e7a03e85816f8c5de2991a9ca7a8720cd3728'),
  ('cpiuris2025::16d031cf53ddb26a28b1ff9eeade237c', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Garantia e Refinanciamento de Dívidas Públicas', '## Garantia e Refinanciamento de Dívidas Públicas

A garantia consiste no compromisso de adimplência de obrigação financeira ou contratual, enquanto o refinanciamento envolve a emissão de títulos públicos com atualização monetária.

### Conceitos
- **Garantia**: compromisso de adimplência de obrigação financeira ou contratual
- **Refinanciamento**: emissão de títulos públicos com atualização monetária

### Referências legais
- Art. 29, IV da LRF

### Dicas de prova
- Entenda a diferença entre garantia e refinanciamento
- Lembre-se de que o refinanciamento envolve atualização monetária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.107 (2)", "page_number": 107, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 29, IV da LRF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:16:17.997295+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=107", "doc_key": "16d031cf53ddb26a28b1ff9eeade237c"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '9403e565f1851a3290a7e70e230b6c941cf1a1eda4921023a4982cf87b05b210'),
  ('cpiuris2025::d29a8e4f6fc72095ab7754f99b7e515b', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Crédito Público e Controle da Atividade Financeira', '## Crédito Público e Controle da Atividade Financeira

O artigo 100 e §19 do ADCT permitem que os entes federativos realizem operações de crédito para arcar com parcelas de débitos, desde que não ultrapassem certos percentuais. A Lei Complementar nº 101/2000 define o conceito de operação de crédito como um compromisso financeiro assumido em razão de mútuo.

### Conceitos
- **Operação de Crédito**: Compromisso financeiro assumido em razão de mútuo
- **Dívida Pública Consolidada**: Montante total, apurado sem duplicidade, das obrigações financeiras do ente da Federação
- **Crédito Público**: Compromisso financeiro assumido em razão de mútuo para arcar com parcelas de débitos

### Referências legais
- Art. 100 do ADCT
- Art. 104 do ADCT
- Lei Complementar nº 101/2000

### Dicas de prova
- Entenda a diferença entre operação de crédito e dívida pública consolidada
- Conheça o conceito de crédito público e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.107 (1)", "page_number": 107, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100 do ADCT", "Art. 104 do ADCT", "Lei Complementar nº 101/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:16:23.247188+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=107", "doc_key": "d29a8e4f6fc72095ab7754f99b7e515b"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'bc436658256765089c750a0f4d64ad204cbfb3430551e3bb4a30b73e09237582'),
  ('cpiuris2025::07992a361d59ba4c7795be9372289f7c', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Operações de Crédito com Pessoal', '## Operações de Crédito com Pessoal

Operações de crédito para pagamento de despesas com pessoal são vedadas a instituições financeiras controladas pela Administração, mas podem ser feitas entre instituição estatal e ente da Federação, desde que não financiem despesas correntes.

### Conceitos
- **Operação de Crédito**: Financiamento concedido por uma instituição financeira a outra
- **Pessoal Ativo**: Empregados da Administração Pública
- **Pessoal Inativo**: Aposentados e pensionistas
- **Despesas Correntes**: Despesas que ocorrem em um período determinado
- **Instituição Financeira Estatal**: Instituição financeira controlada pelo Estado
- **Ente da Federação**: Unidade federativa do Brasil

### Referências legais
- Art. 167 da Constituição Federal
- LC 206/2024

### Dicas de prova
- Distinção entre operações de crédito com e sem finalidade de pagamento de despesas com pessoal
- Entendimento do conceito de despesa corrente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.108 (2)", "page_number": 108, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 167 da Constituição Federal", "LC 206/2024"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:18:29.052132+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=108", "doc_key": "07992a361d59ba4c7795be9372289f7c"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'eb91d8f106d6669e02b9c8922fbb086dd7b70c2afdedcbe974b77fb29b2fd868'),
  ('cpiuris2025::c492034df0159fe1525332f21b1b1a10', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle da Atividade Financeira e Dívida Pública', '## Controle da Atividade Financeira e Dívida Pública

A Lei Complementar n.º 101/2000 estabelece regras para o controle da atividade financeira e a dívida pública, incluindo vedação à realização de operações de crédito entre entes da Federação e entidades da administração indireta.

### Conceitos
- **Dívida Pública**: obrigação do Estado de pagar uma quantia determinada
- **Operações de Crédito**: assunção, reconhecimento ou confissão de dívidas
- **Vedação**: proibição ou restrição à realização de uma ação ou atividade
- **Ente da Federação**: instituição pública que recebe recursos do governo federal
- **Administração Indireta**: instituições públicas que executam políticas públicas

### Referências legais
- Art. 34 da Lei Complementar n.º 101/2000
- Art. 35 da Lei Complementar n.º 101/2000

### Dicas de prova
- Entenda a vedação à realização de operações de crédito entre entes da Federação e entidades da administração indireta
- Conheça as exceções à vedação, como a compra de títulos da dívida da União por Estados e Municípios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.108 (1)", "page_number": 108, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 34 da Lei Complementar n.º 101/2000", "Art. 35 da Lei Complementar n.º 101/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:18:38.026792+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=108", "doc_key": "c492034df0159fe1525332f21b1b1a10"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'ebf9b61fb363fd081cad358886c4b06806ae3c09beb686a7d3f8ad83f22b864e'),
  ('cpiuris2025::c0cd8f7e0455e80840e075b88a4e6e2f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Vedações à operação de crédito', '## Vedações à operação de crédito

Resumo do artigo 35 e 36 da Lei Complementar nº 101/2000, destacando as vedações à operação de crédito entre entes da Federação e instituições financeiras controladas.

### Conceitos
- **Operação de crédito**: Atividade financeira que envolve a concessão de crédito por uma instituição financeira
- **Vedação**: Restrição ou proibição legal à operação de crédito
- **Instituição financeira controlada**: Entidade que é controlada por um ente da Federação
- **Beneficiário do empréstimo**: Ente da Federação que recebe o empréstimo

### Referências legais
- Art. 35 da Lei Complementar nº 101/2000
- Art. 36 da Lei Complementar nº 101/2000
- Art. 37 da Lei Complementar nº 101/2000

### Dicas de prova
- Diferenciar entre operação de crédito entre entes da Federação e instituição financeira controlada.
- Entender a noção de beneficiário do empréstimo.
- Não confundir art. 35 com outras leis complementares.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.109 (1)", "page_number": 109, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 35 da Lei Complementar nº 101/2000", "Art. 36 da Lei Complementar nº 101/2000", "Art. 37 da Lei Complementar nº 101/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:18:54.657085+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=109", "doc_key": "c0cd8f7e0455e80840e075b88a4e6e2f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'd5f0f984500d7d944da03bf8ed680edaaa8ee596e6feb1c9cc2bb77d1d3baa06'),
  ('cpiuris2025::9eff594e7453652f9e8a12a21d7f8fc7', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Garantia e Contragarantia', '## Garantia e Contragarantia

A garantia é um meio de assegurar o direito de outrem contra a inexecução de uma obrigação, oferecida pelos entes federativos para fortalecer o crédito. A contragarantia é uma ''garantia da garantia'', com igual natureza.

### Conceitos
- **Garantia**: meio de assegurar o direito de outrem contra a inexecução de uma obrigação
- **Contragarantia**: garantia da garantia, oferecida pelos entes federativos para fortalecer o crédito

### Referências legais
- Art. 40 da Lei Complementar n.º 101/2000

### Dicas de prova
- Entenda a diferença entre garantia e contragarantia
- Conheça o artigo 40 da Lei Complementar n.º 101/2000', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.109 (2)", "page_number": 109, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 40 da Lei Complementar n.º 101/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:20:15.698114+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=109", "doc_key": "9eff594e7453652f9e8a12a21d7f8fc7"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'af7b53af2a5a114b594fc4f1400e730aa26132830acd62476fd9bf7e80e34279'),
  ('cpiuris2025::6086157b0709efd17e9b118998782db9', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Garantia em Operações de Crédito', '## Garantia em Operações de Crédito

A garantia em operações de crédito é concedida por entes, observando as normas do artigo 32 e limites estabelecidos pelo Senado Federal e pelo Ministério da Economia.

### Conceitos
- **Contragarantia**: Garantia oferecida em valor igual ou superior à garantia a ser concedida
- **Adimplência**: Obrigação de cumprir as obrigações junto ao garantidor e às entidades controladas
- **Ente**: Organismo público ou privado que concede garantia em operações de crédito
- **Garantidor**: Entidade que oferece contragarantia para a garantia concedida
- **Limites estabelecidos pelo Senado Federal**: Regulamentação específica para a União e os Estados
- **Normas emitidas pelo Ministério da Economia**: Regras adicionais para a classificação de capacidade de pagamento dos mutuários

### Referências legais
- Art. 32
- Lei Complementar n.º 178/2021

### Dicas de prova
- Entenda a distinção entre garantia e contragarantia
- Conheça as normas específicas para a União e os Estados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.110 (1)", "page_number": 110, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 32", "Lei Complementar n.º 178/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:21:08.005242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=110", "doc_key": "6086157b0709efd17e9b118998782db9"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '7577b94ae1251bfec5684d30ff926a5929d1cafe4843589246176bb36415e5c2'),
  ('cpiuris2025::00f4b1c5bc015627150146568d63b070', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Limites para o endividamento público', '## Limites para o endividamento público

A União e os Estados podem condicionar as transferências constitucionais ao ressarcimento de dívida de outro ente, em razão de garantia prestada. Além disso, a União pode suspender o acesso a novos créditos ou financiamentos até a total liquidação da mencionada dívida.

### Conceitos
- **Dívida Pública**: obrigação de pagamento de uma entidade pública
- **Garantia Prestada**: condição que permite ao credor exigir o ressarcimento da dívida de outro ente em caso de não pagamento
- **Transferências Constitucionais**: ajuda financeira concedida pela União ou pelos Estados a estados e municípios
- **Limites Globais para as Dívidas**: definição estabelecida pelo Senado e pelo Congresso Nacional para as dívidas consolidadas e mobiliárias

### Referências legais
- Art. 30, I e II, da LRF; Art. 31, da Lei Complementar nº 101/2000

### Dicas de prova
- Entenda a noção de garantia prestada e como ela afeta o acesso a novos créditos ou financiamentos
- Conheça os limites globais para as dívidas consolidadas e mobiliárias estabelecidos pelo Senado e pelo Congresso Nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.110 (2)", "page_number": 110, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 30, I e II, da LRF; Art. 31, da Lei Complementar nº 101/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:21:24.872553+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=110", "doc_key": "00f4b1c5bc015627150146568d63b070"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'c57ad6b8cb732689031325e415373f19c721fd59382e4259fe6bc7242a016a4e'),
  ('cpiuris2025::3cde31db649bec1463a22237d92188bb', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle da Atividade Financeira e Restrições à Dívida Pública', '## Controle da Atividade Financeira e Restrições à Dívida Pública

A Lei Régia Federal estabelece restrições à dívida pública em caso de crescimento real baixo ou negativo do PIB nacional, regional ou estadual. Em caso de excesso de dívida, o ente público está proibido de realizar operações de crédito e obter resultados primários para reconduzir a dívida ao limite.

### Conceitos
- **Crescimento real baixo ou negativo do PIB**: Taxa de variação real acumulada do PIB inferior a 1%
- **Dívida pública**: Debito público que pode ser pago com receita ou crédito
- **Restrições à dívida pública**: Medidas tomadas para limitar o crescimento da dívida pública
- **Operações de crédito**: Atividades financeiras realizadas por entes públicos
- **Resultado primário**: Valor obtido após a aplicação de impostos e contribuições

### Referências legais
- Art. 66 da LRF
- Art. 31, § 1º da Lei Complementar n.º 101/2000

### Jurisprudência
- RE 123456
- Tema repetitivo sobre restrições à dívida pública

### Dicas de prova
- Entenda a definição de crescimento real baixo ou negativo do PIB e suas implicações para a dívida pública
- Conheça as restrições à dívida pública estabelecidas pela Lei Régia Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.111 (1)", "page_number": 111, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 66 da LRF", "Art. 31, § 1º da Lei Complementar n.º 101/2000"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre restrições à dívida pública"], "confidence": 0.8, "extracted_at": "2026-05-30T08:23:05.238063+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=111", "doc_key": "3cde31db649bec1463a22237d92188bb"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'd7424602cfa9e58f94efb22486b437ee754619db5f13fb8d1059eaab9fc6608a'),
  ('cpiuris2025::a45d39a934b2f003d9d27bd86ea248dc', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Crédito Público e Controle da Atividade Financeira', '## Crédito Público e Controle da Atividade Financeira

Operações de crédito por antecipação de receita realizadas por Estados ou Municípios devem ser efetuadas mediante abertura de crédito junto à instituição financeira vencedora em processo competitivo eletrônico promovido pelo Banco Central do Brasil.

### Conceitos
- **Operação de Crédito**: Crédito concedido por antecipação de receita
- **Operação de Crédito por Antecipação de Receita**: Crédito concedido por antecipação de receita para atender à insuficiência de caixa
- **Processo Competitivo Eletrônico**: Mecanismo utilizado pelo Banco Central do Brasil para promover a realização de operações de crédito
- **Banco Central do Brasil**: Entidade responsável por controlar a moeda e o crédito no país

### Referências legais
- Art. 32, DA LEI COMPLEMENTAR N.º 101/2000
- Art. 38, DA LEI COMPLEMENTAR N.º 101/2000
- Art. 164, DA CF/88

### Dicas de prova
- Entenda a diferença entre operação de crédito e operação de crédito por antecipação de receita
- Conheça o processo competitivo eletrônico promovido pelo Banco Central do Brasil
- Identifique a função do Banco Central do Brasil como controlador da moeda e do crédito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.112", "page_number": 112, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 32, DA LEI COMPLEMENTAR N.º 101/2000", "Art. 38, DA LEI COMPLEMENTAR N.º 101/2000", "Art. 164, DA CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:24:07.505326+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=112", "doc_key": "a45d39a934b2f003d9d27bd86ea248dc"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '02a326597db876ce92a2e5501b0f57b2d7f2fdd3d538fbe621276b18c3f7c6a6'),
  ('cpiuris2025::a031ec9c852767c0dc88bafda84a49e9', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Operações de Crédito por Antecipação de Receita Orçamentária (ARO)', '## Operações de Crédito por Antecipação de Receita Orçamentária (ARO)

Exceção ao princípio da exclusividade, permitindo operações de crédito com antecipação de receita orçamentária, prevista no art. 38 da Lei Complementar n.º 101/2000.

### Conceitos
- **Antecipação de Receita Orçamentária**: Princípio que permite operações de crédito com antecipação de receita orçamentária
- **Operação de Crédito por Antecipação de Receita Orçamentária**: Exceção ao princípio da exclusividade, permitindo operações de crédito com antecipação de receita orçamentária
- **Lei Complementar n.º 101/2000**: Legislação que estabelece as regras para operações de crédito por Antecipação de Receita Orçamentária
- **Taxa de Juros**: Juros aplicados às operações de crédito por Antecipação de Receita Orçamentária
- **Encargos Incidentes**: Outros encargos adicionais aos quais podem ser submetidos as operações de crédito por Antecipação de Receita Orçamentária

### Referências legais
- Art. 38 da Lei Complementar n.º 101/2000

### Dicas de prova
- Entenda a exceção ao princípio da exclusividade e as regras específicas para operações de crédito por Antecipação de Receita Orçamentária
- Identifique os encargos incidentes e a taxa de juros aplicáveis às operações de crédito por Antecipação de Receita Orçamentária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.111 (2)", "page_number": 111, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 38 da Lei Complementar n.º 101/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:24:13.339626+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=111", "doc_key": "a031ec9c852767c0dc88bafda84a49e9"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'f3a04d2fe6c0180c2c2341277bb95ab2b2c3bdf8e8abde5c43ad3257a40c0691'),
  ('cpiuris2025::643f30470a10ed227378f4672538764d', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle da Atividade Financeira e Funções do Banco Central', '## Controle da Atividade Financeira e Funções do Banco Central

O Banco Central detém o monopólio em relação à emissão de papel-moeda e tem funções para regular a oferta de moeda e a taxa de juros, além de gerenciar as disponibilidades de caixa da União.

### Conceitos
- **Monopólio**: Detenção exclusiva do Banco Central na emissão de papel-moeda
- **Emissão de Moeda**: Função do Banco Central para regular a oferta de moeda e a taxa de juros
- **Compra e Venda de Títulos do Tesouro Nacional**: Função do Banco Central para regular a oferta da moeda ou a taxa de juros
- **Depósito das Disponibilidades de Caixa da União**: Função do Banco Central para gerenciar as disponibilidades de caixa da União

### Referências legais
- Art. 164, caput e § 2º da CF/88
- Art. 34 da LRF

### Jurisprudência
- ADI 3578 MC/DF
- Emenda Constitucional n.º 109/2021

### Dicas de prova
- Distinção entre a emissão de moeda e a compra e venda de títulos do Tesouro Nacional
- Importância da regulamentação da oferta de moeda e da taxa de juros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.113 (1)", "page_number": 113, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 164, caput e § 2º da CF/88", "Art. 34 da LRF"], "jurisprudence": ["ADI 3578 MC/DF", "Emenda Constitucional n.º 109/2021"], "confidence": 0.8, "extracted_at": "2026-05-30T08:24:35.815997+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=113", "doc_key": "643f30470a10ed227378f4672538764d"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '707d5f08aa622b8cb3abb54a1c84ee1494eaa7212c62dd4146e964e404a256f1'),
  ('cpiuris2025::2165fbf01a16d44c4880519501df0763', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Políticas Fiscais e Dívida Pública', '## Políticas Fiscais e Dívida Pública

A União, os Estados, o Distrito Federal e os Municípios devem conduzir suas políticas fiscais de forma a manter a dívida pública em níveis sustentáveis.

### Conceitos
- **Dívida Pública**: obrigação contraída pelo Estado para financiar despesas
- **Políticas Fiscais**: decisões governamentais que afetam a economia
- **Sustentabilidade da Dívida**: capacidade de o Estado pagar suas dívidas sem prejudicar sua capacidade de financiar suas atividades

### Referências legais
- Art. 100 da Constituição Federal
- ...

### Jurisprudência
- ADI 3578 MC
- ...

### Dicas de prova
- Entenda a relação entre políticas fiscais e dívida pública
- Conheça o conceito de sustentabilidade da dívida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.113 (2)", "page_number": 113, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 100 da Constituição Federal", "..."], "jurisprudence": ["ADI 3578 MC", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T08:26:27.326218+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=113", "doc_key": "2165fbf01a16d44c4880519501df0763"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '91da0c7f4d30750dae317931e83d5ce1fb4d65b03415a465f9ade576768d4e69'),
  ('cpiuris2025::046f219094be56b4ae4d002005ef8d64', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Tribunais de Contas dos Municípios e Estados', '## Tribunais de Contas dos Municípios e Estados

A criação de Tribunais de Contas do Município é permitida pela CF/88, mas a criação de novos está vedada. Os Tribunais de Contas do Estado têm função diferente, fiscalizando todas as contas de um determinado Estado.

### Conceitos
- **Tribunal de Contas do Município**: Órgão municipal que atua na fiscalização das contas de um único Município
- **Tribunais de Contas dos Municípios**: Órgão estadual que atua na fiscalização das contas de todos os Municípios de determinado Estado

### Referências legais
- Art. 31, § 1º da CF/88
- Art. 31, § 4º da CF/88

### Jurisprudência
- MS 21.548
- ...

### Dicas de prova
- Diferenciar entre Tribunais de Contas do Município e dos Estados
- Entender a função específica de cada órgão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.114 (2)", "page_number": 114, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 31, § 1º da CF/88", "Art. 31, § 4º da CF/88"], "jurisprudence": ["MS 21.548", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T08:26:47.843896+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=114", "doc_key": "046f219094be56b4ae4d002005ef8d64"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '2b8bb402d8cd83302c56e7322b43ace7ec01fe3a537f30c3657b03ad9fd7b93e'),
  ('cpiuris2025::415ccddf0a9069f2201271e5accd9f72', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle da Atividade Financeira e Tribunais de Contas', '## Controle da Atividade Financeira e Tribunais de Contas

A Constituição Federal estabelece regras para o controle da atividade financeira, incluindo a fiscalização do Município e a competência dos Tribunais de Contas.

### Conceitos
- **Tribunal de Contas**: Órgão responsável por julgar as contas públicas
- **Princípio da Simetria**: Regra que estende as regras aplicáveis aos Tribunais de Contas da União a outros órgãos
- **Personalidade Jurídica**: A capacidade de um ente jurídico de contrair obrigações e ter direitos
- **Controle Externo**: Fiscalização do Município exercida pelo Poder Legislativo Municipal
- **Parecer Prévio**: Opinião emitida sobre as contas que o Prefeito deve anualmente prestar

### Referências legais
- Art. 70 da CF/88
- Art. 75 da CF/88
- Art. 31 da CF/88

### Dicas de prova
- Entenda o princípio da simetria e sua aplicação aos Tribunais de Contas
- Conheça a competência dos Tribunals de Contas e os órgãos de controle interno', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.114 (1)", "page_number": 114, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 70 da CF/88", "Art. 75 da CF/88", "Art. 31 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:27:25.326917+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=114", "doc_key": "415ccddf0a9069f2201271e5accd9f72"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'e9c4e2393404038ecc9286cd6a4a35bcc3a59779f75caaf926413af06b9bf07f'),
  ('cpiuris2025::3bf88dbb861d80bedb07e447656a7539', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Tribunal de Contas dos Municípios e Controle Externo', '## Tribunal de Contas dos Municípios e Controle Externo

O Tribunal de Contas dos Municípios é um órgão auxiliar das Câmaras Municipais que exerce controle externo sobre os Municípios. A CF/88 permite a criação de Tribunais de Contas dos Municípios, mas não proíbe a extinção mediante emenda à Constituição Estadual.

### Conceitos
- **Tribunal de Contas**: órgão que exerce controle externo sobre os Municípios
- **Controle Externo**: exercício de poder por ente diferente do Poder Executivo
- **Competência**: área de responsabilidade de um órgão ou tribunal
- **ADI 5763/CE**: ação direta de inconstitucionalidade

### Referências legais
- Art. 31, § 4º, da CF/88

### Jurisprudência
- Súmula 623 do STF

### Dicas de prova
- Entenda a competência dos Tribunais de Contas e a autonomia dos Municípios
- Conheça a diferença entre o controle externo e o controle interno', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.115 (1)", "page_number": 115, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 31, § 4º, da CF/88"], "jurisprudence": ["Súmula 623 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T08:28:43.642650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=115", "doc_key": "3bf88dbb861d80bedb07e447656a7539"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'fdcc9735c47a74530b5d761ef0ad8b9ba26265ce4aa6d195d4ff0b2a8ad93cd7'),
  ('cpiuris2025::5a94bb6c89b92e05a3a3e791b2a21b19', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Competência da Justiça Federal e Estadual em relação a verbas constitucionais', '## Competência da Justiça Federal e Estadual em relação a verbas constitucionais

A competência para processar e julgar prefeitos por desvio de verba transferida ao patrimônio municipal compete à Justiça Estadual, enquanto a competência da Justiça Federal prevalece quando o interesse federal não é prejudicado. Verbas constitucionais advindas do Fundo de Participação dos Municípios são exemplos de casos em que a competência é da Justiça Estadual.

### Conceitos
- **Competência Jurisdicional**: A capacidade do Poder Judiciário de decidir sobre questões legais
- **Justiça Federal**: A Justiça que tem competência para julgar questões relacionadas à União ou aos Estados
- **Justiça Estadual**: A Justiça que tem competência para julgar questões relacionadas aos Municípios
- **Verba Constitucional**: Verbas transferidas ao patrimônio dos Estados ou Municípios por meio de leis constitucionais

### Referências legais
- Art. 5º, XXXV da CF/88
- Súmula 209 do STJ
- Súmula 347 do STF

### Jurisprudência
- RE 123456
- MS 35.410

### Dicas de prova
- Entenda a competência jurisdicional e a diferença entre Justiça Federal e Estadual
- Conheça as verbas constitucionais e sua importância nos processos judiciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.116 (1)", "page_number": 116, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 5º, XXXV da CF/88", "Súmula 209 do STJ", "Súmula 347 do STF"], "jurisprudence": ["RE 123456", "MS 35.410"], "confidence": 0.8, "extracted_at": "2026-05-30T08:30:07.547560+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=116", "doc_key": "5a94bb6c89b92e05a3a3e791b2a21b19"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '962c63b7caa74910c2bdcc4c2082272729d2cd2fd20b452dba7d5b75a43822a4'),
  ('cpiuris2025::837d4b97315545e59df2a96d872c8fe5', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Competência da Justiça Federal e Estadual em Desvio de Verba', '## Competência da Justiça Federal e Estadual em Desvio de Verba

A Justiça Federal tem competência quando há interesse federal na matéria, especialmente se os recursos são fiscalizados por órgão federal. Já a Justiça Estadual é competente quando a verba incorpora-se ao patrimônio do Município.

### Conceitos
- **Competência da Justiça Federal**: A competência da Justiça Federal se manifesta quando há interesse federal na matéria
- **Fiscalização por órgão federal**: O interesse federal se manifesta quando os recursos são fiscalizados por órgão federal
- **Desvio de verba sujeita a prestação de contas perante órgão federal**: A competência da Justiça Federal é determinada pela presença de desvio de verba sujeita a prestação de contas perante órgão federal
- **Competência da Justiça Estadual**: A competência da Justiça Estadual se manifesta quando a verba incorpora-se ao patrimônio do Município
- **Incorporação de verba ao patrimônio do Município**: A competência da Justiça Estadual é determinada pela incorporação de verba ao patrimônio do Município
- **Prestação de contas perante órgão federal**: A presença de desvio de verba sujeita a prestação de contas perante órgão federal é um fator que determina a competência da Justiça Federal
- **Fiscalização por órgãos federais**: A fiscalização por órgãos federais é um indicador do interesse federal na matéria
- **Verba sujeita a prestação de contas**: A verba sujeita a prestação de contas é um fator que determina a competência da Justiça Federal

### Referências legais
- Súmula 208 do STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Perguntas sobre competência devem ser respondidas com base na presença ou ausência de interesse federal.
- A fiscalização por órgão federal é um indicador importante para determinar a competência da Justiça Federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.115 (2)", "page_number": 115, "discipline": "Direitos Financeiro", "legal_refs": ["Súmula 208 do STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T08:30:34.147822+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=115", "doc_key": "837d4b97315545e59df2a96d872c8fe5"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'a6991179e92b9106cb85bf168e5ab760f227946395960e64fb6639dd531989ff'),
  ('cpiuris2025::0f8991637b6a546a77d93f90e63d73e1', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Competência da Corte de Contas e Exercício de Poder Jurisdicional', '## Competência da Corte de Contas e Exercício de Poder Jurisdicional

A Corte de Contas tem competência para exercer suas atividades administrativas, sem usurpar as competências de outros órgãos, incluindo a jurisdicional. A deferimento ao Tribunal de Contas de controlar a constitucionalidade das leis acarreta um desrespeito à Constituição.

### Conceitos
- **Competência da Corte de Contas**: A competência para exercer atividades administrativas
- **Exercício de Poder Jurisdicional**: O poder de julgar sobre questões jurídicas
- **Constitucionalidade das Leis**: A validade das leis em relação à Constituição Federal

### Referências legais
- Art. 71 da Constituição Federal

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a competência da Corte de Contas e o exercício do poder jurisdicional
- Diferencie entre a constitucionalidade das leis e a validade em relação à Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.116 (2)", "page_number": 116, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 71 da Constituição Federal"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T08:30:46.515225+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=116", "doc_key": "0f8991637b6a546a77d93f90e63d73e1"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'ce2e64551b9af7f2368f5e2de9bb63b866287095f55d9a4262582eb4adc0cf07'),
  ('cpiuris2025::00334105e78f2f5b0656a02775d4719f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Legitimidade para cobrança de crédito', '## Legitimidade para cobrança de crédito

A legitimidade para a cobrança do crédito é do ente público que mantém o STJ, no caso o Estado de São Paulo, por meio de sua Procuradoria.

### Conceitos
- **Legitimidade**: Direito que determina quem pode agir em nome de outrem
- **Ente Público**: Instituição pública que exerce atividades de interesse público
- **Procuradoria**: Órgão do Estado responsável pela defesa dos interesses públicos

### Referências legais
- Art. 122 da Lei nº 9.532/1997
- ...

### Jurisprudência
- EAg 1.138.822/RS
- REsp 1.628.463/SP
- REsp 1.658.236/RS
- REsp 1408622/SP

### Dicas de prova
- Entendimento do STJ sobre legitimidade para cobrança
- Diferença entre o entendimento da 1ª Turma do STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.117 (2)", "page_number": 117, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 122 da Lei nº 9.532/1997", "..."], "jurisprudence": ["EAg 1.138.822/RS", "REsp 1.628.463/SP", "REsp 1.658.236/RS", "REsp 1408622/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T08:32:30.127860+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=117", "doc_key": "00334105e78f2f5b0656a02775d4719f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '91711f8b3ffd56c2b82fc0379dcc2dfecacddbc0d562220988a91d1be9a959db'),
  ('cpiuris2025::0005f7881992fd991f5aa2d75d75184e', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle da Atividade Financeira e Eficácia das Decisões dos Tribunais de Contas', '## Controle da Atividade Financeira e Eficácia das Decisões dos Tribunais de Contas

A postura do Tribunal de Contas é atenta contra o Poder Legislativo, Judiciário e STF, afirmando que a declaração incidental de inconstitucionalidade somente é permitida ao Poder Judiciário em pleno exercício de suas funções. Além disso, as decisões do Tribunal de Contas têm eficácia de título executivo, mas a competência para promover a cobrança é do ente público beneficiário da condenação.

### Conceitos
- **Declaração incidental de inconstitucionalidade**: Ação do Poder Judiciário para declarar a inconstitucionalidade de uma lei ou ato normativo
- **Título executivo**: Eficácia das decisões dos Tribunais de Contas, que se tornam obrigatórias para os entes públicos
- **Competência para cobrança**: A competência para promover a cobrança é do ente público beneficiário da condenação

### Referências legais
- Art. 71, § 3º, da CF/88

### Jurisprudência
- Súmula 284/STF
- Súmula 347/STF

### Dicas de prova
- Entenda a diferença entre declaração incidental de inconstitucionalidade e ação direta de constitucionalidade
- Conheça a regra da eficácia de título executivo das decisões dos Tribunais de Contas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.117 (1)", "page_number": 117, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 71, § 3º, da CF/88"], "jurisprudence": ["Súmula 284/STF", "Súmula 347/STF"], "confidence": 0.8, "extracted_at": "2026-05-30T08:32:56.222227+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=117", "doc_key": "0005f7881992fd991f5aa2d75d75184e"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'c1580a7f397071f1ff28139b9502295a286d105452569ba567bc0ae9189da925'),
  ('cpiuris2025::8977503c7b0c719fe1f2c37400835037', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Competência do Tribunal de Contas e Execução de Acórdãos', '## Competência do Tribunal de Contas e Execução de Acórdãos

A competência do Tribunal de Contas é estabelecida pela Constituição Federal de 1988, que determina suas atribuições em relação às contas do Presidente da República. O Tribunal de Contas tem legitimidade para cobrança apenas no caso de prejudicado ao erário, e não detém legitimidade para promover a execução de acórdãos.

### Conceitos
- **Competência do Tribunal de Contas**: Atribuições do Tribunal de Contas em relação às contas do Presidente da República
- **Legitimidade para cobrança**: O ente público prejudicado ao erário tem legitimidade para cobrança, mas não o ente que mantém o Tribunal de Contas
- **Execução de acórdãos**: A execução de acórdãos do Tribunal de Contas não é feita mediante procedimento de execução fiscal

### Referências legais
- Art. 71, § 3º da CF/88
- Súmula 643 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência do Tribunal de Contas

### Dicas de prova
- Distinção entre legitimidade para cobrança e execução de acórdãos
- Entendimento da competência do Tribunal de Contas em relação às contas do Presidente da República', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.118 (1)", "page_number": 118, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 71, § 3º da CF/88", "Súmula 643 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência do Tribunal de Contas"], "confidence": 0.8, "extracted_at": "2026-05-30T08:33:23.549235+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=118", "doc_key": "8977503c7b0c719fe1f2c37400835037"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '57597e64e5ff043b06dfedb6b51917c5c76708e5aa2125aa2d34b71f838ddedc'),
  ('cpiuris2025::fe4382715b583c09275135ae29b88220', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Repercussão Geral no Direito Financeiro', '## Repercussão Geral no Direito Financeiro

A questão de repercussão geral está pendente de julgamento pela STF, com decisões recentes como ARE 641.896 RG e REsp. 1.464.226-MA.

### Conceitos
- **Repercussão Geral**: Condição necessária para que uma questão seja julgada pelo STF
- **ARE**: Ação de Revisão Especial do Supremo Tribunal Federal
- **STJ**: Superior Tribunal de Justiça
- **REsp**: Recurso Especial do Superior Tribunal de Justiça
- **Poder Legislativo**: Unidade do Poder Executivo e do Poder Judiciário no Brasil
- **Turma**: Unidade composta por juízes que julgam um caso específico

### Referências legais
- Art. 102 da CF
- Súmula 641/STF

### Jurisprudência
- ARE 641.896 RG
- REsp. 1.464.226-MA
- REsp. 1.390.993/RJ

### Dicas de prova
- Entenda a importância da Repercussão Geral no Direito Financeiro
- Conheça as diferentes instâncias do Poder Judiciário brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.118 (2)", "page_number": 118, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 102 da CF", "Súmula 641/STF"], "jurisprudence": ["ARE 641.896 RG", "REsp. 1.464.226-MA", "REsp. 1.390.993/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T08:34:53.009215+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=118", "doc_key": "fe4382715b583c09275135ae29b88220"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'bb0fd1ff2b6924ee6e8645e8df7329b1ae16a23a91231ac2559cf7c73529e1a7'),
  ('cpiuris2025::7b04a4301def738e762fd988af5a4f9b', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Eficácia imediata das contas', '## Eficácia imediata das contas

As contas terão eficácia imediata a partir de sua edição, mas somente cessarão se houver decisão de 2/3 dos membros do Poder Legislativo local.

### Conceitos
- **Eficácia imediata**: aplicação imediata das contas após sua edição
- **Decisão de 2/3**: necessidade de decisão de dois terços do Poder Legislativo local para extinguir a eficácia das contas

### Referências legais
- Art. 71 da Constituição Federal
- Art. 166, § 1º, I, da CRFB/88

### Jurisprudência
- RE 729.744

### Dicas de prova
- Entenda a diferença entre eficácia imediata e decisão de 2/3
- Conheça o artigo 71 da Constituição Federal e seu impacto nas contas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.119 (2)", "page_number": 119, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 71 da Constituição Federal", "Art. 166, § 1º, I, da CRFB/88"], "jurisprudence": ["RE 729.744"], "confidence": 0.8, "extracted_at": "2026-05-30T08:35:12.253642+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=119", "doc_key": "7b04a4301def738e762fd988af5a4f9b"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '30deaede1eae8b23fb48a7e951857aa43cdff8f130d326f21bd00ba2c50a199c'),
  ('cpiuris2025::0c1360653d8f3985ea1d9e68657e1fef', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle da Atividade Financeira e Contas do Chefe do Executivo', '## Controle da Atividade Financeira e Contas do Chefe do Executivo

O Presidente da República deve prestar contas ao Congresso Nacional em até 60 dias após a abertura da sessão legislativa, de acordo com o art. 84, XXIV, da CF/88. O Tribunal de Contas pode emitir parecer prévio que não vincula o Poder Legislativo, exceto no âmbito municipal.

### Conceitos
- **Parecer Prévio**: Opinião do Tribunal de Contas sobre as contas do Chefe do Executivo
- **Vinculação**: O Poder Legislativo está vinculado ao parecer prévio do Tribunal de Contas em certos casos
- **Controle da Atividade Financeira**: A responsabilidade do Estado em controlar a atividade financeira dos órgãos do Poder Executivo

### Referências legais
- Art. 84, XXIV, da CF/88
- Art. 71, I, da CF/88
- Art. 31, § 2º, da CF/88
- Art. 51, II, da CF/88

### Jurisprudência
- RE 597.362
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre o parecer prévio opinativo e vinculante do Tribunal de Contas
- Conheça as hipóteses em que o Poder Legislativo está vinculado ao parecer prévio do Tribunal de Contas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.119 (1)", "page_number": 119, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 84, XXIV, da CF/88", "Art. 71, I, da CF/88", "Art. 31, § 2º, da CF/88", "Art. 51, II, da CF/88"], "jurisprudence": ["RE 597.362", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T08:35:49.040277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=119", "doc_key": "0c1360653d8f3985ea1d9e68657e1fef"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'cce7162f7e80ad532216f8349553d0dd02bd6e13864cc8f1d80db1da3bf48f64'),
  ('cpiuris2025::5b8e33bd9b0176c927d81374eed65107', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle dos atos de pessoal e responsabilidade administrativa', '## Controle dos atos de pessoal e responsabilidade administrativa

O Tribunal de Contas tem a competência para controlar os atos de admissão de pessoal na administração pública, incluindo cargos efetivos. A responsabilidade administrativa inclui também o ato doloso de deixar de prestar contas quando estiver obrigado por lei.

### Conceitos
- **Tribunal de Contas**: órgão responsável pelo controle interno da administração pública
- **admissão de pessoal**: processo de seleção e contratação de funcionários públicos
- **cargo efetivo**: cargo público com direito a remuneração e benefícios
- **concurso público**: processo de seleção de funcionários públicos por meio de exame

### Referências legais
- Art. 71, III, da CF/88
- Art. 11, VI, da Lei n.º 8.429/1992

### Jurisprudência
- 75 STF. Plenário. RE 729.744/MG
- RE 123456 (Tema repetitivo)

### Dicas de prova
- Entenda a competência do Tribunal de Contas e a responsabilidade administrativa nos atos de admissão de pessoal.
- Conheça as diferenças entre cargo efetivo e concurso público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.120 (2)", "page_number": 120, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 71, III, da CF/88", "Art. 11, VI, da Lei n.º 8.429/1992"], "jurisprudence": ["75 STF. Plenário. RE 729.744/MG", "RE 123456 (Tema repetitivo)"], "confidence": 0.8, "extracted_at": "2026-05-30T08:37:40.502063+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=120", "doc_key": "5b8e33bd9b0176c927d81374eed65107"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '322505ebe511eeb78144c1ee1f9938ee6936310158cf120088ba6dbe2f9974b0'),
  ('cpiuris2025::9db7a46332fc689fa4d450dc2608db88', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle da Atividade Financeira e Tributação', '## Controle da Atividade Financeira e Tributação

O Tribunal de Contas não precisa de prazo para apreciar a legalidade do ato de concessão inicial de aposentadorias, reformas e pensões, exceto na hipótese de prescrição.

### Conceitos
- **Contraditório**: O direito ao contraditório é o direito de ser ouvido antes da decisão que afeta os seus interesses.
- **Ampla Defesa**: O direito à ampla defesa é o direito de ter um advogado ou representante para defender os seus interesses.
- **Prescrição**: A prescrição é a perda do direito de agir em virtude de um prazo determinado que se esgota com o passar do tempo.

### Referências legais
- Decreto-Lei n.º 20.910/1932, art. 1º

### Jurisprudência
- Súmula Vinculante n.º 3 STF

### Dicas de prova
- Entenda a diferença entre o contraditório e a ampla defesa.
- Conheça a prescrição e como ela se aplica ao caso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.121 (1)", "page_number": 121, "discipline": "Direitos Financeiro", "legal_refs": ["Decreto-Lei n.º 20.910/1932, art. 1º"], "jurisprudence": ["Súmula Vinculante n.º 3 STF"], "confidence": 0.8, "extracted_at": "2026-05-30T08:37:50.725620+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=121", "doc_key": "9db7a46332fc689fa4d450dc2608db88"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'a68fab61d7bd4fd1f4248841afb6542f4650c23ca7689cf73fd0746e0e2fa1c0'),
  ('cpiuris2025::edebdc4cd6bc51334dc52b3f2b9cbae2', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle da Atividade Financeira e Julgamento de Contas', '## Controle da Atividade Financeira e Julgamento de Contas

A Câmara de Vereadores não pode julgar fictamente as contas do chefe do Poder Executivo local por decurso de prazo, pois isso é exclusiva do Poder Legislativo. O Tribunal de Contas tem competência para julgar as contas dos administradores e responsáveis por valores públicos, mas seu parecer não é vinculativo.

### Conceitos
- **Competência**: A capacidade ou autoridade de uma entidade para agir em um determinado assunto
- **Julgamento de Contas**: O processo pelo qual o Tribunal de Contas avalia as contas dos administradores e responsáveis por valores públicos
- **Parecer Técnico**: Opinião do Tribunal de Contas sobre uma questão específica, que não é vinculativa
- **Decurso de Prazo**: O período durante o qual um processo ou procedimento está pendente
- **Vinculação**: A obrigação de cumprir uma determinada ação ou decisão

### Referências legais
- Art. 71 da CF/88
- Súmula 736 do STF

### Jurisprudência
- RE 729744
- ACÓRDÃO ELETRÔNICO REPERCUSSÃO GERAL - MÉRITO DJe-186 DIVULG 22-08-2017 PUBLIC 23-08-2017

### Dicas de prova
- Entenda a competência do Tribunal de Contas e da Câmara de Vereadores
- Conheça a diferença entre julgamento e parecer técnico
- Avalie o conceito de decurso de prazo e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.120 (1)", "page_number": 120, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 71 da CF/88", "Súmula 736 do STF"], "jurisprudence": ["RE 729744", "ACÓRDÃO ELETRÔNICO REPERCUSSÃO GERAL - MÉRITO DJe-186 DIVULG 22-08-2017 PUBLIC 23-08-2017"], "confidence": 0.8, "extracted_at": "2026-05-30T08:37:53.004458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=120", "doc_key": "edebdc4cd6bc51334dc52b3f2b9cbae2"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '584f43e1a6d3c6d76cad173d9448fa54bd87d9e8c39b4093a7ba82e649f66b0c'),
  ('cpiuris2025::b00b8f34570411cdafba68bd0d33176f', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Eficácia de decisões do Tribunal de Contas', '## Eficácia de decisões do Tribunal de Contas

As decisões do Tribunal de Contas que imputam débito ou multa têm eficácia de título executivo, com distinção entre transmissibilidade das sanções às sucessores.

### Conceitos
- **Título Executivo**: Decisão com eficácia de título executivo
- **Transmissibilidade**: Permissão para a passagem de direitos ou obrigações para outros
- **Multa**: Sanção punitiva que não pode exceder a pessoa do infrator
- **Débito**: Obligação de pagar uma quantia

### Referências legais
- Art. 5º, XLV da CF/88
- Art. 5º, VIII da Lei n.º 8.443/1992

### Jurisprudência
- ACórdão n.º 92/1999 do Tribunal de Contas da União

### Dicas de prova
- Distinção entre transmissibilidade das sanções às sucessores
- Diferença entre multa e débito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.122 (2)", "page_number": 122, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 5º, XLV da CF/88", "Art. 5º, VIII da Lei n.º 8.443/1992"], "jurisprudence": ["ACórdão n.º 92/1999 do Tribunal de Contas da União"], "confidence": 0.8, "extracted_at": "2026-05-30T08:39:56.655087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=122", "doc_key": "b00b8f34570411cdafba68bd0d33176f"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '2da05c3f1eae70d5636bada8f359ef43136c533215aaad79b66d7e5171449a70'),
  ('cpiuris2025::e8e936318c05391b8536f510bd364dc8', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Prazo para apreciação do Tribunal de Contas', '## Prazo para apreciação do Tribunal de Contas

O prazo para apreciação do Tribunal de Contas é de 5 anos, contados da chegada do processo à Corte. A consequência de ultrapassar esse prazo é a impossibilidade de rever o ato inicial, considerando a aposentadoria, a reforma e a pensão definitivamente registradas.

### Conceitos
- **Prazo para apreciação**: Período dentro do qual o Tribunal de Contas deve julgar a legalidade de um ato
- **Contraditório e ampla defesa**: Direito do interessado ser ouvido antes da decisão final
- **Registro definitivo**: Atividade processual que confirma a decisão final

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 636.553/RS

### Dicas de prova
- Entenda o conceito de prazo para apreciação e suas consequências
- Conheça a importância do contraditório e da ampla defesa no processo administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.121 (2)", "page_number": 121, "discipline": "Direitos Financeiro", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 636.553/RS"], "confidence": 0.8, "extracted_at": "2026-05-30T08:40:09.530355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=121", "doc_key": "e8e936318c05391b8536f510bd364dc8"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '7906330d1bf8ec6b41196c4e9c7fbab43979b9c7b3453ffdc3caa2f967ce9737'),
  ('cpiuris2025::d09d4e14bad624036035decaacb4d1bd', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle da Atividade Financeira e Atribuições do Tribunal de Contas', '## Controle da Atividade Financeira e Atribuições do Tribunal de Contas

O artigo 71 da Constituição Federal estabelece as atribuições do Tribunal de Contas, incluindo a fiscalização contábil, financeira e orçamentária, além de aplicar sanções em caso de ilegalidade ou irregularidade.

### Conceitos
- **Atribuição do Tribunal de Contas**: O Tribunal de Contas tem atribuições para realizar fiscalizações contábeis, financeiras e orçamentárias.
- **Fiscalização contábil**: Verificação da observância das normas contábeis e financeiras.
- **Atribuição sancionatória**: O Tribunal de Contas tem o poder de aplicar sanções em caso de ilegalidade ou irregularidade.
- **Sanção proporcional ao dano**: Multa aplicada com base no dano causado ao erário.
- **Título executivo extrajudicial**: Um título que permite a execução de uma obrigação sem necessidade de processo judicial.
- **Controle externo das contas públicas**: Atribuição do Congresso Nacional para controlar as contas públicas.
- **Fiscalização das contas nacionais de empresas supranacionais**: O Tribunal de Contas fiscaliza as contas de empresas que têm capital social da União.
- **Recurso repassado pela União**: Um recurso financiado pela União para ser utilizado por um Estado, Distrito Federal ou Município.

### Referências legais
- Art. 71 da CF/88

### Dicas de prova
- Entenda a importância do controle externo das contas públicas e as atribuições do Tribunal de Contas.
- Conheça as diferentes formas de fiscalização contábil, financeira e orçamentária.
- Aprenda a aplicar sanções em caso de ilegalidade ou irregularidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.122 (1)", "page_number": 122, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 71 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:41:27.012018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=122", "doc_key": "d09d4e14bad624036035decaacb4d1bd"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'd4473393706783e8939db0df374457056a00faa20b4990956f0fc98164d37244'),
  ('cpiuris2025::f5db3a0420f4612f349347c6a894149c', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Prescritibilidade das ações de ressarcimento', '## Prescritibilidade das ações de ressarcimento

A prescritibilidade das ações de ressarcimento não é aplicada indistintamente e depende do tipo de ilícito. Ato doloso capitulado como improbidade administrativa é exceção, enquanto os outros casos têm prazo de 5 anos.

### Conceitos
- **Imprescritibilidade**: A presença de um prazo de prescrição para ações de ressarcimento
- **Prazo de prescrição**: O período durante o qual uma ação não pode ser proposta
- **Ilícitos administrativos**: Atos que causam prejuízos ao erário e são considerados ilegais
- **Ilícitos civis**: Atos que causam danos a terceiros e são considerados ilegais
- **Tribunal de Contas**: O órgão responsável por controlar as contas públicas
- **Poder geral de cautela**: A capacidade do Tribunal de Contas de tomar medidas para proteger o patrimônio público

### Referências legais
- Art. 37, § 5º, da CF/88
- Súmula Nº 476 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Prescritibilidade das ações de ressarcimento

### Dicas de prova
- Entenda a diferença entre ilícitos administrativos e civis
- Conheça o papel do Tribunal de Contas no controle das contas públicas
- Aprenda sobre o poder geral de cautela do Tribunal de Contas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.123 (1)", "page_number": 123, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 37, § 5º, da CF/88", "Súmula Nº 476 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Prescritibilidade das ações de ressarcimento"], "confidence": 0.8, "extracted_at": "2026-05-30T08:43:06.119943+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=123", "doc_key": "f5db3a0420f4612f349347c6a894149c"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', 'ac25f0cc6e820c3632428082cb80e9fd3f02078621bfb3aaf57046a3705237ed'),
  ('cpiuris2025::0e40102c7f4068e15c65549095502fde', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Concessão de medidas cautelares pelo Tribunal de Contas', '## Concessão de medidas cautelares pelo Tribunal de Contas

O Tribunal de Contas pode conceder medidas cautelares sem audiência da parte contrária, desde que necessárias à neutralização imediata de situações que possam causar lesão ao interesse público ou garantir a utilidade prática do processo.

### Conceitos
- **Tribunal de Contas**: órgão responsável por controlar o uso dos recursos públicos
- **medidas cautelares**: ações temporárias para evitar danos ao interesse público ou garantir a utilidade prática do processo
- **competência do TCU**: o Tribunal de Contas tem competência para decretar medidas cautelares em procedimentos de apuração
- **indisponibilidade dos bens**: medida cautelar que impede o responsável por dispor de seus bens durante um prazo não superior a 1 ano
- **constitucionalidade**: a questão de saber se uma lei ou ato é compatível com a Constituição
- **STF**: Superior Tribunal Federal, órgão máximo do Poder Judiciário brasileiro
- **Tribunal de Contas da União**: órgão responsável por controlar o uso dos recursos públicos na União

### Referências legais
- Art. 44 da Lei n.º 8.443/1992

### Jurisprudência
- RE 852.475/SP
- RE 669.069/MG
- REXT 636.886
- REsp. 1.390.993/RJ

### Dicas de prova
- Entenda a competência do TCU e as medidas cautelares que pode conceder.
- Conheça a constitucionalidade da previsão legal sobre indisponibilidade dos bens.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.123 (2)", "page_number": 123, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 44 da Lei n.º 8.443/1992"], "jurisprudence": ["RE 852.475/SP", "RE 669.069/MG", "REXT 636.886", "REsp. 1.390.993/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T08:43:19.301026+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=123", "doc_key": "0e40102c7f4068e15c65549095502fde"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '8deac484a3846a35b263273f867307f24cfda4d01fae981e1ccdf8c9713b8bb0'),
  ('cpiuris2025::d978ea1b9ddb6513c5888117a67a0f02', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle da Atividade Financeira e Crédito Público', '## Controle da Atividade Financeira e Crédito Público

A Constituição Federal estabelece limites para a contratação de empréstimos por instituições financeiras, especialmente para o pagamento de despesas com pessoal ativo e inativo.

### Conceitos
- **Contratação de empréstimos**: A contratação de empréstimos por instituições financeiras
- **Despesas correntes**: Despesas que podem ser pagas com empréstimos
- **Despesas de capital**: Despesas que não podem ser pagas com empréstimos
- **Instituições financeiras estatais**: Instituições financeiras que recebem empréstimos do Estado para pagamento de despesas

### Referências legais
- Art. 167, III da CF
- Art. 167, X da CF
- Lei nº 7.529/2017, art. 2º, § 2º

### Jurisprudência
- ADI 5683
- RE 636553

### Dicas de prova
- Entenda a distinção entre despesas correntes e de capital
- Conheça as limitações da contratação de empréstimos por instituições financeiras estatais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.124 (1)", "page_number": 124, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 167, III da CF", "Art. 167, X da CF", "Lei nº 7.529/2017, art. 2º, § 2º"], "jurisprudence": ["ADI 5683", "RE 636553"], "confidence": 0.8, "extracted_at": "2026-05-30T08:44:04.608820+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=124", "doc_key": "d978ea1b9ddb6513c5888117a67a0f02"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '742b1b9c33e2e9a6405aa391c670fdaf3be5af9dc7682b118a6c159b5bbfab5e'),
  ('cpiuris2025::414be32a86a0a08d82557215391fabf7', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Reserva de Iniciativa Legislativa', '## Reserva de Iniciativa Legislativa

A reserva de iniciativa para deflagrar o processo legislativo é assegurada às Cortes de Contas pela Lei Maior do país, e não pode ser contornada por meio de emenda à constituição estadual.

### Conceitos
- **Reserva de Iniciativa Legislativa**: Prerrogativa assegurada às Cortes de Contas
- **Lei Maior**: Constituição da República
- **Iniciativa Legislativa**: Direito do Poder Legislativo iniciar o processo legislativo

### Referências legais
- Art. 73 da Constituição da República
- Art. 75 da Constituição da República
- Art. 96, II, da Constituição da República

### Jurisprudência
- ADI 5323
- Súmula N da STF

### Dicas de prova
- Entenda a reserva de iniciativa legislativa e sua importância nas Cortes de Contas.
- Diferencie entre emenda à constituição estadual e reservada de iniciativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.124 (2)", "page_number": 124, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 73 da Constituição da República", "Art. 75 da Constituição da República", "Art. 96, II, da Constituição da República"], "jurisprudence": ["ADI 5323", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-30T08:45:15.170020+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=124", "doc_key": "414be32a86a0a08d82557215391fabf7"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '286820575f4be22dc795893792d83289da7e585f251d4cb4067e9ca1eaba9c0b'),
  ('cpiuris2025::2ada99c86c9fc2cb8c8e05eeb3d77c7e', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Índice de Ações Diretas de Inconstitucionalidade e Acórdãos', '## Índice de Ações Diretas de Inconstitucionalidade e Acórdãos

Lista de ações diretas de inconstitucionalidade e acórdãos relacionados a diversas leis e constituições brasileiras.

### Conceitos
- **Ação Direta de Inconstitucionalidade**: Procedimento jurídico que visa declarar inconstitucional uma lei ou ato do Poder Executivo.
- **Acórdão**: Decisão final do Tribunal Superior Eleitoral (TSE) em um processo eleitoral.

### Referências legais
- Art. 102 da Constituição Federal de 1988
- Súmula 634/STF

### Jurisprudência
- ADI 2037
- Acórdão n.º 92/1999

### Dicas de prova
- Entenda a diferença entre Ação Direta de Inconstitucionalidade e Recurso Extraordinário.
- Conheça as principais decisões do TSE em acórdãos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf", "source_ref": "IURIS - Direitos Financeiro - 2025.pdf · p.127", "page_number": 127, "discipline": "Direitos Financeiro", "legal_refs": ["Art. 102 da Constituição Federal de 1988", "Súmula 634/STF"], "jurisprudence": ["ADI 2037", "Acórdão n.º 92/1999"], "confidence": 0.8, "extracted_at": "2026-05-30T08:46:02.095922+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Financeiro - 2025.pdf#page=127", "doc_key": "2ada99c86c9fc2cb8c8e05eeb3d77c7e"}'::jsonb, '{"materia": "Direitos Financeiro"}'::jsonb, 'cp_iuris_2025', '6490a17df2a61aadb99d8aa37212ab9036c947079266ce7a60ebfc10be502a40'),
  ('cpiuris2025::8aa480f49a782f2442b95a8826d766f5', 'doutrina', 'cp_iuris', 'Direitos Financeiro — Controle da Execução Orçamentária', '## Controle da Execução Orçamentária

O controle da execução orçamentária é composto por controles internos e externo, com a verificação de legalidade prévia dos atos de execução orçamentária.

### Conceitos
- **Controle Interno**: Verificação de legalidade prévia dos atos de execução orçamentária
- **Controle Externo**: Exercício do controle da execução orçamentária pelo Poder Executivo, Tribunal de Contas ou órgão equivalente
- **Legalidade**: Verificação se os atos de execução orçamentária estão em conformidade com a lei

### Referências legais
- Art. 29, § 2º, da LRF
- Art. 29, § 1º, da LRF
- Art. 29, II, da LRF
- Art. 29, IV, da LRF
- Art. 29, § 3º, da LRF
- Art. 75, Lei n.º 4.320/64
- Art. 76, Lei n.º 4.320/64
- Art. 77, Lei n.º 4.320/64

### Jurisprudência
- TCM-RJ - Procurador (FCC 2015)

### Dicas de prova
- Entenda a distinção entre controle interno e externo da execução orçamentária
