  ('cpiuris2025::b090656b08e6c4f822bfd95d3c066580', 'doutrina', 'cp_iuris', 'Direitos Humanos — Introdução aos Direitos Humanos', '## Introdução aos Direitos Humanos

Resumo objetivo: Este texto apresenta uma introdução aos direitos humanos, destacando a importância desses direitos na sociedade moderna.

### Conceitos
- **Direitos Humanos**: São direitos inalienáveis e fundamentais à dignidade humana.
- **Dignidade Humana**: É o valor fundamental que sublinha a importância dos direitos humanos.

### Referências legais
- Constituição da República
- Lei nº 9.387, de 2 de maio de 1996

### Dicas de prova
- Entenda a importância dos direitos humanos na sociedade moderna.
- Destaque a dignidade humana como o valor fundamental que sublinha os direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.2", "page_number": 2, "discipline": "Direitos Humanos", "legal_refs": ["Constituição da República", "Lei nº 9.387, de 2 de maio de 1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:47:36.234616+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=2", "doc_key": "b090656b08e6c4f822bfd95d3c066580"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '8152e50406dc248d38be7931a130cf492bcce042e47d715a91ab51c82856bc4e'),
  ('cpiuris2025::46b61e267e8c574030b1ab8a529c45d5', 'doutrina', 'cp_iuris', 'Direitos Humanos — Biografia do Autor', '## Biografia do Autor

