- Identifique o título e a instituição que concedeu o doutorado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.3", "page_number": 3, "discipline": "Direitos Humanos", "legal_refs": [], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:48:12.644031+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=3", "doc_key": "46b61e267e8c574030b1ab8a529c45d5"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '449b155dd382fc808e522650292d4ea05b12efe9b32780ae18dbd8231d766a0a'),
  ('cpiuris2025::b48ecee1adb1d03865de86dd0dd1a654', 'doutrina', 'cp_iuris', 'Direitos Humanos — Teoria Geral dos Direitos Humanos', '## Teoria Geral dos Direitos Humanos

O capítulo aborda a teoria geral dos direitos humanos, destacando as fases evolutivas do conceito de homem e os principais antecedentes históricos e teóricos.

### Conceitos
- **Conceito de Homem**: Entendido como um conceito dinâmico e evolutivo
- **Fases Evolutivas do Conceito de Homem**: Divisão em quatro fases: Axial, Medieval, Ética Kantiana e Existencialista

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a evolução do conceito de homem ao longo da história
- Conheça as principais teorias do direito e suas influências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.4 (1)", "page_number": 4, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:48:45.761902+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=4", "doc_key": "b48ecee1adb1d03865de86dd0dd1a654"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ee993a8ce21ca89495af58406cc0666a2a49e1afbad9cbae47a9efdc07d91b91'),
  ('cpiuris2025::52b606e74475a4aaac794b0f9fafbf45', 'doutrina', 'cp_iuris', 'Direitos Humanos — Aplicabilidade imediata dos direitos humanos', '## Aplicabilidade imediata dos direitos humanos

Discute a aplicabilidade imediata dos direitos humanos, destacando sua relevância e importância no contexto jurídico.

### Conceitos
- **Direitos Humanos**: Conjunto de direitos inerentes à dignidade humana
- **Aplicabilidade imediata**: A capacidade dos direitos humanos de serem aplicados diretamente e sem necessidade de ação adicional

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de aplicabilidade imediata dos direitos humanos e sua importância na jurisprudência.
- Destaque a relevância da aplicabilidade imediata para garantir a eficácia dos direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.4 (3)", "page_number": 4, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T08:49:24.532694+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=4", "doc_key": "52b606e74475a4aaac794b0f9fafbf45"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a48f0499058d8e85c92d1a84bce68fe8d1241cafcc6d9ae05ddd8e8b0feb0200'),
  ('cpiuris2025::323a7f33328f12d8c1fb0fe0baaf9c9f', 'doutrina', 'cp_iuris', 'Direitos Humanos — Características dos Direitos Humanos', '## Características dos Direitos Humanos

Resumo das características fundamentais dos Direitos Humanos, incluindo fundamentalidade, abstratividade e moralidade.

### Conceitos
- **Fundamentalidade**: A característica de ser um direito inalienável e inviolável
- **Abstratividade**: A capacidade de ser aplicado a situações hipotéticas, sem necessidade de especificação de casos concretos
- **Moralidade**: A característica de ser um direito que se baseia em princípios morais e éticos
- **Prioridade**: A ordem em que os direitos humanos devem ser respeitados e protegidos
- **Inalienabilidade**: A característica de não poder ser negado ou retirado a alguém
- **Irrenunciabilidade e imprescritibilidade**: A característica de não poder ser renunciado ou prescrito
- **Indivisibilidade**: A característica de que os direitos humanos são indivisíveis e interconectados
- **Interdependência**: A característica de que os direitos humanos se relacionam uns com os outros

### Referências legais
- Art. 5 da Constituição Federal

### Dicas de prova
- Entenda a distinção entre fundamentabilidade e abstratividade
- Conheça as características morais dos direitos humanos
- Aprenda a priorizar os direitos humanos em situações conflituantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.4 (2)", "page_number": 4, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:49:32.975265+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=4", "doc_key": "323a7f33328f12d8c1fb0fe0baaf9c9f"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '3afcb06a58999d122ad0630fa371e7e81768c9fabfbfb45fb27f2e2ea018059b'),
  ('cpiuris2025::71406c7098d9c7a09f6b4f34b69b9429', 'doutrina', 'cp_iuris', 'Direitos Humanos — Limites à implementação dos direitos sociais', '## Limites à implementação dos direitos sociais

Discute a teoria do mínimo existencial e do princípio da reserva do possível como limites para a implementação dos direitos sociais.

### Conceitos
- **Teoria do mínimo existencial**: teoria que estabelece que os direitos sociais têm um limite mínimo
- **Princípio da reserva do possível**: princípio que estabelece que os direitos sociais devem ser implementados com base na possibilidade real

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre as duas teorias
- Conheça a Resolução 29/9', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.4 (4)", "page_number": 4, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:50:57.577071+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=4", "doc_key": "71406c7098d9c7a09f6b4f34b69b9429"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ba9477a5a097d7247ed4dc9a24c587bbfff2dd6feefa5e2cef9c985acb243260'),
  ('cpiuris2025::72d62bf3daffc3e1b169d9cc279e6b8c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Internacionalização da Proteção dos Direitos Humanos', '## Internacionalização da Proteção dos Direitos Humanos

O texto discute a internacionalização da proteção dos direitos humanos, destacando os sistemas regionais e europeu de proteção, bem como o sistema africano.

### Conceitos
- **Internacionalização**: Processo pelo qual os direitos humanos são reconhecidos e protegidos em todo o mundo
- **Sistema Global de Proteção dos Direitos Humanos**: Regras e normas que regem a proteção dos direitos humanos em escala global
- **Onusiano**: Responsabilidade compartilhada por uma ação ou omissão de um Estado em relação aos direitos humanos

### Referências legais
- Art. XXVIII da Carta das Nações Unidas

### Dicas de prova
- Entenda a distinção entre onusiano e responsabilidade individual de um Estado
- Conheça os sistemas regionais e europeu de proteção dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Direitos Humanos", "legal_refs": ["Art. XXVIII da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:51:29.666864+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=5", "doc_key": "72d62bf3daffc3e1b169d9cc279e6b8c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '2b2713e36802499ee7d74b75ed9e2241f04411be050aa094ad92785b2db5008c'),
  ('cpiuris2025::b7e01c7422ac7cd07a99c4bd7742779e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção de Povos Indígenas', '## Proteção de Povos Indígenas

O capítulo aborda a proteção dos povos indígenas, incluindo o âmbito internacional e as normas de proteção.

### Conceitos
- **Povos Indígenas**: pessoas que habitam áreas remotas e têm uma cultura própria
- **Proteção Internacional**: normas e tratados internacionais que visam proteger os direitos dos povos indígenas
- **Normas de Proteção**: regras e leis que visam proteger os direitos e o bem-estar dos povos indígenas

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da proteção internacional para os povos indígenas
- Conheça as normas de proteção e seus objetivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T08:52:33.477477+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=5", "doc_key": "b7e01c7422ac7cd07a99c4bd7742779e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'eb8ae93c6622b87c8dcf0da1e11752dec3d0001ec4008f6a1b3183b7e3bb5a7c'),
  ('cpiuris2025::239a82757622d1061069900b6cf1546c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Processo Internacional dos Direitos Humanos', '## Processo Internacional dos Direitos Humanos

Discute o conceito, classificação dos mecanismos de apuração, justiciabilidade e os sistemas interamericanos de direitos humanos.

### Conceitos
- **Conceito**: Entendido como um conjunto de normas e mecanismos destinados a proteger e promover os direitos humanos.
- **Classificação dos mecanismos de apuração**: Divisão em mecanismos de apuração internacional, nacional e regional.
- **Justiciabilidade**: A capacidade de um direito ou norma ser objeto de uma ação judicial.
- **Sistemas Interamericanos de Direitos Humanos**: Organizações regionais que promovem e protegem os direitos humanos, como a OEA.
- **Tratados internacionais de direitos humanos**: Acordos entre países que estabelecem normas e mecanismos para proteger os direitos humanos.
- **Ratificação dos tratados internacionais de direitos humanos**: O processo pelo qual um país adota um tratado internacional de direitos humanos.
- **Deslocamento de competência**: A transferência da competência para apurar violações de direitos humanos de uma autoridade a outra.
- **Vedação absoluta**: Proibição total e absoluta da tortura em qualquer circunstância.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de processo internacional dos direitos humanos e sua classificação.
- Ajuste a definição de justiciabilidade ao contexto do texto.
- Identifique os sistemas interamericanos de direitos humanos mencionados no texto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T08:52:40.931357+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=5", "doc_key": "239a82757622d1061069900b6cf1546c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ccd4f5d1c5a06c5f360b35b93f9a2fccfd9111e0f9529c93b9d17304b4dfa876'),
  ('cpiuris2025::7e7a7cb25fc2c080bd0fc268adb0b0aa', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direitos dos Povos Indígenas', '## Direitos dos Povos Indígenas

O texto aborda a declaração das Nações Unidas sobre os direitos dos povos indígenas e a Convenção 169 da Organização Internacional do Trabalho, relacionando-se com as questões tribais.

### Conceitos
- **Direitos Humanos**: direitos fundamentais das pessoas
- **Povos Indígenas**: povos que habitam áreas remotas e têm uma cultura específica
- **Convenção 169**: convenção internacional que protege os direitos dos povos indígenas

### Referências legais
- Declaração das Nações Unidas sobre os Direitos dos Povos Indígenas

### Dicas de prova
- Entenda a importância da Convenção 169 e sua relação com os direitos humanos
