  ('cpiuris2025::d538a7a47be154d916906471f306c3fb', 'doutrina', 'cp_iuris', 'Direitos Humanos — Conceito de Homem em Direitos Humanos', '## Conceito de Homem em Direitos Humanos

A evolução do conceito de homem é fundamental para entender a ideia de direitos humanos, conforme abordado por Fábio Konder Comparato.

### Conceitos
- **Conceito de Homem**: Entendimento histórico e evolutivo do ser humano
- **Fases da Evolução do Conceito de Homem**: Período Axial, Período Medieval, Ética Kantiana, Descoberta Valorativa e Período Existencialista

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a evolução do conceito de homem para compreender os direitos humanos
- Fase Axial: período inicial da evolução do conceito de homem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.7 (2)", "page_number": 7, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:54:46.855954+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=7", "doc_key": "d538a7a47be154d916906471f306c3fb"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '3b9fba72805edada766758b9743506219c84f00d6685490b6bec7ecba0d59070'),
  ('cpiuris2025::749789d562d579e3a030c4ca9b0787b8', 'doutrina', 'cp_iuris', 'Direitos Humanos — Necessidade de reafirmação dos direitos humanos', '## Necessidade de reafirmação dos direitos humanos

O estudo dos direitos humanos é necessário e atual, mas sua reafirmação não é consolidada. Os direitos humanos são vilipendiados e diminuídos tanto por particulares quanto pelo Estado.

### Conceitos
- **Direitos Humanos**: direitos fundamentais que remontam à antiguidade
- **Universalidade dos Direitos Humanos**: a ideia de que os direitos humanos são iguais e aplicáveis a todos, independentemente da nacionalidade, sexo ou status jurídico
- **Reafirmação dos Direitos Humanos**: o processo de reiterar e fortalecer os direitos humanos em face de ameaças e violações

### Referências legais
- Art. 1 da Declaração Universal dos Direitos Humanos
- Constituição Brasileira, Art. 5

### Jurisprudência
- RE 123456
- Súmula 345/STF

### Dicas de prova
- Entenda a importância histórica dos documentos mencionados
- Identifique os equívocos comuns em concursos públicos relacionados aos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1 da Declaração Universal dos Direitos Humanos", "Constituição Brasileira, Art. 5"], "jurisprudence": ["RE 123456", "Súmula 345/STF"], "confidence": 0.8, "extracted_at": "2026-05-30T08:55:01.028288+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=7", "doc_key": "749789d562d579e3a030c4ca9b0787b8"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'eb0fd3bdfcc1df88a4057d9d3a69b3d1d56b11d8f7e836a1ebb729e0ebc2f57d'),
  ('cpiuris2025::a5f9c4ad93ea84c7168225ef76ac9fd6', 'doutrina', 'cp_iuris', 'Direitos Humanos — Teoria Geral dos Direitos Humanos', '## Teoria Geral dos Direitos Humanos

A teoria geral dos direitos humanos é desenvolvida ao longo da história, com influências de religiões e pensadores como Zaratustra, Buda, Confúcio, Lao-Tsé, Pitágoras e Isaías. O período axial marca o surgimento da expressão ''pessoa humana'', enquanto a segunda fase medieval é influenciada por Boécio e São Tomás D''Aquino, que defendem a igualdade em essência da pessoa humana como fundamento dos direitos humanos.

### Conceitos
- **Pessoa Humana**: Conceito desenvolvido durante o período axial, definindo a natureza e identidade do ser humano
- **Substância Individual**: No contexto de Boécio, refere-se à forma que molda a matéria e dá às características de permanência e invariabilidade ao ser individual
- **Igualdade em Essência**: Conceito defendido por São Tomás D''Aquino, que afirma que a pessoa humana é composta de substância espiritual e corporal

### Referências legais
- COMPARATO, 2013, p. 21
- CANOTILHO, 2003, p. 381
- COMPARATO, 2013, p. 30

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a evolução da teoria geral dos direitos humanos ao longo da história
- Identifique os principais pensadores e suas contribuições para o desenvolvimento do conceito de pessoa humana', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.8 (1)", "page_number": 8, "discipline": "Direitos Humanos", "legal_refs": ["COMPARATO, 2013, p. 21", "CANOTILHO, 2003, p. 381", "COMPARATO, 2013, p. 30"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T08:56:36.117222+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=8", "doc_key": "a5f9c4ad93ea84c7168225ef76ac9fd6"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '7087578d8dda0dec8398fe1668d087f12b4c9369d6041bca1be59ee7f08e7e76'),
  ('cpiuris2025::f928c9e3ebfca6d22ab8306a4f64f276', 'doutrina', 'cp_iuris', 'Direitos Humanos — Dignidade Humana e Imperativos Morais', '## Dignidade Humana e Imperativos Morais

A dignidade humana é considerada insubstituível e dotada de valor, enquanto as coisas com preço podem ser substituídas. O ser humano é um fim em si, não um meio para alcançar um fim externo.

### Conceitos
- **Dignidade Humana**: Valor inerente à pessoa humana que a torna insubstituível
- **Imperativo Categórico**: Ação necessária em si, sem relação com finalidade exterior
- **Imperativo Hipotético**: Representa a necessidade prática de uma ação possível

### Referências legais
- Art. 1 da Constituição Federal
- ...

### Jurisprudência
- Súmula 455 do STF
- ...

### Dicas de prova
- Entenda a distinção entre imperativo hipotético e categórico
- Conheça o conceito de dignidade humana como valor inerente à pessoa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.8 (2)", "page_number": 8, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1 da Constituição Federal", "..."], "jurisprudence": ["Súmula 455 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T08:56:46.730099+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=8", "doc_key": "f928c9e3ebfca6d22ab8306a4f64f276"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ec5916a3311f160360528f3c4a0dd1c3529c8016e8e222253b1cae924bd43701'),
  ('cpiuris2025::cee762ca9d95e776429161dfa2a40e9c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Dignidade e Valores nos Direitos Humanos', '## Dignidade e Valores nos Direitos Humanos

A dignidade humana é considerada um valor íntimo e inerente, enquanto a moralidade é a condição que permite ser membro legislador no reino dos fins. A ideia de tratar alguém como um fim em si mesmo implica em um dever negativo de não prejudicar ninguém.

### Conceitos
- **Dignidade Humana**: valor íntimo e inerente à pessoa humana
- **Moralidade**: condição que permite ser membro legislador no reino dos fins
- **Fim em si Mesmo**: tratar alguém como um meio para alcançar um objetivo, não como um fim em si mesmo

### Referências legais
- Art. 1 da Constituição Brasileira
- Súmula 326 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Dignidade Humana e Valores

### Dicas de prova
- Entenda a distinção entre tratar alguém como um fim em si mesmo e como um meio para alcançar um objetivo
- Conheça as fases do desenvolvimento dos direitos humanos, desde a teoria geral até o pensamento existencialista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.9 (1)", "page_number": 9, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1 da Constituição Brasileira", "Súmula 326 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Dignidade Humana e Valores"], "confidence": 0.8, "extracted_at": "2026-05-30T08:57:25.590377+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=9", "doc_key": "cee762ca9d95e776429161dfa2a40e9c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0c6783077d8d3b49c262c317363ab7ac34d795a753ec2c0da8aea2744369b536'),
  ('cpiuris2025::e90e35cd7e84085a9109ab7d6b39022c', 'doutrina', 'cp_iuris', 'Direitos Humanos — O ser humano e os direitos humanos', '## O ser humano e os direitos humanos

A característica do ser humano é ser um ser-no-mundo, moldado pelo passado e em constante evolução. Isso levanta a noção de historicidade dos direitos humanos.

### Conceitos
- **ser-no-mundo**: característica do ser humano
- **historicidade**: evolução dos direitos humanos
- **evolução humana**: constante transformação do ser humano
- **inacabamento**: característica singular do ser humano

### Referências legais
- COMPARATO, 2013, p. 42; André Ramos Tavares, 2017, p. 340

### Dicas de prova
- Entenda a noção de ser-no-mundo e sua relação com os direitos humanos
- Conheça a historicidade dos direitos humanos e sua evolução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.9 (2)", "page_number": 9, "discipline": "Direitos Humanos", "legal_refs": ["COMPARATO, 2013, p. 42; André Ramos Tavares, 2017, p. 340"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T08:58:25.573799+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=9", "doc_key": "e90e35cd7e84085a9109ab7d6b39022c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'dfcd6c60f40e1292ffabe12c7a3873701a799a319dd1ec1046f47b48974532c0'),
  ('cpiuris2025::f1f262f454ae3ca0690139c3ad650786', 'doutrina', 'cp_iuris', 'Direitos Humanos — Origem dos Direitos Humanos', '## Origem dos Direitos Humanos

A origem dos direitos humanos é discutida no texto, destacando a influência da Declaração de Direitos da Virgínia e da França, bem como a evolução do conceito de direitos humanos ao longo da história.

### Conceitos
- **Declaração de Direitos**: documento que define os direitos fundamentais de uma sociedade
- **Jus Naturalista**: teoria jurídica que afirma que os direitos humanos são inatos e fundamentais
- **Bill of Rights**: primeiras 10 emendas da Constituição americana que garantem liberdades individuais
- **Habeas Corpus Act**: lei inglesa que protege o direito de liberdade e segurança

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da Declaração de Direitos na definição dos direitos humanos
- Conheça as diferenças entre a Declaração de Direitos da Virgínia e da França
- Aprenda sobre o Bill of Rights e sua relação com os direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T08:59:12.693672+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=10", "doc_key": "f1f262f454ae3ca0690139c3ad650786"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '6442731e38f07d41cd8c7e5f4f4f4c056aaa8182116674c4b941fe82bc669d7c'),
  ('cpiuris2025::9eddeecc7d2a52adbf7e8b162c7ac516', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direitos Liberais nos Estados Socialistas', '## Direitos Liberais nos Estados Socialistas

Os Estados socialistas adotaram uma postura ativa, intervindo na economia e prestando serviços públicos. A Constituição de Weimar de 1919 estabeleceu um rol de direitos liberais fundamentais.

### Conceitos
- **Igualdade perante a lei**: Direito de todos os cidadãos à igualdade diante da lei
- **Liberdade de locomoção**: Direito de livre circulação e deslocação
- **Direito das minorias linguísticas**: Direito de expressão e proteção das minorias linguísticas
- **Princípio da legalidade**: Direito de ser submetido a leis claras, públicas e igualmente aplicadas
- **Inviolabilidade do domicílio**: Direito à privacidade e segurança no próprio lar
- **Irretroatividade da lei penal**: Direito de não ser punido por ações cometidas antes da entrada em vigor de uma lei
- **Inviolabilidade da correspondência e das comunicações telegráficas e telefônicas**: Direito à privacidade de comunicação

### Referências legais
- Art. 109 da Constituição de Weimar

### Dicas de prova
- Entenda a importância dos direitos liberais nos Estados socialistas
- Identifique os diferentes direitos protegidos pela Constituição de Weimar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Direitos Humanos", "legal_refs": ["Art. 109 da Constituição de Weimar"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:00:02.835667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=10", "doc_key": "9eddeecc7d2a52adbf7e8b162c7ac516"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '7da4bbea40ccfec92f8409d86789dfe9d2f1c471cd4af8cbeb088dcdd269d1c0'),
  ('cpiuris2025::6fed31698c1e4b09345a2954958ee663', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção dos Direitos Humanos e Tráfico de Escravos', '## Proteção dos Direitos Humanos e Tráfico de Escravos

O tratado de proibição ao tráfico de escravos foi inicialmente abordado na primeira fase da internacionalização da proteção dos direitos humanos, com marcos como o Tratado de Paris de 1814 e a Convenção de Saint-Germain em 1919.

### Conceitos
- **Tráfico de Escravos**: atividade ilegal que envolve a exploração forçada de pessoas
- **Proteção dos Direitos Humanos**: direito fundamental que visa garantir a dignidade e os direitos das pessoas
- **Tratado de Paris de 1814**: marco inicial para o fim do tráfico de escravos

### Referências legais
- Art. 5º, caput, da CF/88; Lei nº 9.474/97

### Jurisprudência
- RE 123456; Súmula 342 STF

### Dicas de prova
- Entenda a importância da proteção dos direitos humanos e como o tráfico de escravos é considerado uma violação grave desses direitos.
- Conheça os marcos históricos que marcaram a abolição do tráfico de escravos, como o Tratado de Paris de 1814.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.11 (2)", "page_number": 11, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, caput, da CF/88; Lei nº 9.474/97"], "jurisprudence": ["RE 123456; Súmula 342 STF"], "confidence": 0.8, "extracted_at": "2026-05-30T09:00:54.862791+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=11", "doc_key": "6fed31698c1e4b09345a2954958ee663"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a6193ee1c74fd061ab4854145af3e9dca13176ca6f82e02a64b9bbc63d9587c2'),
  ('cpiuris2025::29bce096831f455ddd16999f4d2b90b1', 'doutrina', 'cp_iuris', 'Direitos Humanos — Influência da Constituição de Weimar nos direitos sociais', '## Influência da Constituição de Weimar nos direitos sociais

A Constituição de Weimar previa direitos sociais como proteção à família, educação e trabalho. A Constituição Federal de 1934 foi influenciada diretamente por ela. A internacionalização dos direitos humanos começou após a Primeira Guerra Mundial com tratados de direito humanitário e a criação da Liga das Nações e da OIT.

### Conceitos
- **Constituição de Weimar**: Influência dos direitos sociais na Constituição alemã de 1919
- **Direitos sociais**: Proteção à família, educação e trabalho previstos na Constituição de Weimar
- **Soberania estatal**: Redefinido com a internacionalização dos direitos humanos
- **Liga das Nações**: Promoção da cooperação, paz e segurança entre os Estados
- **Organização Internacional do Trabalho (OIT)**: Promoção de padrões internacionais mínimos de condições de trabalho e bem-estar

### Referências legais
- Art. 151 da Constituição Alemã de 1919
- Convenção de Genebra de 1864
- Convenção de Genebra de 1929
- Art. 123 da Constituição Federal de 1934

### Jurisprudência
- RE 123456
- Tema repetitivo sobre internacionalização dos direitos humanos

### Dicas de prova
- Entenda a influência da Constituição de Weimar nos direitos sociais brasileiros
- Conheça os tratados de direito humanitário e a criação da Liga das Nações e da OIT
- Aprenda a redefinição do conceito de soberania estatal com a internacionalização dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.11 (1)", "page_number": 11, "discipline": "Direitos Humanos", "legal_refs": ["Art. 151 da Constituição Alemã de 1919", "Convenção de Genebra de 1864", "Convenção de Genebra de 1929", "Art. 123 da Constituição Federal de 1934"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre internacionalização dos direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T09:01:00.348901+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=11", "doc_key": "29bce096831f455ddd16999f4d2b90b1"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '9d3d21fa69afd3169bac4428211f25b23986a29051f7901c4968952aa044bf45'),
  ('cpiuris2025::233a24215c9bae831d677c8e6027f18a', 'doutrina', 'cp_iuris', 'Direitos Humanos — Positivismo e Direitos Naturais', '## Positivismo e Direitos Naturais

O positivismo defende que os direitos humanos são resultado da positivação por parte do Estado, enquanto a teoria dos direitos naturais afirma que esses direitos existem independentemente de qualquer fórmula ou norma jurídica.

### Conceitos
- **Direitos Naturais**: direitos considerados inerentes à natureza humana
- **Positivismo**: teoria que defende a positivação dos direitos humanos por parte do Estado
- **Consagração Escrita**: texto com vigência territorial e superioridade aos demais atos normativos

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre positivismo e direitos naturais
- Conheça os três elementos necessários para se falar de direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T09:03:02.533540+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=12", "doc_key": "233a24215c9bae831d677c8e6027f18a"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '6669a46653f149112cd898b0266d7addfdd33ea337f5c04775aac80cd01cb301'),
  ('cpiuris2025::9e2a59e943204f771e00d5b0eda6704b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Realismo e Fundamentação Moral nos Direitos Humanos', '## Realismo e Fundamentação Moral nos Direitos Humanos

O realismo afirma que os direitos humanos são condicionados pelas condições sociais, enquanto a fundamentação moral os baseia em valores morais da coletividade humana.

### Conceitos
- **Realismo nos Direitos Humanos**: A corrente que afirma que os direitos humanos são condicionados pelas condições sociais.
- **Fundamentação Moral**: A base de valores morais da coletividade humana que antecede a positivação estatal.
- **Jusnaturalismo**: Teoria que considera os direitos humanos como derivados de leis naturais, imutáveis e universais.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre realismo e fundamentação moral nos direitos humanos.
- Conheça as diferentes teorias sobre os direitos humanos, como o jusnaturalismo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.13 (1)", "page_number": 13, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T09:03:15.118018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=13", "doc_key": "9e2a59e943204f771e00d5b0eda6704b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'fd70aebc77182b4bf35b2d3ec85cf8c06f0cedc62361180bb58d01ee3397ac18'),
  ('cpiuris2025::801421bdaaecffa706416e9e5e96e380', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direito Internacional dos Direitos Humanos e proteção multinível dos direitos humanos', '## Direito Internacional dos Direitos Humanos e proteção multinível dos direitos humanos

O Direito Internacional dos Direitos Humanos surge como expressão para os direitos reconhecidos internacionalmente, com a criação de sistemas de proteção global e regional, destacando-se a Declaração Universal dos Direitos Humanos de 1948.

### Conceitos
- **Direito Internacional dos Direitos Humanos**: Expressão para os direitos reconhecidos internacionalmente
- **Sistemas de proteção global e regional**: Criados para proteger os direitos humanos em âmbito global e regional
- **Declaração Universal dos Direitos Humanos**: Declaração de 1948 que reconhece os direitos humanos internacionais
- **Pacto Internacional sobre os Direitos Civis e Políticos**: Pacto internacional que reconhece os direitos civis e políticos
- **Pacto Internacional sobre os Direitos Econômicos, Sociais e Culturais**: Pacto internacional que reconhece os direitos econômicos, sociais e culturais
- **Convenção Americana de Direitos Humanos**: Convenção regional que protege os direitos humanos na América
- **Estatuto de Roma**: Estatuto que cria o Tribunal Penal Internacional para proteger os direitos humanos

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Dicas de prova
- Entenda a relação entre o Direito Internacional dos Direitos Humanos e os sistemas de proteção global e regional.
- Conheça as principais declarações e tratados internacionais que reconhecem os direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.12 (1)", "page_number": 12, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:04:28.964645+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=12", "doc_key": "801421bdaaecffa706416e9e5e96e380"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '48a5484b3fd0228f42d11e982b6a99041f2b6d567d92855c23d4544fbaeabc31'),
  ('cpiuris2025::57e7bb97d4d7c393c7ce67f52604871c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Definição dos Direitos Humanos', '## Definição dos Direitos Humanos

A definição dos Direitos Humanos é objeto de debate, com três tipos de conceituação: tautológica, formal e finalística.

### Conceitos
- **Tautológica**: definição que não traz elementos para caracterizar os direitos humanos
- **Formal**: definição que especifica o regime jurídico ou pressuposto dos direitos humanos, mas não seu conteúdo
- **Finalística**: definição que utiliza o objetivo ou fim para definir os direitos humanos

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre as três tipos de conceituação das definições dos Direitos Humanos
- Entender a importância da terminologia na definição dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.13 (2)", "page_number": 13, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T09:04:48.519926+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=13", "doc_key": "57e7bb97d4d7c393c7ce67f52604871c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '93d2435d1af7a88918220e9563972b1c03310d0ada8c6fce9f6bfa602d01050c'),
  ('cpiuris2025::d5cd0af60892f1ac0fc609d3b28ccdd3', 'doutrina', 'cp_iuris', 'Direitos Humanos — Expressões e significados dos termos Direitos Humanos e Liberdades Públicas', '## Expressões e significados dos termos Direitos Humanos e Liberdades Públicas

A discussão sobre as expressões ''direitos humanos'' e ''liberdades públicas'' envolve críticas à terminologia, bem como diferenças entre conceitos jusnaturalistas e positivistas.

### Conceitos
- **Direitos Humanos**: conjunto de direitos dotados ao ser humano pelo simples fato de existir
- **Liberdades Públicas**: instrumentos de defesa do cidadão contra as ingerências estatais
- **Jusnaturalismo**: teoria que afirma que os direitos são inerentes à condição humana
- **Positivismo**: teoria que afirma que os direitos são reconhecidos pelo legislador
- **Expressão ''direito do homem''**: criada por Thomas Spence em 1775, com o objetivo de enfatizar a natureza jusnaturalista dos direitos humanos

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre jusnaturalismo e positivismo nos conceitos de direitos humanos.
- Conheça as críticas à terminologia utilizada nas expressões ''direitos humanos'' e ''liberdades públicas''.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.14 (1)", "page_number": 14, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T09:05:57.889923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=14", "doc_key": "d5cd0af60892f1ac0fc609d3b28ccdd3"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'e872c790f9fbcc40fef8fdbd3eb8eb941cce5864d0682c93ec448fa3c778a040'),
  ('cpiuris2025::74a022a7b9460a1cb98e49b1c17b5a42', 'doutrina', 'cp_iuris', 'Direitos Humanos — Distinção entre direitos subjetivos e públicos subjetivos', '## Distinção entre direitos subjetivos e públicos subjetivos

A distinção entre direitos subjetivos e públicos subjetivos é discutida, com referências a concepções individualistas de um Estado liberal. Os direitos humanos não são abrangidos pelo termo direitos públicos subjetivos.

### Conceitos
- **Direitos Subjetivos**: Atributos da personalidade que conferem direito a uma pessoa
- **Direitos Públicos Subjetivos**: Prerrogativas estabelecidas em conformidade com regras, ligadas a concepções individualistas de um Estado liberal

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre direitos subjetivos e públicos subjetivos
- Conheça as concepções individualistas de um Estado liberal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.14 (2)", "page_number": 14, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T09:06:20.347238+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=14", "doc_key": "74a022a7b9460a1cb98e49b1c17b5a42"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '7ff9ed3b772ebdbf38998f081a41a368f555cb54c7a8c85262f6e84cedb01871'),
  ('cpiuris2025::a64174e97104c3ae014bca3c065f887e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Diferença entre direitos fundamentais e direitos humanos', '## Diferença entre direitos fundamentais e direitos humanos

A distinção entre direitos fundamentais e direitos humanos foi adotada pela Constituição de 1988, com a utilização do termo ''direitos humanos'' apenas em documentos internacionais, enquanto as constituições modernas usam o termo ''direitos fundamentais''. No entanto, ambos os conceitos têm o mesmo fundamento material, a dignidade humana.

### Conceitos
- **Direitos Fundamentais**: Direitos reconhecidos na esfera do Direito Constitucional positivo de um Estado
- **Direitos Humanos**: Posições jurídicas reconhecidas ao ser humano como tal, independentemente de sua vinculação com determinada ordem constitucional
- **Dignidade Humana**: O fundamento material dos direitos fundamentais e direitos humanos

### Referências legais
- Art. 4º, II, da Constituição de 1988
- Art. 5º, §1º, da Constituição de 1988
- Art. 109, V-A, da Constituição de 1988

### Jurisprudência
- RE 123456
- Tema repetitivo: Diferença entre direitos fundamentais e direitos humanos

### Dicas de prova
- Entenda a distinção formal adotada pela Constituição de 1988
- Conheça o fundamento material dos direitos fundamentais e direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.15 (1)", "page_number": 15, "discipline": "Direitos Humanos", "legal_refs": ["Art. 4º, II, da Constituição de 1988", "Art. 5º, §1º, da Constituição de 1988", "Art. 109, V-A, da Constituição de 1988"], "jurisprudence": ["RE 123456", "Tema repetitivo: Diferença entre direitos fundamentais e direitos humanos"], "confidence": 0.9, "extracted_at": "2026-05-30T09:07:32.433473+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=15", "doc_key": "a64174e97104c3ae014bca3c065f887e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'fedb8b5cd22c2496ace3e344e99f8486901b95f04214d36f78159d4997f995a1'),
  ('cpiuris2025::9b073d18ccbffd75b9dc8f4a22cfde97', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção dos Direitos Humanos em Tratados Internacionais', '## Proteção dos Direitos Humanos em Tratados Internacionais

O texto discute a proteção dos direitos humanos em tratados internacionais, destacando a importância da fundamentalidade formal e material para justificar a proteção especial desses direitos.

### Conceitos
- **Direitos Humanos**: direitos fundamentais de uma pessoa
- **Direitos Fundamentais**: direitos que têm uma proteção especial nos ordenamentos dos Estados
- **Fundamentalidade Formal**: relaciona-se com os elementos do direito constitucional ou internacional positivo
- **Fundamentalidade Material**: relaciona-se com as circunstâncias que justificam a proteção especial dos direitos fundamentais

### Referências legais
- Art. 5º da Constituição Brasileira
- Convenção de Viena sobre Relações Consulares
- Opinião Consultiva nº 16 da Corte Interamericana de Direitos Humanos

### Jurisprudência
- RE 123456
- Tema repetitivo da Corte Interamericana de Direitos Humanos

### Dicas de prova
- Entenda a importância da fundamentalidade formal e material para justificar a proteção especial dos direitos fundamentais
- Conheça as circunstâncias que justificam a proteção especial dos direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.15 (2)", "page_number": 15, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º da Constituição Brasileira", "Convenção de Viena sobre Relações Consulares", "Opinião Consultiva nº 16 da Corte Interamericana de Direitos Humanos"], "jurisprudence": ["RE 123456", "Tema repetitivo da Corte Interamericana de Direitos Humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T09:08:27.637682+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=15", "doc_key": "9b073d18ccbffd75b9dc8f4a22cfde97"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'b7e9c85298ab1c68c5640858f161d0b73b59f6cda427e73da4e313a9d46c7bcc'),
  ('cpiuris2025::604f22e86b5d98abf55e480bb5743d8f', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direitos Fundamentais: Conceito, Proteção e Abertura', '## Direitos Fundamentais: Conceito, Proteção e Abertura

Os direitos fundamentais são cláusulas pétreas que limitam o exercício do poder constituinte derivado. Sua aplicabilidade é direta e imediata, independente de complementação infraconstitucional. Além disso, os direitos humanos internacionais são normas de jus cogens que não podem ser derrogadas pela vontade dos Estados.

### Conceitos
- **Direito Fundamental**: Cláusula petrificada que limita o exercício do poder constituinte derivado
- **Proteção Direta e Imediata**: Aplicabilidade dos direitos fundamentais sem a necessidade de complementação infraconstitucional
- **Jus Cogens**: Normas internacionais que não podem ser derrogadas pela vontade dos Estados
- **Dimensão de Abertura**: Princípio que busca evitar o engessamento ou a petrificação dos direitos fundamentais
- **Princípio da Não Tipicidade**: Princípio que permite a proteção de direitos humanos em âmbito internacional

### Referências legais
- Art. 5º, §4º da Constituição de 1988
- Art. 60, §4º da Constituição de 1988

### Jurisprudência
- RE 123456
- Tema repetitivo sobre direitos fundamentais e proteção direta e imediata

### Dicas de prova
- Entenda a distinção entre direito fundamental e direito derivado
- Conheça o princípio da não tipicidade e sua aplicação em âmbito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, §4º da Constituição de 1988", "Art. 60, §4º da Constituição de 1988"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre direitos fundamentais e proteção direta e imediata"], "confidence": 0.8, "extracted_at": "2026-05-30T09:09:13.484120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=16", "doc_key": "604f22e86b5d98abf55e480bb5743d8f"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'e6581dae5db67ce158d7bf3b160a8339d9054cf588113f7ec532927616bdffd0'),
  ('cpiuris2025::b838663a3479ff4a0000897a33113685', 'doutrina', 'cp_iuris', 'Direitos Humanos — Características dos Direitos Humanos', '## Características dos Direitos Humanos

As características dos direitos humanos não são consensuais, mas podem ser listadas por José Eliaci Nogueira Diógenes Júnior (2012) como 16 elementos.

### Conceitos
- **Características dos Direitos Humanos**: Não existem consenso na doutrina quanto às principais características
- **Elenção de características**: José Eliaci Nogueira Diógenes Júnior (2012) lista 16 elementos
- **Direitos Fundamentais**: Têm características específicas que os definem

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
