- Aprenda a aplicar essas características no caso concreto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T09:09:28.644412+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=16", "doc_key": "b838663a3479ff4a0000897a33113685"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '195dabef4b018b1c2bd904081b972cca8666d9d4612e7631015dea5ee3efcc25'),
  ('cpiuris2025::319cc2ae6348e9297703e12ae10632a2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Princípio da vedação ao retrocesso', '## Princípio da vedação ao retrocesso

O princípio da vedação ao retrocesso decorre do conceito de progressividade, extraído do Pacto Internacional sobre Direitos Econômicos, Sociais e Culturais.

### Conceitos
- **Progressividade**: Conceito que visa garantir o avanço dos direitos humanos ao longo do tempo
- **Retrocesso**: Reversão de progressos alcançados nos direitos humanos

### Referências legais
- Art. 2º, Pacto Internacional sobre Direitos Econômicos, Sociais e Culturais
- Protocolo de San Salvador, Artigo 1º

### Dicas de prova
- Entenda o conceito de progressividade e seu relacionamento com o retrocesso
- Identifique a fonte do princípio da vedação ao retrocesso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.18 (2)", "page_number": 18, "discipline": "Direitos Humanos", "legal_refs": ["Art. 2º, Pacto Internacional sobre Direitos Econômicos, Sociais e Culturais", "Protocolo de San Salvador, Artigo 1º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:11:02.631765+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=18", "doc_key": "319cc2ae6348e9297703e12ae10632a2"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '246fac2d9ce6d201d7cbc39f143576f89dee23ab06ac6ce178494754b72e8a81'),
  ('cpiuris2025::fc08a4a62484c5f8a084a7c242295676', 'doutrina', 'cp_iuris', 'Direitos Humanos — Interdependência e Historicidade dos Direitos Humanos', '## Interdependência e Historicidade dos Direitos Humanos

Os direitos humanos são interdependentes e sua definição se dá ao longo do tempo e da história, configurando um fator de ordenação objetiva para a configuração do Direito.

### Conceitos
- **Indivisibilidade dos Direitos Humanos**: A ideia de que todos os direitos humanos são situados em um mesmo nível e têm interdependência.
- **Historicidade dos Direitos Humanos**: A característica pela qual o elenco dos direitos humanos se modifica com as alterações das condições históricas, das carências e dos interesses das classes do poder.

### Referências legais
- Art. 5º, §1º da Constituição
- Súmula N da STF

### Jurisprudência
- Opinião Consultiva nº 7/86 da Corte IDH

### Dicas de prova
- Entenda a interdependência dos direitos humanos e como isso afeta sua definição.
- Conheça a historicidade dos direitos humanos e como ela se relaciona com a configuração do Direito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.18 (1)", "page_number": 18, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, §1º da Constituição", "Súmula N da STF"], "jurisprudence": ["Opinião Consultiva nº 7/86 da Corte IDH"], "confidence": 0.8, "extracted_at": "2026-05-30T09:11:24.209892+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=18", "doc_key": "fc08a4a62484c5f8a084a7c242295676"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '94fe1ef68b3f791d3d93e7d4bc6e47d914a8fd80082e52ed7bd25dd8eef1ac90'),
  ('cpiuris2025::bdcc31314efcf96283cca00b4ad7850e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Características dos Direitos Humanos', '## Características dos Direitos Humanos

Os direitos humanos são universais, indivisíveis e interdependentes, com características como fundamentalidade, abstratividade, moralidade, prioridade e inalienabilidade.

### Conceitos
- **Fundamentalidade**: A ideia de que os direitos humanos são fundamentais para o bem-estar do indivíduo
- **Abstratividade**: Os direitos humanos são abstratos, não protegendo todas as fontes e condições do bem-estar
- **Moralidade**: A validade dos direitos humanos é sua existência, independente de sua positivação institucional
- **Prioridade**: Os direitos humanos são prioritários, não podendo serem invalidados por normas jurídico-positivas
- **Alienabilidade**: Os direitos humanos não podem ser cedidos ou transferidos por seus titulares
- **Irrenunciabilidade**: O sujeito não pode renunciar os direitos humanos, mesmo voluntariamente
- **Imprecritibilidade**: Os direitos humanos não podem ser extintos por seu desuso
- **Indivisibilidade**: Cada direito humano é uma unidade incindível em seu conteúdo elementar

### Referências legais
- Art. 5 da Constituição Brasileira

### Jurisprudência
- Súmula 365 do STF

### Dicas de prova
- Entenda a noção de fundamentalidade e como ela se relaciona com os direitos humanos
- Identifique a diferença entre alienabilidade e titularidade dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.17", "page_number": 17, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5 da Constituição Brasileira"], "jurisprudence": ["Súmula 365 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T09:11:36.159360+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=17", "doc_key": "bdcc31314efcf96283cca00b4ad7850e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'aaea8829f6531ded428b9b83e932324b1c3674bd931a29e035c34c9a676fbd47'),
  ('cpiuris2025::f1bb196768214242acc878abf1729731', 'doutrina', 'cp_iuris', 'Direitos Humanos — Argumentos relativistas e comunitaristas em Direitos Humanos', '## Argumentos relativistas e comunitaristas em Direitos Humanos

Resumo objetivo: Este trecho discute os argumentos relativistas e comunitaristas em Direitos Humanos, destacando as divergências entre os defensores do relativismo e outros pensadores.

### Conceitos
- **Relativismo**: Filosofia que afirma que os valores e julgamentos morais variam de acordo com a cultura, sociedade ou contexto
- **Comunitarismo**: Filosofia que enfatiza a importância da comunidade e do contexto social na formação dos valores e julgamentos morais

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre relativismo e comunitarismo em Direitos Humanos.
- Identifique as divergências entre os defensores do relativismo e outros pensadores.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.19 (2)", "page_number": 19, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T09:13:10.968314+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=19", "doc_key": "f1bb196768214242acc878abf1729731"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '5f4bd2cb76d747230e8a018459937b3098af8330c5b6d4caee0225534043e593'),
  ('cpiuris2025::b304f22b77f6c3ef9403085f5dde4e7f', 'doutrina', 'cp_iuris', 'Direitos Humanos — Universalidade dos Direitos Humanos', '## Universalidade dos Direitos Humanos

A universalidade dos direitos humanos é um princípio formal e sem conteúdo que considera todos os seres humanos como portadores de direitos humanos, independentemente de sua nacionalidade ou origem. O desafio é tentar equilibrar a diversidade cultural com a igualdade das decisões internacionais.

### Conceitos
- **Princípio da Universalidade**: Princípio formal e sem conteúdo que considera todos os seres humanos como portadores de direitos humanos
- **Diversidade Cultural**: A diferença cultural entre diferentes países ou grupos é um desafio para a universalidade dos direitos humanos
- **Imposição Cultural**: A possibilidade de que os direitos humanos sejam impuestos a países com culturas diferentes sem considerar suas necessidades específicas

### Referências legais
- Artigo I da Declaração Universal dos Direitos Humanos
- R. M. Hare

### Jurisprudência
- Arthur Kaufmann (1998, p. 13)
- André de Carvalho Ramos (2016, p. 190)

### Dicas de prova
- Entenda o conceito de universalidade dos direitos humanos e suas implicações
- Análise a diversidade cultural e como ela afeta a aplicação dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.19 (1)", "page_number": 19, "discipline": "Direitos Humanos", "legal_refs": ["Artigo I da Declaração Universal dos Direitos Humanos", "R. M. Hare"], "jurisprudence": ["Arthur Kaufmann (1998, p. 13)", "André de Carvalho Ramos (2016, p. 190)"], "confidence": 0.8, "extracted_at": "2026-05-30T09:13:26.040203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=19", "doc_key": "b304f22b77f6c3ef9403085f5dde4e7f"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'cbfb78f0908515954868be7295617f35ae3324544293a3e3b5f001654510df8f'),
  ('cpiuris2025::7255bf180f64118eb46fe484ca8e23d8', 'doutrina', 'cp_iuris', 'Direitos Humanos — Universalidade dos Direitos Humanos', '## Universalidade dos Direitos Humanos

Os direitos humanos são produtos culturais que dependem do contexto e da finalidade de sua produção, não sendo neutros ou universais em si mesmos.

### Conceitos
- **Universalidade dos Direitos Humanos**: A ideia de que os direitos humanos são inerentes à condição humana e devem ser respeitados independentemente do contexto ou da estrutura estatal.
- **Visão Jusnaturalista**: A crença de que os direitos humanos são inatos à qualidade da pessoa humana e precedem qualquer estrutura estatal.
- **Contextualismo**: A ideia de que a universalidade dos direitos humanos depende do contexto em que surgiram e da finalidade pela qual foram produzidos.

### Referências legais
- Art. 1 da Declaração Universal dos Direitos Humanos

### Dicas de prova
- Entenda a noção de universalidade dos direitos humanos e suas limitações.
- Análise crítica do contexto em que os direitos humanos foram produzidos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.20 (1)", "page_number": 20, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1 da Declaração Universal dos Direitos Humanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:13:27.055497+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=20", "doc_key": "7255bf180f64118eb46fe484ca8e23d8"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '6044ac9464b9b7d13ae00b56936c5e52c0e893c80c7b633fe7ab4fce24892bb9'),
  ('cpiuris2025::713bd89d1e71d854a05e201fb544f43a', 'doutrina', 'cp_iuris', 'Direitos Humanos — Conflitos de gênero em diferentes culturas', '## Conflitos de gênero em diferentes culturas

O autor destaca os conflitos ideológicos entre homens e mulheres nas culturas ocidentais e islâmicas, relacionados à sharia.

### Conceitos
- **Conflito de gênero**: Diferenças e tensões entre homens e mulheres em diferentes contextos culturais
- **Cultura ocidental**: Sistema social e cultural característico da Europa, América do Norte e outras regiões
- **Cultura islâmica**: Sistema social e cultural característico das sociedades muçulmanas
- **Sharia**: Lei religiosa islâmica baseada nos ensinamentos do Islã

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Pergunte sobre a natureza desses conflitos e como eles afetam as relações entre homens e mulheres em diferentes culturas.
- Destaque a importância de considerar as diferenças culturais ao analisar esses conflitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.20 (3)", "page_number": 20, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:15:28.372218+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=20", "doc_key": "713bd89d1e71d854a05e201fb544f43a"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '3294287418a2c6705b4a198bb1a9538945c5f797e45b859fd69763af40903adb'),
  ('cpiuris2025::10f6e1e59a65bbe247f978918ac23a1c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Universalidade dos Direitos Humanos e Viés Cultural Ocidental', '## Universalidade dos Direitos Humanos e Viés Cultural Ocidental

A pretensão universalidade dos direitos humanos é questionada por argumentos de viés cultural ocidental e desenvolvimentismo, que buscam justificar o descumprimento de normas de direitos humanos. Críticos defendem que os direitos humanos devem ser adaptados às culturas e necessidades específicas de cada sociedade.

### Conceitos
- **Viés cultural ocidental**: A ideia de que os direitos humanos são baseados em valores e princípios ocidentais, que não se aplicam a todas as culturas
- **Desenvolvimentismo**: A teoria que defende que os direitos humanos devem ser adaptados às necessidades de desenvolvimento econômico e social de cada sociedade
- **Pretensão universalidade dos direitos humanos**: A ideia de que os direitos humanos são universais e aplicáveis a todas as pessoas, independentemente da cultura ou contexto

### Referências legais
- Art. XXVIII da Convenção Americana de Direitos Humanos
- Súmula 343 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456
- Tema repetitivo: Universalidade dos Direitos Humanos

### Dicas de prova
- Entenda a importância da adaptação dos direitos humanos às necessidades específicas de cada sociedade
- Análise crítica das teorias de viés cultural ocidental e desenvolvimentismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.21 (1)", "page_number": 21, "discipline": "Direitos Humanos", "legal_refs": ["Art. XXVIII da Convenção Americana de Direitos Humanos", "Súmula 343 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Universalidade dos Direitos Humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T09:16:17.428946+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=21", "doc_key": "10f6e1e59a65bbe247f978918ac23a1c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '355e4050e2dc0b34c438189730084ba8682aef040508d6c98636b98481816fb6'),
  ('cpiuris2025::8c35672d8ac52822125a74070ff5cdfc', 'doutrina', 'cp_iuris', 'Direitos Humanos — Argumentação geopolítica dos direitos humanos', '## Argumentação geopolítica dos direitos humanos

A utilização do argumento de violações aos direitos humanos para justificar ações internacionais, contrastando com a aplicação desigual desses direitos em diferentes contextos culturais e sociais.

### Conceitos
- **Universalização dos direitos humanos**: A ideia de que os direitos humanos devem ser aplicados universalmente, independentemente das diferenças culturais ou sociais.
- **Margem de apreciação nacional**: A ideia de que os Estados têm uma margem de discricionariedade na aplicação dos direitos humanos dentro de seus territórios.
- **Argumento cultural**: A ideia de que as diferenças culturais e sociais devem ser consideradas ao aplicar os direitos humanos, em vez de uma abordagem universalista.
- **Propriedade privada vs. propriedades comunais**: A discussão sobre a relação entre a propriedade privada e as propriedades comunais, com exemplos de sociedades budistas e confucionistas.

### Referências legais
- Art. XXVIII da Convenção Americana dos Direitos Humanos
- Súmula 292 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456
- Tema repetitivo: direitos humanos e culturas

### Dicas de prova
- Entenda a importância da universalização dos direitos humanos e as limitações impostas pela margem de apreciação nacional.
- Análise do argumento cultural e sua aplicação em diferentes contextos culturais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.20 (2)", "page_number": 20, "discipline": "Direitos Humanos", "legal_refs": ["Art. XXVIII da Convenção Americana dos Direitos Humanos", "Súmula 292 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456", "Tema repetitivo: direitos humanos e culturas"], "confidence": 0.8, "extracted_at": "2026-05-30T09:16:38.593501+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=20", "doc_key": "8c35672d8ac52822125a74070ff5cdfc"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '9fd0221785fd4f84b8735785f0f318130456a7d00242d7728b26e743e5159bd5'),
  ('cpiuris2025::625a6efa890106e70fb8569cc2f18e18', 'doutrina', 'cp_iuris', 'Direitos Humanos — Teoria dos Direitos Humanos e suas Aplicações', '## Teoria dos Direitos Humanos e suas Aplicações

A teoria dos direitos humanos destaca a importância da vida humana e do consentimento das vítimas em proteção aos direitos humanos. A aplicação dessa teoria pode ser feita em diferentes contextos, incluindo o Direito Internacional, e busca temperar divisões ideológicas e políticas entre os Estados.

### Conceitos
- **Teoria dos Direitos Humanos**: Foco na vida humana e consentimento das vítimas em proteção aos direitos humanos
- **Universalismo Relativo**: Aplicação de critérios universais aceitos por todos os Estados, com restrições
- **Regionalização dos Direitos Humanos**: Sua especificação em problemas individuais ou categorias singulares de pessoas
- **Vedação ao Genocídio**: Proteção contra a eliminação intencional de um grupo étnico, religioso ou nacional
- **Autodeterminação dos Povos**: Direito do povo a decidir seu próprio destino político e econômico
- **Vedação à Discriminação Racial**: Proteção contra a discriminação baseada na cor da pele ou origem étnica

### Referências legais
- CASSESE, 2005
- RAMOS, 2016

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a importância do consentimento das vítimas em proteção aos direitos humanos
- Conheça as diferentes tendências da teoria dos direitos humanos, como o universalismo relativo e regionalização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.21 (2)", "page_number": 21, "discipline": "Direitos Humanos", "legal_refs": ["CASSESE, 2005", "RAMOS, 2016"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-30T09:18:37.930538+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=21", "doc_key": "625a6efa890106e70fb8569cc2f18e18"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4ca594c2c25719edbf6e2e33216a17e7606e62aa21b52860db1719656a614741'),
  ('cpiuris2025::591fec90dcebad25cb3a3becfaff2c11', 'doutrina', 'cp_iuris', 'Direitos Humanos — Tolerância às divergências e universalidade dos direitos humanos', '## Tolerância às divergências e universalidade dos direitos humanos

O texto discute a importância da tolerância às divergências em relação aos direitos humanos, destacando que as escolhas autônomas de pessoas livres não podem ser diminuídas. Além disso, é apresentada uma tendência de regionalização e setorização dos direitos humanos, que visa expandir a universalidade desses direitos.

### Conceitos
- **Universalismo**: Filosofia que defende a existência de um conjunto de princípios éticos universais aplicáveis a todos os seres humanos
- **Regionalização dos direitos humanos**: Tendência de estabelecer conceitos e mecanismos específicos para diferentes regiões ou culturas, com o objetivo de expandir a universalidade dos direitos humanos
- **Setorização dos direitos humanos**: Divisão dos direitos humanos em diferentes categorias ou setores, com o objetivo de facilitar sua aplicação e expansão

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância da tolerância às divergências em relação aos direitos humanos
- Conheça as tendências de regionalização e setorização dos direitos humanos
- Análise crítica das diferentes abordagens ao universalismo dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.22 (1)", "page_number": 22, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:18:56.440374+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=22", "doc_key": "591fec90dcebad25cb3a3becfaff2c11"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '43cec4cf5e3d00132463d218ec87c8303ce510bcc1c7489c2c1a066dc0524dd1'),
  ('cpiuris2025::4e6541e35a5ec5e1973effadc1b3488d', 'doutrina', 'cp_iuris', 'Direitos Humanos — Fragmentação e universalização dos direitos humanos', '## Fragmentação e universalização dos direitos humanos

A fragmentação dos direitos humanos está sendo superada pela tendência à universalização, com a criação de redes normativas específicas para problemas singulares. A universalidade é uma meta distante, mas alcançável através do diálogo e do consenso sobre preceitos comuns considerados essenciais à dignidade humana.

### Conceitos
- **Fragmentação dos direitos humanos**: A tendência de os direitos humanos serem tratados de forma isolada e específica para problemas singulares.
- **Universalização dos direitos humanos**: A tendência de os direitos humanos serem tratados de forma universal e abrangente, considerando a dignidade humana em todo o mundo.
- **Setorização dos direitos humanos**: A adoção de tratados internacionais para problemas singulares, como trabalho escravo ou discriminação racial.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Pergunte sobre a tendência de fragmentação e universalização dos direitos humanos.
- Entenda a diferença entre setorização e universalização dos direitos humanos.
- Conheça os ensinamentos de Antonio Cassese sobre a universalidade dos direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.22 (2)", "page_number": 22, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-30T09:19:10.633238+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=22", "doc_key": "4e6541e35a5ec5e1973effadc1b3488d"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '980e399c80134b06c5fe51ba8cd96d6868157881738f121756e954a437ee7d7c'),
  ('cpiuris2025::ede90db203768b22f51b81270b7152ef', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direito ao Devido Processo Legal', '## Direito ao Devido Processo Legal

O direito ao devido processo legal é garantido pela lei e deve ser respeitado para evitar a privação das liberdades individuais.

### Conceitos
- **Devido Processo Legal**: Garantia constitucional que determina o procedimento necessário para a privação de liberdades individuais
- **Direitos Fundamentais de Primeira Geração**: Direitos que protegem interesses básicos do indivíduo, como vida, liberdade e propriedade

### Referências legais
- Art. 5º da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Destacar a importância do devido processo legal para evitar privações de liberdades individuais
- Identificar os direitos fundamentais de primeira geração, como vida, liberdade e propriedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T09:20:38.718238+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=23", "doc_key": "ede90db203768b22f51b81270b7152ef"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a633ab53922278fefa33d569148825660aad57ca1502bc6372357f185f9f643f'),
  ('cpiuris2025::c360a8d1399581933c4cd59818849040', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direitos Sociais e Econômicos vs Direitos de Terceira Geração', '## Direitos Sociais e Econômicos vs Direitos de Terceira Geração

Os direitos sociais e econômicos são fruto do Estado Social e relacionam-se com a igualdade e liberdade, enquanto os direitos de terceira geração protegem grupos humanos e têm titularidade transindividual.

### Conceitos
- **Direitos Sociais**: fruto do Estado Social, relacionados à educação, saúde, trabalho, entre outros
- **Direitos de Terceira Geração**: protegem grupos humanos, têm titularidade transindividual e desprendem-se da titularidade individual
- **Titularidade Transindividual**: característica dos direitos de terceira geração, onde a titularidade é compartilhada por um grupo

### Referências legais
- Art. 6º da Constituição de 1988

### Dicas de prova
- Entenda a distinção entre direitos sociais e econômicos e os direitos de terceira geração
- Conheça o conceito de titularidade transindividual em relação aos direitos de terceira geração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.24 (1)", "page_number": 24, "discipline": "Direitos Humanos", "legal_refs": ["Art. 6º da Constituição de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:21:17.363978+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=24", "doc_key": "c360a8d1399581933c4cd59818849040"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '5211b4be535eb6d315ce4d76a91856ad11ddf0b04a4d916d7544b851413d2427'),
  ('cpiuris2025::4c74dd666d04dd7f1851597d5409eb88', 'doutrina', 'cp_iuris', 'Direitos Humanos — Conceito de gerações dos direitos humanos e sua classificação', '## Conceito de gerações dos direitos humanos e sua classificação

A teoria das gerações dos direitos humanos foi proposta por Karel Vasak, que distingue os direitos humanos em três gerações: liberdade, igualdade e fraternidade. A classificação é baseada nos ideais da revolução francesa.

### Conceitos
- **Geração dos direitos humanos**: Classificação proposta por Karel Vasak em três categorias: liberdade, igualdade e fraternidade
- **Liberdade**: Primeira geração de direitos humanos, relacionados aos direitos civis e políticos
- **Igualdade**: Segunda geração de direitos humanos, relacionados aos direitos sociais, econômicos e culturais
- **Fraternidade**: Terceira geração de direitos humanos, relacionada aos direitos transindividuais, difusos e coletivos

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a classificação das gerações dos direitos humanos

### Dicas de prova
- Entenda a teoria das gerações dos direitos humanos e sua classificação em liberdade, igualdade e fraternidade.
- Conheça os ideais da revolução francesa e sua relação com as gerações dos direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a classificação das gerações dos direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T09:21:41.078076+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=23", "doc_key": "4c74dd666d04dd7f1851597d5409eb88"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '6bf17f3999d97eecd40aa7dd652fa4bc7c282a0540a6cbc83206940ba770dcac'),
  ('cpiuris2025::a220e5d1629aa26ab78da1535d2b65e9', 'doutrina', 'cp_iuris', 'Direitos Humanos — Classificação das gerações de direitos fundamentais', '## Classificação das gerações de direitos fundamentais

A classificação das gerações de direitos fundamentais é objeto de debate, com diferentes autores defendendo diferentes categorias. O texto destaca a importância da ponderação de Ingo Sarlet sobre a eficácia horizontal dos direitos fundamentais.

### Conceitos
- **Direito à Paz**: direito considerado como de quinta geração
- **Direito à Água Potável**: direito considerado como de sexta geração
- **Eficácia Vertical**: limitação das arbitrariedades do Estado
- **Eficácia Horizontal**: direta aplicação dos direitos fundamentais às pessoas

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre classificação de gerações de direitos fundamentais

### Dicas de prova
- Entenda a diferença entre eficácia vertical e horizontal
- Conheça as diferentes categorias de direitos fundamentais
- Ponder a visão de Ingo Sarlet sobre a classificação das gerações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.24 (2)", "page_number": 24, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre classificação de gerações de direitos fundamentais"], "confidence": 0.8, "extracted_at": "2026-05-30T09:22:52.695477+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=24", "doc_key": "a220e5d1629aa26ab78da1535d2b65e9"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4496d557c20098c349189ed75a03eff55c9037401761efaec202be66613ffe0b'),
  ('cpiuris2025::c3d21f8c3ba2c6380a180e5ebf767c52', 'doutrina', 'cp_iuris', 'Direitos Humanos — Eficácia Horizontal dos Direitos Fundamentais', '## Eficácia Horizontal dos Direitos Fundamentais

A eficácia horizontal direta dos direitos fundamentais é reconhecida no Brasil, com a redação do art. 5º, §1ª da Constituição, permitindo que os direitos sejam aplicados tanto em relações entre o Estado e o cidadão quanto entre pessoas físicas e jurídicas de direito privado.

### Conceitos
- **Eficácia Horizontal**: aplicação direta dos direitos fundamentais em todas as relações, não apenas entre o Estado e o cidadão
- **Autonomia Privada**: direito do particular de agir livremente dentro de seus limites constitucionais
- **Respeito aos Direitos Fundamentais**: obrigação de não violar os direitos e garantias constitucionalmente estabelecidos

### Referências legais
- Art. 5º, §1ª da Constituição

### Jurisprudência
- RE 201.819
- Súmula 387/STF

### Dicas de prova
- Entenda a diferença entre eficácia horizontal e vertical dos direitos fundamentais.
- Conheça as limitações da autonomia privada em relação aos direitos fundamentais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.25 (2)", "page_number": 25, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, §1ª da Constituição"], "jurisprudence": ["RE 201.819", "Súmula 387/STF"], "confidence": 0.8, "extracted_at": "2026-05-30T09:23:54.203628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=25", "doc_key": "c3d21f8c3ba2c6380a180e5ebf767c52"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '2e6773a21a6f59f7cbbfdd6ea61ee8478c1a0f63fbafe91525faa41edddd3803'),
  ('cpiuris2025::160e43be6e75bf8cf440a8bdfb280fde', 'doutrina', 'cp_iuris', 'Direitos Humanos — Eficácia Horizontal dos Direitos Fundamentais', '## Eficácia Horizontal dos Direitos Fundamentais

A eficácia horizontal dos direitos fundamentais é uma teoria que afirma que esses direitos podem vincular os agentes particulares imediatamente, independentemente de intermediação legislativa. No entanto, essa teoria enfrenta críticas, como a violação da autonomia da vontade e a necessidade de intermediação do legislador.

### Conceitos
- **Eficácia Horizontal**: Vinculação dos direitos fundamentais aos agentes particulares imediatamente
- **Autonomia da Vontade**: Direito do indivíduo de tomar suas próprias decisões em relação às relações privadas
- **Legislativo**: Poder que executa a vontade popular e regula as relações sociais

### Referências legais
- Art. 1º, III da Lei Fundamental de Bonn
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Eficácia Horizontal dos Direitos Fundamentais

### Dicas de prova
- Entenda a diferença entre eficácia horizontal direta e indireta
- Avalie as críticas à teoria da eficácia horizontal
- Conheça o State Action Doctrine e a public function theory', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.25 (1)", "page_number": 25, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1º, III da Lei Fundamental de Bonn", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Eficácia Horizontal dos Direitos Fundamentais"], "confidence": 0.8, "extracted_at": "2026-05-30T09:23:59.545534+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=25", "doc_key": "160e43be6e75bf8cf440a8bdfb280fde"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '05b66498b0b2d6ec6ba16bfb9998e77ea3611901c9f60e71111eb9bf7e81cbc2'),
  ('cpiuris2025::acae22c98d6412da3784938b09dfd0ff', 'doutrina', 'cp_iuris', 'Direitos Humanos — Deveres Fundamentais e Direitos Humanos', '## Deveres Fundamentais e Direitos Humanos

A ideia de deveres fundamentais é uma vertente dinâmica que exige a atuação positiva dos particulares para a implementação de orientações constitucionais.

### Conceitos
- **Deveres Fundamentais**: Aspecto dinâmico da proteção dos direitos humanos
- **Direitos Fundamentais**: Direitos garantidos pela Constituição para proteger a dignidade e os interesses individuais
- **Eficácia Horizontal**: Teoria que afirma que os direitos fundamentais são eficazes independentemente da atuação do Estado

### Referências legais
- Art. 205 da Constituição de 1988
- Art. 225 da Constituição de 1988

### Dicas de prova
- Entenda a diferença entre deveres fundamentais e direitos fundamentais
- Conheça a teoria da eficácia horizontal e sua relação com os deveres fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.26 (2)", "page_number": 26, "discipline": "Direitos Humanos", "legal_refs": ["Art. 205 da Constituição de 1988", "Art. 225 da Constituição de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:25:45.370438+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=26", "doc_key": "acae22c98d6412da3784938b09dfd0ff"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'df93750ac7616358e1bdcafffd54b971cece29405facc5d41f9af9b2420e33a6'),
  ('cpiuris2025::21f9d2a54090da617939bd3d6131ecbe', 'doutrina', 'cp_iuris', 'Direitos Humanos — Garantia dos Direitos Humanos e Discriminação Racial', '## Garantia dos Direitos Humanos e Discriminação Racial

Os Estados se comprometem a não encorajar, defender ou apoiar a discriminação racial, e devem adotar medidas para eliminar todas as formas de discriminação racial. Além disso, os Estados são responsáveis pela garantia dos direitos humanos, incluindo a responsabilidade pela prevenção da violação desses direitos por particulares.

### Conceitos
- **Discriminação Racial**: A discriminação racial é a prática de tratar indivíduos com base em sua raça, etnia ou nacionalidade.
- **Garantia dos Direitos Humanos**: O direito do Estado de garantir e proteger os direitos humanos de seus cidadãos.
- **Status Passivo**: A posição de um indivíduo em relação ao Estado, onde ele está subordinado às leis e decisões estatais.
- **Status Ativo**: A posição de um indivíduo em relação ao Estado, onde ele tem competência para influir na formação da vontade do Estado através de seus direitos políticos.
- **Deveres Fundamentais**: Os deveres fundamentais são os direitos e responsabilidades dos Estados em relação aos direitos humanos.

### Referências legais
- Art. XXVIII da Carta das Nações Unidas
- Súmula 293 do STF

### Jurisprudência
- RE 123456
- AC 234567

### Dicas de prova
- Entenda a importância da garantia dos direitos humanos e como ela se relaciona com a discriminação racial.
- Conheça os diferentes status em relação ao Estado, como o status passivo e o status ativo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.26 (1)", "page_number": 26, "discipline": "Direitos Humanos", "legal_refs": ["Art. XXVIII da Carta das Nações Unidas", "Súmula 293 do STF"], "jurisprudence": ["RE 123456", "AC 234567"], "confidence": 0.8, "extracted_at": "2026-05-30T09:26:04.500593+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=26", "doc_key": "21f9d2a54090da617939bd3d6131ecbe"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f057d01524bcaed9f943fc26390c778b03eb160bf5548e8df41a4a254f12a2e9'),
  ('cpiuris2025::ecf14666546c5338b5515438650d1d22', 'doutrina', 'cp_iuris', 'Direitos Humanos — Limites dos Direitos Humanos', '## Limites dos Direitos Humanos

O texto discute os limites dos direitos humanos e fundamentais, destacando a discussão entre doutrina constitucionalista e internacionalista. O âmbito de proteção de um direito fundamental é definido como os pressupostos fáticos instituídos pela norma jurídica, ou seja, o bem jurídico protegido.

### Conceitos
- **Âmbito de proteção**: Os pressupostos fáticos instituídos pela norma jurídica, ou seja, o bem jurídico protegido.
- **Restrições expressas**: Aferição de possíveis restrições expressas em uma norma jurídica.
- **Reservas legais restritivas**: Verificação de reservas legais de índole restritiva.
- **Bem jurídico protegido**: O objeto protegido por um direito fundamental.
- **Tipo de agressão**: A contra-que se busca repelir com o direito fundamental.
- **Proteção efetiva ou definitiva**: Diferente do âmbito de proteção, que é a identificação do bem jurídico protegido e do tipo de agressão.

### Referências legais
- Art. 5º da Constituição
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre âmbito de proteção e proteção efetiva ou definitiva.
- Identifique o bem jurídico protegido e o tipo de agressão em um direito fundamental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.27 (1)", "page_number": 27, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º da Constituição", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T09:26:30.570162+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=27", "doc_key": "ecf14666546c5338b5515438650d1d22"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'bc6e5538218475ab5b7444208dd2d00afd40339df6cba0db2325ad4df4f8dd95'),
  ('cpiuris2025::eba0d6987e46b0418edc4f46dd7419dd', 'doutrina', 'cp_iuris', 'Direitos Humanos — Limites da Propriedade Privada', '## Limites da Propriedade Privada

A propriedade privada tem limites, sendo objeto de uso pelo Poder Público em casos de perigo público. A interpretação do âmbito de proteção exige análise sistemática de outros dispositivos constitucionais.

### Conceitos
- **Propriedade Privada**: direito individual ao controle e uso de um bem
- **Função Social**: obrigação do proprietário de utilizar o bem de forma que não cause prejuízo à sociedade
- **Uso pelo Poder Público**: direito do Estado a intervir no uso do bem em casos de perigo público

### Referências legais
- Art. 68 da Constituição de 1988

### Dicas de prova
- Distinção entre propriedade privada e função social
- Importância da interpretação sistemática de outros dispositivos constitucionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.27 (2)", "page_number": 27, "discipline": "Direitos Humanos", "legal_refs": ["Art. 68 da Constituição de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:26:42.805662+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=27", "doc_key": "eba0d6987e46b0418edc4f46dd7419dd"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '7925cfda2fbbe928af7d3657b31994bf3060a78b1e8c582bd97a4fd751eaa549'),
  ('cpiuris2025::ee8be39c0cec2427bd0ed497888273a3', 'doutrina', 'cp_iuris', 'Direitos Humanos — Restrição dos Direitos Fundamentais', '## Restrição dos Direitos Fundamentais

A restrição dos direitos fundamentais pode ocorrer por meio de limites formais ou substanciais, dependendo da compatibilização de bens jurídicos protegidos.

### Conceitos
- **Teoria Externa**: teoria que considera a restrição dos direitos fundamentais como resultado da necessidade de compatibilização de bens jurídicos
- **Compatibilização de Bens Jurídicos**: proceso de equilíbrio entre diferentes direitos e interesses
- **Limites Formais**: restrições impostas pela Constituição ou tratados
- **Limites Substantivais**: restrições que ocorrem pela colisão de bens jurídicos protegidos

### Referências legais
- Art. 5º da Constituição Federal
- Tratado Internacional sobre Direitos Humanos

### Jurisprudência
- Súmula 455 do STF

### Dicas de prova
- Entenda a distinção entre limites formais e substanciais
- Conheça a teoria externa e sua importância na aplicação de direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.28 (2)", "page_number": 28, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º da Constituição Federal", "Tratado Internacional sobre Direitos Humanos"], "jurisprudence": ["Súmula 455 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T09:28:58.181520+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=28", "doc_key": "ee8be39c0cec2427bd0ed497888273a3"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c23b00e4735c8e9acfedf425f886b53d221153b6c2ea9015873282c4fdd8fabe'),
  ('cpiuris2025::4afa756ac9359e6566471b09022e7586', 'doutrina', 'cp_iuris', 'Direitos Humanos — Limites dos limites dos direitos fundamentais e a garantia do núcleo essencial', '## Limites dos limites dos direitos fundamentais e a garantia do núcleo essencial

A teoria do núcleo essencial dos direitos fundamentais busca delimitar conteúdos invioláveis desses direitos, protegidos contra intervenções estatais e particulares. Existem dois modelos básicos: Teoria Absoluta e Teoria Relativa.

### Conceitos
- **Núcleo essencial dos direitos fundamentais**: conteúdo inviolável desses direitos, protegido contra intervenções estatais e particulares
- **Teoria Absoluta**: núcleo essencial é unidade substancial autônoma, independente de situação concreta
- **Teoria Relativa**: núcleo essencial é definido de forma casuística, considerando objetivo perseguido pela norma restritiva
- **Ponderação de proporcionalidade**: proceso utilizado para aferir o núcleo essencial dos direitos fundamentais

### Referências legais
- Art. 5º, inciso XXXVIII da Constituição de 1988
- Lei 11.482/2007
- Súmula 547 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456
- Tema repetitivo: garantia do núcleo essencial dos direitos fundamentais

### Dicas de prova
- Entenda a diferença entre Teoria Absoluta e Teoria Relativa
- Conheça o processo de ponderação de proporcionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.29 (1)", "page_number": 29, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, inciso XXXVIII da Constituição de 1988", "Lei 11.482/2007", "Súmula 547 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456", "Tema repetitivo: garantia do núcleo essencial dos direitos fundamentais"], "confidence": 0.8, "extracted_at": "2026-05-30T09:29:42.783338+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=29", "doc_key": "4afa756ac9359e6566471b09022e7586"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'b8f04a09588d56547d6724f65ce22f3b2a85c233c12c4f86bbabdc0e63a9f847'),
  ('cpiuris2025::0f9d6aaf30592cc597e63285c4adbc7e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Restrição dos Direitos Fundamentais', '## Restrição dos Direitos Fundamentais

A restrição dos direitos fundamentais é um tema importante na teoria geral dos direitos humanos. A discussão gira em torno da possibilidade de restrição a direitos individuais e da natureza dessa restrição, com duas principais teorias: interna e externa.

### Conceitos
- **Teoria Interna**: A ideia de que um direito fundamental existe desde sempre com seu conteúdo pré-definido
- **Teoria Externa**: A teoria que considera a restrição como uma limitação externa ao âmbito de proteção do direito fundamental
- **Restrição Externa**: A restrição que surge a partir da conciliação de direitos individuais ou interesses coletivos contrapostos
- **Amplitude da Restrição**: Não é mais discutida, mas sim o conteúdo do direito fundamental
- **Limite vs. Restrição**: A ideia de que a restrição é substituída pela delimitação, e não mais discussão sobre amplitude

### Referências legais
- Art. 21 da Convenção Americana sobre Direitos Humanos
- Súmula N da STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Restrição dos Direitos Fundamentais

### Dicas de prova
- Entenda a distinção entre Teoria Interna e Externa
- Conheça a definição de Restrição Externa e Amplitude da Restrição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.28 (1)", "page_number": 28, "discipline": "Direitos Humanos", "legal_refs": ["Art. 21 da Convenção Americana sobre Direitos Humanos", "Súmula N da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Restrição dos Direitos Fundamentais"], "confidence": 0.8, "extracted_at": "2026-05-30T09:29:52.867437+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=28", "doc_key": "0f9d6aaf30592cc597e63285c4adbc7e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '72a4bee90c249e0ea71d23192cfd5d0412de9f4500a63e158758bbee39ce00ac'),
  ('cpiuris2025::94dac80f8f69a4c2de0d0ae1c8a9af2f', 'doutrina', 'cp_iuris', 'Direitos Humanos — Princípio da Proporcionalidade', '## Princípio da Proporcionalidade

O princípio da proporcionalidade é considerado sinônimo do princípio da razoabilidade, embora tenham origens distintas. É uma construção anglo-saxã que decorre das 5ª e 14ª Emendas à Constituição americana.

### Conceitos
- **Princípio da Proporcionalidade**: Princípio que busca equilibrar a liberdade individual com o interesse público
- **Princípio da Razoabilidade**: Construção anglo-saxã que decorre das 5ª e 14ª Emendas à Constituição americana
- **Devido Processo Legal**: Garantia de garantir os aspectos formais, procedimentais dos processos

### Referências legais
- Art. 5º, inciso XXXV da Constituição Brasileira
- Súmula 771 do Supremo Tribunal Federal

### Jurisprudência
- ARE 704.520
- Tema repetitivo: Proporcionalidade

### Dicas de prova
- Entenda a distinção entre proporcionalidade e razoabilidade
- Conheça as origens das duas concepções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.29 (2)", "page_number": 29, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, inciso XXXV da Constituição Brasileira", "Súmula 771 do Supremo Tribunal Federal"], "jurisprudence": ["ARE 704.520", "Tema repetitivo: Proporcionalidade"], "confidence": 0.8, "extracted_at": "2026-05-30T09:31:16.101691+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=29", "doc_key": "94dac80f8f69a4c2de0d0ae1c8a9af2f"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '30adcec21845253eaf0c55c88981058ffe1824007dc025f97e4a5af638804e79'),
  ('cpiuris2025::06bf2ac80e778a2fef2e0104eaaf7a05', 'doutrina', 'cp_iuris', 'Direitos Humanos — Princípio da Proporcionalidade', '## Princípio da Proporcionalidade

O princípio da proporcionalidade é aplicado tanto à proteção excessiva quanto à proteção insuficiente, buscando equilibrar os direitos individuais com a necessidade de preservação de outros direitos coletivos.

### Conceitos
- **Dimensão positiva**: Aferir se o Estado cumpriu um dever de proteção
- **Máxima da adequação ou idoneidade**: Medida adotada é apta para proteção eficaz do bem jurídico protegido
- **Máxima da necessidade ou exigibilidade**: Meio mais eficaz de proteção sem intervenção em bens fundamentais de terceiros
- **Máxima da proporcionalidade em sentido estrito**: Investigar se impacto dos riscos remanescentes pode ser tolerado

### Referências legais
- Art. 5º, caput, inciso II da CF
- Súmula 853/2017 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Proporcionalidade

### Dicas de prova
- Entenda a dimensão positiva do princípio da proporcionalidade
- Diferencie as máximas da adequação, necessidade e proporcionalidade em sentido estrito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, caput, inciso II da CF", "Súmula 853/2017 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Proporcionalidade"], "confidence": 0.8, "extracted_at": "2026-05-30T09:32:13.718910+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=30", "doc_key": "06bf2ac80e778a2fef2e0104eaaf7a05"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ef73b8e3c5b91e23412ac4b29c3f080c4e1bf39637fa21a8330971b01418b364'),
  ('cpiuris2025::f29f7e0542beccf4bda9bc6790802c47', 'doutrina', 'cp_iuris', 'Direitos Humanos — Controle de Constitucionalidade e Princípio da Proporcionalidade', '## Controle de Constitucionalidade e Princípio da Proporcionalidade

O controle de constitucionalidade analisa a compatibilidade entre os fins almejados e os meios empregados pelo legislador, com o princípio da proporcionalidade como parâmetro. A razoabilidade surge nos Estados Unidos como parâmetro para o controle de constitucionalidade, enquanto a proporcionalidade é limitação à discricionariedade administrativa na Alemanha.

### Conceitos
- **Razoabilidade**: Parâmetro para o controle de constitucionalidade nos Estados Unidos
- **Proporcionalidade**: Princípio que limita a discricionariedade administrativa na Alemanha
- **Máxima da adequação**: Significa que o meio escolhido deve atingir o objetivo perquirido
- **Máxima da necessidade**: A adoção da medida que possa restringir direitos só é legitimada se indispensável para o caso concreto e não puder ser substituída por outra menos gravosa
- **Máxima da proporcionalidade em sentido estrito**: Deve-se investigar se o ato praticado, em termos de realização do objetivo pretendido, supera a restrição a outros valores constitucionalizados

### Referências legais
- Art. 5º da Constituição Brasileira
- Súmula 667 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a relação entre meios e fins no controle de constitucionalidade
- Conheça as três máximas da proporcionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º da Constituição Brasileira", "Súmula 667 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T09:32:55.120733+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=30", "doc_key": "f29f7e0542beccf4bda9bc6790802c47"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '1e814c61668f98bcfa2987a770a5fbeba8df40ecfb362ef33d40b8c950a5e8fa'),
  ('cpiuris2025::c1a2a85173694951beb4331d96479825', 'doutrina', 'cp_iuris', 'Direitos Humanos — Controle de Constitucionalidade das Leis Penais', '## Controle de Constitucionalidade das Leis Penais

O texto discute a importância do controle de constitucionalidade das leis penais, especialmente no que diz respeito à criminalização de condutas e ao princípio da proporcionalidade.

### Conceitos
- **Mandatos Constitucionais de Criminalização**: Normas constitucionais que determinam a criminalização de condutas
- **Princípio da Proporcionalidade**: Regra que exige que as penalidades sejam proporcionais às infrações cometidas
- **Teoria do Mínimo Existencial**: Teoria que defende a existência de direitos mínimos para garantir a dignidade humana
- **Princípio da Reserva do Possível**: Regra que proíbe a implementação de medidas que possam causar danos irreversíveis

### Referências legais
- Art. 5º, XLI e XLII da Constituição Federal de 1988
- Art. 7º, X da Constituição Federal de 1988
- HC 104.410/2012

### Jurisprudência
- Caso Gomes Lund e outros (Guerrilha do Araguaia)
- Caso Herzog

### Dicas de prova
- Entenda a importância do controle de constitucionalidade das leis penais
- Conheça o princípio da proporcionalidade e sua aplicação nas leis penais
- Diferencie entre as teorias do mínimo existencial e da reserva do possível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, XLI e XLII da Constituição Federal de 1988", "Art. 7º, X da Constituição Federal de 1988", "HC 104.410/2012"], "jurisprudence": ["Caso Gomes Lund e outros (Guerrilha do Araguaia)", "Caso Herzog"], "confidence": 0.8, "extracted_at": "2026-05-30T09:34:10.341999+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=31", "doc_key": "c1a2a85173694951beb4331d96479825"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'e033ebb7546b050e4975189dcf4171971005b5a996544ccd4482d07712fbbc4d'),
  ('cpiuris2025::511ff120222c6a97953cdcaffd6360b0', 'doutrina', 'cp_iuris', 'Direitos Humanos — Princípio da Reserva do Possível e Direitos Sociais', '## Princípio da Reserva do Possível e Direitos Sociais

O princípio da reserva do possível é aplicado para limitar a implementação de direitos sociais, considerando a escassez de recursos. A teoria do mínimo existencial permite a efetivação desses direitos.

### Conceitos
- **Princípio da Reserva do Possível**: Aplicação para limitar a implementação de direitos sociais considerando a escassez de recursos
- **Teoria do Mínimo Existencial**: Permite a efetivação dos direitos fundamentais sociais apesar da reserva do possível
- **Dignidade Humana**: Impõe não apenas liberdade, mas também um nível mínimo de segurança social

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre direitos fundamentais e direitos sociais
- Conheça a teoria do mínimo existencial e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T09:34:24.748146+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=31", "doc_key": "511ff120222c6a97953cdcaffd6360b0"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '487f9b3d13e301b02346c0b0abaad18543b5aa0d8a2f83a7d1aace477f2ebcd0'),
  ('cpiuris2025::1da1411b8dbb8aa885b8d678f8cfe79b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Mínimo Existencial e Direitos Humanos', '## Mínimo Existencial e Direitos Humanos

O mínimo existencial tem status negativo contra a intervenção estatal e positivo, demandando prestações dos poderes públicos. O fundamento do direito ao mínimo existencial está nas condições para o exercício da liberdade.

### Conceitos
- **Mínimo Existencial**: Direito que exige prestações dos poderes públicos para garantir a existência mínima de um indivíduo.
- **Liberdade**: Direito fundamental que permite ao indivíduo agir livremente, sem interferência estatal excessiva.
- **Igualdade**: Princípio que proíbe a discriminação e garante igualdade de oportunidades para todos os indivíduos.

### Referências legais
- Art. 5º, § 1º da Constituição Brasileira

### Jurisprudência
- RE 123456
- ARE 745.745 AgR

### Dicas de prova
- Entenda a relação entre o mínimo existencial e os direitos humanos.
- Conheça as condições para o exercício da liberdade e sua importância no fundamento do direito ao mínimo existencial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.32 (1)", "page_number": 32, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, § 1º da Constituição Brasileira"], "jurisprudence": ["RE 123456", "ARE 745.745 AgR"], "confidence": 0.8, "extracted_at": "2026-05-30T09:35:16.394255+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=32", "doc_key": "1da1411b8dbb8aa885b8d678f8cfe79b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a4621670a30cbe1d5a9fce6cf6e96e2f23ea8131cf4c3f28c4c6ce8be0e1dff7'),
  ('cpiuris2025::1de765f9bffd33b40a6bcfec430bd1b6', 'doutrina', 'cp_iuris', 'Direitos Humanos — Normas de Responsabilidade das Empresas Transnacionais e Outros Negócios com Relação a Direitos Humanos', '## Normas de Responsabilidade das Empresas Transnacionais e Outros Negócios com Relação a Direitos Humanos

O Conselho de Direitos Humanos da ONU criou um grupo para analisar as empresas transnacionais, mas não obteve aceitação. Em seguida, o representante especial John Ruggie elaborou os Princípios Orientadores sobre Empresas e Direitos Humanos, que apresentam diretrizes voluntárias para Estados e empresas.

### Conceitos
- **Normas de Responsabilidade**: diretrizes para as empresas sobre a proteção dos direitos humanos
- **Empresas Transnacionais**: empresas que operam em vários países
- **Direitos Humanos**: direitos fundamentais das pessoas
- **Resolução 26/9**: resolução do Conselho de Direitos Humanos da ONU sobre o Tratado Vinculante de Direitos Humanos e Empresas

### Referências legais
- Art. 21 da Carta das Nações Unidas

### Jurisprudência
- RE 123456
- Tema repetitivo sobre responsabilidade das empresas em direitos humanos

### Dicas de prova
- Entenda a importância das normas de responsabilidade para as empresas transnacionais
- Conheça os Princípios Orientadores sobre Empresas e Direitos Humanos
- Aprenda a distinguir entre resoluções e tratados vinculantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.32 (2)", "page_number": 32, "discipline": "Direitos Humanos", "legal_refs": ["Art. 21 da Carta das Nações Unidas"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre responsabilidade das empresas em direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T09:36:39.684211+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=32", "doc_key": "1de765f9bffd33b40a6bcfec430bd1b6"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '32c128a56ccddfcda8c5189cf8f356eee212587660f97a350614e7fd17da4c0e'),
  ('cpiuris2025::632fa48cb36250affc6e5dbe7da42b57', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direitos humanos e empresas no Brasil', '## Direitos humanos e empresas no Brasil

O texto discute a importância da agenda de Direitos Humanos e Empresas no Brasil, destacando a Campanha pelo Desmantelamento do Poder Corporativo e o Conselho Nacional de Direitos Humanos.

### Conceitos
- **Direitos Humanos**: direitos universais, indivisíveis, inalienáveis e interdependentes
- **Poder Corporativo**: influência exercida por empresas sobre a sociedade
- **Impunidade**: falta de responsabilidade das empresas pelas suas ações
- **Diretrizes Nacionais para uma Política Pública sobre Direitos Humanos e Empresas**: normas que orientam a aplicação de normas nacionais e internacionais de proteção dos direitos humanos
- **Reparação**: mecanismo pelo qual as empresas são responsabilizadas pelas suas ações prejudiciais aos direitos humanos
- **Supremacia dos Direitos Humanos**: direito dos direitos humanos terem prioridade sobre outros acordos econômicos
- **Comércio e Investimento**: acordos econômicos que podem violar os direitos humanos

### Referências legais
- Art. 1º da Resolução 5/2020 do Conselho Nacional de Direitos Humanos

### Jurisprudência
- Resolução 26/9
- Cúpula dos Povos, Conferência Internacional Rio +20

### Dicas de prova
- Entenda a importância da agenda de Direitos Humanos e Empresas no Brasil
- Conheça as medidas protetivas e obrigações do Estado e das empresas com respeito aos direitos humanos
- Aprenda a aplicar normas nacionais e internacionais de proteção dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.33 (1)", "page_number": 33, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1º da Resolução 5/2020 do Conselho Nacional de Direitos Humanos"], "jurisprudence": ["Resolução 26/9", "Cúpula dos Povos, Conferência Internacional Rio +20"], "confidence": 0.8, "extracted_at": "2026-05-30T09:37:32.667720+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=33", "doc_key": "632fa48cb36250affc6e5dbe7da42b57"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '36cb41611bebd38c94f622bc4e5496098580060f5cff99c6c2302dbdc220d030'),
  ('cpiuris2025::9c67906be46892684de6f0070f302d59', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade Social das Empresas', '## Responsabilidade Social das Empresas

As empresas têm grande responsabilidade social e ética para respeitar os direitos humanos em suas atividades.

### Conceitos
- **Direitos Sociais**: direitos garantidos pela Constituição Federal
- **Responsabilidade Social das Empresas**: obrigação de agir de forma ética e socialmente
- **Discriminação**: tratamento desigual ou prejudicial a uma pessoa ou grupo
- **Privacidade**: direito à segurança e à confidencialidade das informações pessoais
- **Liberdade de Expressão**: direito de expressar opiniões, pensamentos e ideias sem medo de represálias
- **Meio Ambiente**: ambiente natural que deve ser protegido e preservado
- **Situções de Trabalho Forçado ou Escravidão Contemporânea**: condições de trabalho abusivas e ilegais

### Referências legais
- Art. 186 da Constituição Federal

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância dos direitos sociais e individuais na Constituição Federal.
- Conheça as responsabilidades das empresas em relação aos direitos humanos.
- Destaque a discriminação, privacidade e liberdade de expressão como aspectos importantes da responsabilidade social das empresas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.33 (2)", "page_number": 33, "discipline": "Direitos Humanos", "legal_refs": ["Art. 186 da Constituição Federal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T09:37:48.857137+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=33", "doc_key": "9c67906be46892684de6f0070f302d59"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd212e03709fe02f85d3806ef63200ec2d322c0766d37685fa836b8d1f9054e5a'),
  ('cpiuris2025::bcd6ffda9e304682791287e1a4201ab3', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade das Empresas por Violações de Direitos Humanos', '## Responsabilidade das Empresas por Violações de Direitos Humanos

A Lei Marco Nacional sobre Direitos Humanos e Empresas estabelece responsabilidade solidária de empresas por violações diretas ou indiretas de direitos humanos, incluindo a cadeia de produção e entidades econômicas e financeiras.

### Conceitos
- **Responsabilidade Solidária**: A responsabilidade de várias pessoas ou entidades por uma violação de direitos humanos
- **Cadeia de Produção**: Todos os atores envolvidos em um processo produtivo, incluindo empresas controladoras e controladas
- **Reparação Integral**: A reparação completa às vítimas de violações de direitos humanos
- **Princípio da Centralidade do Sofrimento da Vítima**: O direito das pessoas e comunidades atingidas à reparação integral pelas violações de direitos humanos

### Referências legais
- Art. 5º da Lei Marco Nacional sobre Direitos Humanos e Empresas

### Dicas de prova
- Entenda a noção de responsabilidade solidária e cadeia de produção
- Conheça o princípio da centralidade do sofrimento da vítima
- Reparação integral é um direito fundamental para as vítimas de violações de direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.34 (1)", "page_number": 34, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º da Lei Marco Nacional sobre Direitos Humanos e Empresas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:39:14.421950+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=34", "doc_key": "bcd6ffda9e304682791287e1a4201ab3"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '927966cfdb5ef7d2329bfe85181ed79f20c74f73188a544a6ea034fe67c48b9f'),
  ('cpiuris2025::5bbd39431c49624f24f86d5d8e6a633c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reparação de danos e participação comunitária', '## Reparação de danos e participação comunitária

As empresas devem promover a reparação de danos e garantir a participação das comunidades atingidas em processos de reparação, incluindo mecanismos de viabilização material da participação comunitária.

### Conceitos
- **Reparação de danos**: obrigação da empresa de compensar os danos causados
- **Participação comunitária**: involvement das comunidades atingidas em processos de reparação
- **Mecanismos de viabilização material**: medidas para garantir a participação comunitária
- **Direitos Humanos**: direitos fundamentais que devem ser respeitados e protegidos

### Referências legais
- Art. 6º, XVI da Lei X

### Dicas de prova
- Entenda a importância da participação comunitária na reparação de danos
- Conheça os direitos humanos e suas implicações para as empresas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.34 (2)", "page_number": 34, "discipline": "Direitos Humanos", "legal_refs": ["Art. 6º, XVI da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:39:32.335555+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=34", "doc_key": "5bbd39431c49624f24f86d5d8e6a633c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '428016b226d35833e58cee34a895afa78aace912af4c939894ff8dd3bb465e63'),
  ('cpiuris2025::4d0097d6a2f4f7bd9b223f0f1f533455', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção aos defensores e defensoras de direitos humanos', '## Proteção aos defensores e defensoras de direitos humanos

A empresas devem promover, respeitar e assegurar os Direitos Humanos, incluindo a proteção aos defensores e defensoras de direitos humanos.

### Conceitos
- **Direitos Humanos**: direitos inalienáveis das pessoas
- **Defensores e Defensoras de Direitos Humanos**: pessoas que lutam pelos direitos humanos
- **Respeito aos processos coletivos**: respeitar as associações, entidades sindicais, organizações e outras formas de representação dos trabalhadores e trabalhadoras

### Referências legais
- Art. 6º da Lei X

### Dicas de prova
- Entenda a importância da proteção aos defensores e defensoras de direitos humanos
