  ('cpiuris2025::5f2b2020802205dd90b89f45b1ee470e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Conceito, evolução histórica e dimensões dos Direitos Humanos', '## Conceito, evolução histórica e dimensões dos Direitos Humanos

A questão pergunta sobre a definição do conceito de direitos humanos, sua evolução histórica e suas dimensões. O texto destaca a proteção prevista para as pessoas naturais que violam direitos humanos.

### Conceitos
- **Direitos Humanos**: são direitos inerentes à dignidade humana, garantidos por normas jurídicas
- **Direitos Fundamentais**: são direitos que podem ser relativizados no caso concreto, dependendo da ordem jurídica em questão

### Referências legais
- Art. 5º da Constituição Federal
- Declaração Universal dos Direitos Humanos

### Jurisprudência
- Súmula 326 do STF

### Dicas de prova
- Entenda a distinção entre direitos humanos e fundamentais
- Conheça a evolução histórica dos direitos humanos
- Identifique as dimensões dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.35 (2)", "page_number": 35, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º da Constituição Federal", "Declaração Universal dos Direitos Humanos"], "jurisprudence": ["Súmula 326 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T09:40:05.579907+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=35", "doc_key": "5f2b2020802205dd90b89f45b1ee470e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd8c61d78dc1325c145b64b63e9ea84790368738ba3cdcbae1eeac2e11d6de144'),
  ('cpiuris2025::6637a13f6498d20c81c731cb80262bc5', 'doutrina', 'cp_iuris', 'Direitos Humanos — Marcos Históricos dos Direitos Humanos', '## Marcos Históricos dos Direitos Humanos

Os direitos humanos evoluíram ao longo da história, com marcos fundamentais como o iluminismo, o constitucionalismo e o socialismo.

### Conceitos
- **Direitos Humanos**: direitos inalienáveis de cada pessoa
- **Iluminismo**: movimento que promoveu a razão e a liberdade
- **Constitucionalismo**: sistema político baseado em uma constituição
- **Socialismo**: economia e política que visam igualar as condições de vida

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

