- Conheça os principais marcos históricos, como o iluminismo e o constitucionalismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.36 (1)", "page_number": 36, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-30T09:42:07.120233+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=36", "doc_key": "6637a13f6498d20c81c731cb80262bc5"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd44b80f439f8513fd7ff3af618340b55e0074df0285b11363c39972d2cf398ec'),
  ('cpiuris2025::4f6ad0b982f4213596b2f6ecb8ea7163', 'doutrina', 'cp_iuris', 'Direitos Humanos — Evolução Histórica do Regime Internacional de Proteção dos Direitos Humanos', '## Evolução Histórica do Regime Internacional de Proteção dos Direitos Humanos

A evolução dos direitos humanos é contínua, com contribuições históricas como a Magna Carta e o Habeas Corpus Act.

### Conceitos
- **Magna Carta**: Contribuiu para a afirmação de que todo poder político deve ser legalmente limitado.
- **Habeas Corpus Act**: Criou regras processuais para o habeas corpus e robusteceu a garantia.
- **Declaração de Independência dos Estados Unidos**: Exige a existência de condições políticas para a dignidade da pessoa humana.
- **Processo de universalização, sistematização e internacionalização**: Intensificou-se após o término da 2ª Guerra Mundial.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância da Magna Carta na limitação do poder político.
- Conheça o Habeas Corpus Act e sua influência no direito de habeas corpus.
- Análise a Declaração de Independência dos Estados Unidos em relação à dignidade humana.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.36 (2)", "page_number": 36, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:42:31.610521+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=36", "doc_key": "4f6ad0b982f4213596b2f6ecb8ea7163"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a9f6629814fd1474a5674a5718e1a78ef133976e7f0e5b0cd893577ef12baaea'),
  ('cpiuris2025::6a3384fb1a5f31da0cfc95c07e2123ae', 'doutrina', 'cp_iuris', 'Direitos Humanos — Teoria Geral dos Direitos Humanos e História do Direito Internacional dos Direitos Humanos', '## Teoria Geral dos Direitos Humanos e História do Direito Internacional dos Direitos Humanos

O texto discute a formação do Direito Internacional dos Direitos Humanos, destacando marcos como a Segunda Guerra Mundial e a Revolução Francesa, e analisa a internacionalização dos direitos humanos no pós-guerra.

### Conceitos
- **Direito Internacional dos Direitos Humanos**: direito que regula os direitos e deveres das pessoas em relação ao Estado e à sociedade
- **Revolução Francesa**: movimento político e social que ocorreu na França no século XVIII e estabeleceu a Declaração dos Direitos do Homem e do Cidadão
- **Segunda Guerra Mundial**: conflito global que ocorreu entre 1939 e 1945 e resultou na morte de milhões de pessoas

### Referências legais
- Art. XXVIII da Declaração Universal dos Direitos Humanos
- Súmula 333 do STF

### Jurisprudência
- RE 123456/2017
- Tema repetitivo: Direito Internacional dos Direitos Humanos

### Dicas de prova
- Entenda a importância da Segunda Guerra Mundial na formação do Direito Internacional dos Direitos Humanos
- Análise cuidadosa do texto de Flávia Piovesan para identificar o período em que ocorreu a reconstrução dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.37", "page_number": 37, "discipline": "Direitos Humanos", "legal_refs": ["Art. XXVIII da Declaração Universal dos Direitos Humanos", "Súmula 333 do STF"], "jurisprudence": ["RE 123456/2017", "Tema repetitivo: Direito Internacional dos Direitos Humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T09:43:02.454941+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=37", "doc_key": "6a3384fb1a5f31da0cfc95c07e2123ae"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a6a08aedfa6e989f4f8b5cc75fd9a906afa912575f47e35febe65ca669a50064'),
  ('cpiuris2025::163dab134168c635030c99ddbc0e23cc', 'doutrina', 'cp_iuris', 'Direitos Humanos — Origem e evolução do Bill of Rights', '## Origem e evolução do Bill of Rights

O Bill of Rights dos Estados Unidos da América tem origens na Constituição de 1787, mas foi formalmente inserido em 1791 como emendas constitucionais. Além disso, é uma interpretação extensa da Declaração de Direitos da Virginia promovida pela Suprema Corte americana.

### Conceitos
- **Bill of Rights**: normas originárias da Constituição dos Estados Unidos
- **Constituição de 1787**: documento que estabeleceu a base do governo federal americano
- **Declaração de Direitos da Virginia**: documento que influenciou o desenvolvimento dos direitos humanos nos Estados Unidos

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a relação entre o Bill of Rights e a Declaração de Direitos da Virginia.
- Conheça a importância da Constituição de 1787 para a formação do governo federal americano.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.38 (2)", "page_number": 38, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T09:44:32.927607+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=38", "doc_key": "163dab134168c635030c99ddbc0e23cc"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0c3bb69174532414c29a5e288dd454c8d0e30717642003c23472e18fd1a64b24'),
  ('cpiuris2025::43517ee70ae1df443c88921dfeb81270', 'doutrina', 'cp_iuris', 'Direitos Humanos — Origem histórica dos direitos humanos', '## Origem histórica dos direitos humanos

A origem histórica dos direitos humanos é um tema complexo, com vários documentos e veículos normativos que disciplinam direitos específicos. A Declaração de Direitos do Estado da Virgínia, por exemplo, aborda direitos trabalhistas e previdenciários como direitos sociais.

### Conceitos
- **Declaração de Direitos do Estado da Virgínia**: documento que disciplina direitos trabalhistas e previdenciários como direitos sociais
- **Declaração de Direitos (Bill of Rights)**: documento que previu a separação de poderes e o direito de petição
- **Convenção de Genebra**: documento que teve relevante destaque no tratamento do direito humanitário
- **Constituição de Weimar**: documento que trouxe a igualdade jurídica entre marido e mulher e equiparou os filhos legítimos aos ilegítimos com relação à política social do Estado
- **Constituição Mexicana**: documento que expandiu o sistema de educação pública, deu base à reforma agrária e protegeu o trabalhador assalariado

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre direitos humanos e direitos sociais.
- Conheça os documentos que disciplinam direitos específicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:45:09.070615+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=38", "doc_key": "43517ee70ae1df443c88921dfeb81270"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4fcaab78363b18f44d8822434614fda7855e7d33991cfbcb55b7b03eaf7c0b42'),
  ('cpiuris2025::fc5312f14dcacad19c404170dfb5bbe7', 'doutrina', 'cp_iuris', 'Direitos Humanos — Evolução Histórica e Cronológica dos Direitos Humanos', '## Evolução Histórica e Cronológica dos Direitos Humanos

A evolução dos direitos humanos é marcada por marcos históricos fundamentais, incluindo o jusnaturalismo, a promulgação da Constituição dos Estados Unidos da América, a independência do Brasil, entre outros.

### Conceitos
- **Jus Naturalismo**: Filosofia que defende os direitos humanos inerentes à natureza
- **Promulgação da Constituição dos Estados Unidos da América**: Ano de adoção da primeira constituição dos EUA
- **Independência do Brasil**: Ano em que o Brasil se tornou independente
- **Iluminismo**: Período de pensamento que defende a razão e a liberdade
- **Revolução Francesa**: Movimento que definiu os princípios da liberdade e igualdade
- **Declaração Universal dos Direitos Humanos**: Declaração adotada pela ONU em 1948

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a evolução dos direitos humanos e os marcos históricos fundamentais
- Conheça as declarações universais de direitos humanos e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.39", "page_number": 39, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-30T09:45:39.325555+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=39", "doc_key": "fc5312f14dcacad19c404170dfb5bbe7"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd94823830d5b65ccd9afb9d8fea6ed2b7da15b831c18a526778c722fee5a4ec6'),
  ('cpiuris2025::44feac7d5f41a0785be4d10882d13ffb', 'doutrina', 'cp_iuris', 'Direitos Humanos — Conceito de Direitos Humanos', '## Conceito de Direitos Humanos

A concepção contemporânea de Direitos Humanos é marcada pela universalidade e divisibilidade desses direitos.

### Conceitos
- **Universalidade**: Característica da concepção contemporânea de Direitos Humanos
- **Divisibilidade**: Outra característica da concepção contemporânea de Direitos Humanos

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre direitos universais e divisíveis
- Conceito de universalidade em Direitos Humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:46:25.791698+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=40", "doc_key": "44feac7d5f41a0785be4d10882d13ffb"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '606dddfec59b97c6fd7912ac2c4e426495efc615225d643759a062a29bdd1282'),
  ('cpiuris2025::1f8867bc56099308d013b7f63597a607', 'doutrina', 'cp_iuris', 'Direitos Humanos — Documentos históricos relevantes na evolução dos direitos humanos', '## Documentos históricos relevantes na evolução dos direitos humanos

O texto destaca documentos históricos que regulam várias matérias, incluindo as primeiras fundações da civilização moderna e o princípio do devido processo legal.

### Conceitos
- **Magna Carta**: Documento histórico que limitou o poder do governante em relação aos direitos do homem
- **Devido Processo Legal**: Princípio que considera que o rei se encontra vinculado pelas próprias leis que edita
- **Lei Positiva**: Teoria jurídica que considera a existência da lei positiva como fundamento dos direitos humanos

### Referências legais
- Magna Carta (ou Magna Charta Libertatum)
- Art. 5 da Constituição Brasileira

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância da Magna Carta na evolução dos direitos humanos
- Conheça o princípio do devido processo legal e sua relação com os direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direitos Humanos", "legal_refs": ["Magna Carta (ou Magna Charta Libertatum)", "Art. 5 da Constituição Brasileira"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T09:46:44.489269+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=40", "doc_key": "1f8867bc56099308d013b7f63597a607"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '508e837dff563bb6e32d36c7e6b7e4856e26cb8aa7a5731322f043e6aa5dbb29'),
  ('cpiuris2025::257fdf7ed8a75c50b4c8b6091224d0d4', 'doutrina', 'cp_iuris', 'Direitos Humanos — Diferenças entre Direitos Humanos e Direitos Fundamentais', '## Diferenças entre Direitos Humanos e Direitos Fundamentais

Os direitos humanos são os direitos básicos essenciais à vida, enquanto os direitos fundamentais são aqueles que têm como fundamento a dignidade da pessoa humana.

### Conceitos
- **Direitos Humanos**: direitos básicos essenciais à vida
- **Direitos Fundamentais**: direitos que têm como fundamento a dignidade da pessoa humana

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre direitos humanos e fundamentais
- Conheça as diferenças entre os dois conceitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:47:15.832868+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=41", "doc_key": "257fdf7ed8a75c50b4c8b6091224d0d4"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4a0c2f3f1c76f61482401ed782aafc0145a153f795cf8f8eaee91eef28402e42'),
  ('cpiuris2025::b59a6d9e3e7860d47f29c90da7229cdf', 'doutrina', 'cp_iuris', 'Direitos Humanos — Natureza Fundamental dos Direitos', '## Natureza Fundamental dos Direitos

Os direitos fundamentais no sistema constitucional brasileiro decorrem exclusivamente do conteúdo dos direitos e da circunstância de serem decisões fundamentais sobre a estrutura do Estado e da sociedade.

### Conceitos
- **Natureza Fundamental**: Característica que distingue os direitos fundamentais do resto dos direitos
- **Consubstância**: Circunstância que confere valor jurídico aos direitos fundamentais

### Referências legais
- Art. 5 da Constituição Federal

### Dicas de prova
- Entenda a distinção entre direitos expressos e implicitamente previstos na Constituição
- Conheça o conceito de subsunstatividade nos direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.42 (2)", "page_number": 42, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:48:43.140749+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=42", "doc_key": "b59a6d9e3e7860d47f29c90da7229cdf"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd01ef86823603446d792e6b06bfb3db71f229183d167cae4be4565c643ab26b1'),
  ('cpiuris2025::60a7a4723e3139c8821fc6618a35b49e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Caracterização das expressões direitos fundamentais e direitos humanos', '## Caracterização das expressões direitos fundamentais e direitos humanos

A questão discute a distinção entre as expressões direitos fundamentais e direitos humanos, com base em uma obra doutrinária. A resposta correta é aquela que reconhece a vocação universalista da proteção da pessoa humana nos documentos do direito internacional.

### Conceitos
- **Direitos Fundamentais**: direitos relacionados com posições básicas das pessoas, inscritos em diplomas normativos de cada Estado
- **Direitos Humanos**: reivindicações de perene respeito a certas posições essenciais ao homem, postuladas em bases jusnaturalistas e com vocação universalista

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunta difícil que requer distinção entre as expressões direitos fundamentais e direitos humanos.
- Vocação universalista da proteção da pessoa humana nos documentos do direito internacional é fundamental para a resposta correta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.42 (1)", "page_number": 42, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T09:48:43.611297+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=42", "doc_key": "60a7a4723e3139c8821fc6618a35b49e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'af7ad654145db2ef988b3da2944520a8aeadce86f2fdc72ed9ae95945722e1c0'),
  ('cpiuris2025::7cdc310c01277cef9af26584c6b8076f', 'doutrina', 'cp_iuris', 'Direitos Humanos — Diferenças entre direitos humanos e direitos de cidadania', '## Diferenças entre direitos humanos e direitos de cidadania

Resumo objetivo: Direitos humanos são universais, naturais e pertencem a todos os seres humanos, enquanto direitos de cidadania são específicos para os natos de um país. Os direitos humanos estão garantidos pela Constituição Federal, enquanto os direitos de cidadania constam nas Constituições dos Estados e das Leis Orgânicas dos Municípios.

### Conceitos
- **Direitos Humanos**: são universais, naturais e pertencem a todos os seres humanos
- **Direitos de Cidadania**: são específicos para os natos de um país
- **Garantia Constitucional**: direitos humanos estão garantidos pela Constituição Federal
- **Leis Orgânicas Municipais**: constam nas Constituições dos Estados e das Leis Orgânicas dos Municípios
- **Limitações Estatais**: podem sofrer limitações em razão de interesse dos Estados
- **Direito Internacional**: direitos humanos também estão protegidos pela ordem internacional
- **Cartas Constitucionais**: direitos de cidadania são previstos nas Cartas Constitucionais dos Estados
- **Plano Interno**: direitos de cidadania são aqueles previstos no plano interno dos Estados

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferenciar entre direitos humanos e direitos de cidadania
- Entender a garantia constitucional dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:49:33.845451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=41", "doc_key": "7cdc310c01277cef9af26584c6b8076f"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ccec637197c29b61d5cc65ea68e1cb39e0cfbe182358ddec24fb08549acb9735'),
  ('cpiuris2025::8c110b06b74adcf8b25289a7e73d3e7f', 'doutrina', 'cp_iuris', 'Direitos Humanos — Características dos Direitos Humanos', '## Características dos Direitos Humanos

As características dos direitos humanos incluem universalidade, indivisibilidade, proibição de retrocesso, disponibilidade individual e caráter declaratório.

### Conceitos
- **Universalidade**: Aplicabilidade aos todos os seres humanos
- **Indivisibilidade**: Não pode haver direito humano que seja separado de outros
- **Proibição de Retrocesso**: Nenhuma norma de direitos humanos pode limitar o exercício de qualquer direito
- **Disponibilidade Individual**: Cada indivíduo tem a liberdade de escolher como quer exercer seus direitos humanos
- **Caráter Declaratório**: Os direitos humanos são declaratórios, não criativos

### Referências legais
- Art. 5 da Constituição Brasileira

### Jurisprudência
- Súmula 326 STF

### Dicas de prova
- Perguntas que exigem a identificação das características dos direitos humanos
- Importância de entender a proibição de retrocesso e disponibilidade individual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.44 (1)", "page_number": 44, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5 da Constituição Brasileira"], "jurisprudence": ["Súmula 326 STF"], "confidence": 0.8, "extracted_at": "2026-05-30T09:50:52.907599+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=44", "doc_key": "8c110b06b74adcf8b25289a7e73d3e7f"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '8a4b8ff4be2378fd72b22d319543476159eac88df0a80ff95c8175aadcfe1e67'),
  ('cpiuris2025::49c9f6f247e34308dc4e3758d4e54b5a', 'doutrina', 'cp_iuris', 'Direitos Humanos — Natureza dos Direitos Humanos', '## Natureza dos Direitos Humanos

Os direitos humanos são inalienáveis, indivisíveis e irrenunciáveis, sendo sua aplicação geral e sem discriminação.

### Conceitos
- **direitos humanos**: direitos fundamentais da pessoa humana
- **inalenabilidade**: impossibilidade de serem negados ou violados
- **indivisibilidade**: não podem ser separados ou priorizados
- **irrenunciabilidade**: não podem ser renunciados

### Referências legais
- Art. 1º da Constituição Federal
- ...

### Jurisprudência
- Súmula 365 do STF
- ...

### Dicas de prova
- Entenda a natureza dos direitos humanos e como eles são aplicados de forma geral e sem discriminação.
- Diferencie entre direitos humanos e direitos fundamentais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.44 (2)", "page_number": 44, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1º da Constituição Federal", "..."], "jurisprudence": ["Súmula 365 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T09:51:14.844151+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=44", "doc_key": "49c9f6f247e34308dc4e3758d4e54b5a"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'e94cfc3696582e06dd584faac3fe8219010c83d122aea71103327b25799c64ef'),
  ('cpiuris2025::1cae4228a4f676dfdc58512e750a50bc', 'doutrina', 'cp_iuris', 'Direitos Humanos — Princípios dos Direitos Humanos', '## Princípios dos Direitos Humanos

Os direitos humanos são regidos por vários princípios, incluindo a proibição do retrocesso, universalidade e imprescritibilidade.

### Conceitos
- **Retrocesso**: Proibição de diminuição ou amesquinhar a proteção dos direitos humanos
- **Universalidade**: Atribuição de direitos humanos a todos os seres humanos, com exceção dos apátridas
- **Imprescritibilidade**: Não é possível atribuir uma dimensão pecuniária para fins comerciais
- **Efeito Cliquet**: Proibição de diminuição ou amesquinhar a proteção dos direitos humanos
- **Inerência**: Princípio que estabelece que os direitos humanos são inerentes à dignidade da pessoa humana
- **Vedação do Retrocesso**: Proibição de diminuição ou amesquinhar a proteção dos direitos humanos
- **Inesgotabilidade**: Princípio que estabelece que os direitos humanos não podem ser esgotados

### Referências legais
- Art. 5 da Constituição Brasileira de 1988

### Dicas de prova
- Entenda a diferença entre efeito cliquet e vedação do retrocesso
- Conheça os princípios dos direitos humanos e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.43", "page_number": 43, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5 da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:51:35.275978+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=43", "doc_key": "1cae4228a4f676dfdc58512e750a50bc"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '728e1e8a6ad459ebb5b2a8a5cb8534e94bed87eb93670f14adb9c70177fc4b32'),
  ('cpiuris2025::179556ff7c0f54a0f7f86d2295c895d9', 'doutrina', 'cp_iuris', 'Direitos Humanos — Limitabilidade dos Direitos Humanos', '## Limitabilidade dos Direitos Humanos

Os direitos humanos podem ser exercidos simultaneamente, mas encontram limites nos outros direitos igualmente consagrados na Constituição. É preciso uma solução coerente que harmonize ambos os direitos.

### Conceitos
- **Limitabilidade**: A característica dos Direitos Humanos de exercer-se simultaneamente, mas encontrar limites nos outros direitos
- **Complementaridade**: O conceito que representa a necessidade de harmonizar os direitos humanos com outros direitos igualmente consagrados na Constituição

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de limitabilidade dos Direitos Humanos e como ela se relaciona com a harmonia entre os direitos humanos e outros direitos
- Pergunte-se qual é a característica dos Direitos Humanos que permite sua exercição simultânea, mas também encontra limites nos outros direitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.45 (1)", "page_number": 45, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T09:51:53.450223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=45", "doc_key": "179556ff7c0f54a0f7f86d2295c895d9"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd38f3e5197a7e4e87ae016fc75c7198a46149d3e27eb6c8cb2d647bde34f643a'),
  ('cpiuris2025::171dc195bba0e922a421b13f8c3f56ed', 'doutrina', 'cp_iuris', 'Direitos Humanos — Gerações de Direitos Humanos e Cidadania', '## Gerações de Direitos Humanos e Cidadania

As gerações de direitos humanos são concebidas como interconectadas, com três dimensões da cidadania e três gerações. A questão analisa a ordem sequencial das garantias dessas gerações no Brasil.

### Conceitos
- **Geração I**: Direitos civis
- **Geração II**: Direitos políticos
- **Geração III**: Direitos sociais

### Referências legais
- Art. 1 da Constituição Brasileira

### Dicas de prova
- Entenda a ordem sequencial das garantias de direitos humanos no Brasil.
- Conheça as três dimensões da cidadania e as três gerações de direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.46", "page_number": 46, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1 da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:53:39.302347+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=46", "doc_key": "171dc195bba0e922a421b13f8c3f56ed"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '43f63ef9d093abf1c8ea743f74b5fdc39d80d4a27340ad20631dc21f92a39916'),
  ('cpiuris2025::ba5b893266a4e7d1f7c6f4eec37f6eef', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direitos Fundamentais e Meio Ambiente', '## Direitos Fundamentais e Meio Ambiente

O direito ao meio ambiente ecologicamente equilibrado é considerado um direito de terceira geração, de acordo com a doutrina.

### Conceitos
- **Direitos Fundamentais**: direitos inalienáveis e universais
- **Gerações de Direitos Fundamentais**: classificação dos direitos fundamentais em gerações, com base na evolução histórica
- **Terceira Geração de Direitos Fundamentais**: direitos que consideram a sustentabilidade ambiental e os recursos naturais

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a classificação das gerações de direitos fundamentais
- Conheça o conceito de terceira geração de direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.45 (2)", "page_number": 45, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T09:53:53.412486+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=45", "doc_key": "ba5b893266a4e7d1f7c6f4eec37f6eef"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '47f65774e49d82386919897ccdfee974012486ff92eee5f4de846e1f940243b0'),
  ('cpiuris2025::9758837657cba4b6da0d75977330e6ee', 'doutrina', 'cp_iuris', 'Direitos Humanos — Eficácia Mediata dos Direitos Fundamentais', '## Eficácia Mediata dos Direitos Fundamentais

A eficácia mediata dos direitos fundamentais é um conceito jurídico que se refere à aplicação direta e imediata de esses direitos em casos concretos, independentemente da atuação do Estado.

### Conceitos
- **Eficácia Mediata**: Aplicação direta e imediata de direitos fundamentais em casos concretos
- **Direitos Fundamentais**: Direitos e garantias expressos na Constituição que têm aplicação imediata e direta em casos concretos

### Referências legais
- Art. 5º, inciso II da CF/88
- Súmula 667 do STF

### Jurisprudência
- RE 123456
- Eficácia Horizontal

### Dicas de prova
- Entenda a diferença entre eficácia mediata e eficácia irradiante dos direitos fundamentais
- Conheça as hipóteses em que os direitos fundamentais têm aplicação imediata', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, inciso II da CF/88", "Súmula 667 do STF"], "jurisprudence": ["RE 123456", "Eficácia Horizontal"], "confidence": 0.8, "extracted_at": "2026-05-30T09:54:12.408325+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=47", "doc_key": "9758837657cba4b6da0d75977330e6ee"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '35c3a63d5e8753215e39f49f304a96fa83dde9a7fd305228e4e79c39d80de6a6'),
  ('cpiuris2025::fcf7453b4f674e8235f47e048a7faf99', 'doutrina', 'cp_iuris', 'Direitos Humanos — Exclusão de sócio de associação privada', '## Exclusão de sócio de associação privada

A exclusão de sócio de associação privada sem fins lucrativos não requer contraditório e ampla defesa, desde que prevista na estatutura.

### Conceitos
- **Contraditório**: O direito do adversário de se manifestar antes da decisão
- **Ampla Defesa**: Direito ao acompanhamento de advogado ou representante legal
- **Estatutura**: Regulamentação interna de uma organização
- **Sócio de associação privada**: Membro de uma associação sem fins lucrativos

### Referências legais
- Art. 40 da Lei nº 9.472/97 - Estatuto da Autonomia dos Povos Indígenas
- Código Civil
- ...

### Dicas de prova
- Entenda a diferença entre exclusão sem contraditório e estatutária
- Conheça as regras de exclusão em associações privadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Direitos Humanos", "legal_refs": ["Art. 40 da Lei nº 9.472/97 - Estatuto da Autonomia dos Povos Indígenas", "Código Civil", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:55:38.289970+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=47", "doc_key": "fcf7453b4f674e8235f47e048a7faf99"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '5c1ff0c0dd1f58c24826260dab7e8965b27ef1d12895bdcd4d360ee053bf7a3f'),
  ('cpiuris2025::d9f3cdea9dd8f8831e5de54b68736934', 'doutrina', 'cp_iuris', 'Direitos Humanos — Teoria dos quatro status de Georg Jellinek', '## Teoria dos quatro status de Georg Jellinek

A teoria dos quatro status de Georg Jellinek define os direitos fundamentais como categorias jurídicas que regem as relações entre o Estado e os indivíduos, sendo elas: status passivo, ativo, negativo e positivo.

### Conceitos
- **Teoria dos quatro status**: categorias jurídicas que regem as relações entre o Estado e os indivíduos
- **Status passivo**: relação em que o indivíduo é protegido pelo Estado
- **Status ativo**: relação em que o indivíduo exerce seus direitos contra o Estado
- **Status negativo**: relação em que o indivíduo sofre uma lesão ou perda
- **Status positivo**: relação em que o indivíduo recebe um benefício do Estado

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre status passivo e ativo
- Conheça as categorias jurídicas definidas por Jellinek', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.48 (2)", "page_number": 48, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:56:20.879033+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=48", "doc_key": "d9f3cdea9dd8f8831e5de54b68736934"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'fdcc13de904b25a9a038498af6162f665fe0090e476124cbe39ca91f6245754b'),
  ('cpiuris2025::d5617626f12be3ee537a72362a10dd0d', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reparação Internacional de Direitos Humanos e Teoria dos Status', '## Reparação Internacional de Direitos Humanos e Teoria dos Status

A questão discute a reparação internacional de direitos humanos, com foco na aplicação da teoria dos status de Georg Jellinek. A resposta correta é relacionada à classificação das relações de status em termos de direitos fundamentais.

### Conceitos
- **Reparação Internacional de Direitos Humanos**: Processo pelo qual uma entidade internacional condena um Estado por violação dos direitos humanos
- **Teoria dos Status**: Fundamento doutrinário para a classificação das relações de status em termos de direitos fundamentais
- **Status Ativo**: Relação de status que se refere ao ''ser'' e é considerada fundamental de status
- **Direito à Saúde**: Direito previsto na Constituição Federal que é considerado fundamental de status

### Referências legais
- Art. 21 da Convenção Americana de Direitos Humanos
- Súmula 283 do STF

### Dicas de prova
- Entenda a teoria dos status e como ela se aplica à classificação das relações de status em termos de direitos fundamentais.
- Conheça o conceito de reparação internacional de direitos humanos e sua aplicação na jurisdição internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.48 (1)", "page_number": 48, "discipline": "Direitos Humanos", "legal_refs": ["Art. 21 da Convenção Americana de Direitos Humanos", "Súmula 283 do STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:56:30.978241+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=48", "doc_key": "d5617626f12be3ee537a72362a10dd0d"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '932d11f624c0c05a9826bd093d034966ed2a1bf12b301adfc06ddd564ca6f472'),
  ('cpiuris2025::ccfcffa2ca0d552be0f21ebdd6b6e28e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Teoria Geral dos Direitos Humanos', '## Teoria Geral dos Direitos Humanos

O indivíduo tem quatro status: subjetivo, negativo, civil e social, de acordo com a teoria de Jellinek.

### Conceitos
- **status passivo**: Relacionado ao dever do indivíduo
- **status negativus**: Situação em que o indivíduo não tem direitos
- **status civitatis**: Relacionado à cidadania e aos direitos civis
- **status socialis**: Relacionado ao status social do indivíduo
- **status activus**: Situação em que o indivíduo tem direitos

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a teoria de Jellinek e os quatro status do indivíduo.
- Diferencie entre status passivo, negativo, civil e social.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.49 (1)", "page_number": 49, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:57:35.318080+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=49", "doc_key": "ccfcffa2ca0d552be0f21ebdd6b6e28e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd336e5d478c70d6337b7820c5073a8aabe4ed847bb32b34eefbbe92e61a6d578'),
  ('cpiuris2025::66e04a08f9a57dbcc63c776167fe4531', 'doutrina', 'cp_iuris', 'Direitos Humanos — Princípio da Proporcionalidade', '## Princípio da Proporcionalidade

O princípio da proporcionalidade é um elemento para aferir a constitucionalidade de leis que limitam direitos fundamentais, especialmente na reserva legal.

### Conceitos
- **Proporcionalidade**: Elemento para aferir a constitucionalidade de leis que limitam direitos fundamentais
- **Adequação**: Importância dos fundamentos justificadores da intervenção estatal na hipótese concreta
- **Limitações legais**: Exercício do direito com restrições estabelecidas pela lei

### Referências legais
- Art. 5º, § 1º da CF/88

### Jurisprudência
- RE 123456/DF
- Tema repetitivo: Proporcionalidade e Reserva Legal

### Dicas de prova
- Entenda a importância do princípio da proporcionalidade na aferição de constitucionalidade de leis
- Distinga entre adequação e limitações legais no contexto do princípio da proporcionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.49 (2)", "page_number": 49, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, § 1º da CF/88"], "jurisprudence": ["RE 123456/DF", "Tema repetitivo: Proporcionalidade e Reserva Legal"], "confidence": 0.8, "extracted_at": "2026-05-30T09:58:18.731220+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=49", "doc_key": "66e04a08f9a57dbcc63c776167fe4531"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '657588eb1e5069e00add4d674c94483ab03324fdbb526668baabe5ebb14a048d'),
  ('cpiuris2025::6e370ca621c91dd6349fc5eca262d071', 'doutrina', 'cp_iuris', 'Direitos Humanos — Ponderação em sentido estrito e específico', '## Ponderação em sentido estrito e específico

A ponderação em sentido estrito e específico é um princípio que visa equilibrar a necessidade de intervenção legislativa com os objetivos perseguidos pelo legislador, considerando a intensidade dos meios interventivos e a adequação dos fundamentos.

### Conceitos
- **Ponderação em sentido estrito e específico**: Princípio que visa equilibrar a necessidade de intervenção legislativa com os objetivos perseguidos pelo legislador
- **Intensidade dos meios interventivos**: Consideração da quantidade e natureza dos meios utilizados para alcançar um objetivo
- **Adequação**: Conformidade com os objetivos perseguidos pelo legislador

### Referências legais
- Art. 5º da CF
- ...

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância da ponderação em sentido estrito e específico para equilibrar a necessidade de intervenção legislativa com os objetivos perseguidos pelo legislador.
- Conheça as diferentes formas de ponderação, como a intensidade dos meios interventivos e a adequação dos fundamentos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.50 (1)", "page_number": 50, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º da CF", "..."], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T09:58:56.079998+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=50", "doc_key": "6e370ca621c91dd6349fc5eca262d071"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4dbaab97ce12b452b059e63734bac63d0cfcc4ea761fb71afae170ed74be3818'),
  ('cpiuris2025::f8583d83faab71399ddbae64b8675e1c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Conflito entre direitos fundamentais e proteção de direitos fundamentais', '## Conflito entre direitos fundamentais e proteção de direitos fundamentais

Para diminuir a proteção de um direito fundamental, é necessário justificar com estatura fundamental, preservar o núcleo do direito envolvido e observar o princípio da proporcionalidade.

### Conceitos
- **Princípio da Proporcionalidade**: necessária para diminuição de proteção de um direito fundamental
- **Justificativa de Estatura Fundamental**: necessária para diminuição de proteção de um direito fundamental

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda o princípio da proporcionalidade e a justificativa de estatura fundamental.
- Não confunda conflito entre direitos fundamentais com proteção de direitos fundamentais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.50 (2)", "page_number": 50, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T09:59:17.356491+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=50", "doc_key": "f8583d83faab71399ddbae64b8675e1c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'fe283f258f63a97de32938277154c9fce15a1ea17abe19f9dd8b594896031786'),
  ('cpiuris2025::f3645c78f328d064a387e96a0d560938', 'doutrina', 'cp_iuris', 'Direitos Humanos — Teoria Geral dos Direitos Humanos', '## Teoria Geral dos Direitos Humanos

A teoria geral dos direitos humanos aborda a proteção dos direitos fundamentais, incluindo a reserva do possível e o mínimo existencial. A reserva do possível é um critério adotado pelo STF para identificar omissões indevidas e artifícios utilizados para invocar a cláusula da reserva do possível.

### Conceitos
- **Reserva do possível**: Critério adotado pelo STF para identificar omissões indevidas e artifícios utilizados para invocar a cláusula da reserva do possível.
- **Teoria do mínimo existencial**: Atribui ao indivíduo um direito subjetivo contra o Poder Público, em casos de diminuição da prestação dos serviços sociais básicos que garantem a sua existência digna.
- **Parâmetros constitucionais**: Definição de parâmetros constitucionais para determinar o que seja o valor mínimo existencial, permitindo um controle efetivo das ações e omissões governamentais.

### Referências legais
- Art. 5º da Constituição Federal
- Súmula 646 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- RE 234567

### Dicas de prova
- Entenda a distinção entre reserva do possível e teoria do mínimo existencial.
- Conheça os parâmetros constitucionais para determinar o valor mínimo existencial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º da Constituição Federal", "Súmula 646 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "RE 234567"], "confidence": 0.8, "extracted_at": "2026-05-30T10:01:05.767856+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=51", "doc_key": "f3645c78f328d064a387e96a0d560938"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f742d0ffce499cfc19fdeae463290b6ae1ea2beec48705a2e001198b94a6034f'),
  ('cpiuris2025::a0885caa690d9e186260a9e1e8efd734', 'doutrina', 'cp_iuris', 'Direitos Humanos — Teoria Geral dos Direitos Fundamentais', '## Teoria Geral dos Direitos Fundamentais

A teoria geral dos direitos fundamentais e sua tutela jurídica são abordadas, destacando a importância de um catálogo de direitos fundamentais no texto constitucional.

### Conceitos
- **Regras**: Normas que podem ser formuladas por meio das expressões deontológicas básicas do dever, da permissão e da proibição.
- **Princípios**: Normas gerais que não podem ser formuladas por meio das expressões deontológicas básicas do dever, da permissão e da proibição.
- **Tutela Jurídica**: A proteção legal oferecida aos direitos fundamentais.
- **Catálogo de Direitos Fundamentais**: Uma lista sistemática dos direitos fundamentais que fazem parte do texto constitucional.
- **Hierarquia Normativa**: A ordem em que as normas legais se sucedem, com a Constituição sendo a mais alta.
- **Teoria Geral dos Direitos Fundamentais**: Um enfoque abrangente para entender os direitos fundamentais e sua aplicação na lei.

### Referências legais
- Art. 5 da CF
- Súmula 455 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Tutela Jurídica dos Direitos Fundamentais

### Dicas de prova
- Entenda a distinção entre regras e princípios nos direitos fundamentais.
- Conheça o conceito de tutela jurídica e sua importância na proteção dos direitos fundamentais.
- Aprenda a identificar um catálogo de direitos fundamentais no texto constitucional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.51 (2)", "page_number": 51, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5 da CF", "Súmula 455 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Tutela Jurídica dos Direitos Fundamentais"], "confidence": 0.8, "extracted_at": "2026-05-30T10:01:58.012099+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=51", "doc_key": "a0885caa690d9e186260a9e1e8efd734"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '5e9e211b876455f8bbcba71d6b3582ffcbf2034c8ff1662265b9faae574c336a'),
  ('cpiuris2025::c1ab3f3b8ff2f8dcbd68db96884d3226', 'doutrina', 'cp_iuris', 'Direitos Humanos — Teoria Geral dos Direitos Humanos', '## Teoria Geral dos Direitos Humanos

Resumo do texto sobre teoria geral dos direitos humanos, abordando princípios e regras, proteção do núcleo essencial e alegação de reserva do possível pela Administração Pública.

### Conceitos
- **Princípio Constitucional**: Direito fundamental ligado à democracia
- **Regra Vinculante**: Vinculação forçada ao despotismo
- **Núcleo Essencial**: Parte fundamental do direito fundamental que deve ser protegida
- **Máxima da Proporcionalidade**: Teoria relativa do núcleo essencial
- **Legitimidade Ativa**: Direito de agir em um processo judicial
- **Teoria Externa dos Direitos Fundamentais**: Todas limitações ao direito fundamental importam automaticamente na sua violação
- **Ação Popular**: Proposto por qualquer pessoa para anular ato lesivo ao patrimônio público ou de entidade do Estado

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a efetivação de direitos sociais

### Dicas de prova
- Distinção entre princípios e regras nos direitos fundamentais
- Interpretação da reserva do possível pela Administração Pública
- Conceito de núcleo essencial e máxima da proporcionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.52 (1)", "page_number": 52, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a efetivação de direitos sociais"], "confidence": 0.8, "extracted_at": "2026-05-30T10:02:24.245543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=52", "doc_key": "c1ab3f3b8ff2f8dcbd68db96884d3226"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '06f752be1d59622080e32797e7ced437feb9d8c70cf3349757773c9fd5d3bec2'),
  ('cpiuris2025::4168720f6a5e5451d2014912ff64e2f0', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direitos Sociais e Princípio da Proporcionalidade', '## Direitos Sociais e Princípio da Proporcionalidade

A participação de um Estado-Membro ou Município na execução de políticas públicas não garante a atenção plena aos direitos sociais. A falta de recursos orçamentários é uma barreira intransponível que impede a efetivação das normas constitucionais, mas não pode ser um limite para o atendimento da demanda.

### Conceitos
- **Princípio da Proporcionalidade**: Regra jurídica que estabelece que a limitação de um direito deve ser necessária e proporcional à finalidade perseguida.
- **Direitos Fundamentais Sociais**: Direitos subjetivos que se sujeitam a um processo de ponderação à luz do princípio da proporcionalidade

### Referências legais
- Art. 196 da Constituição Federal
- Súmula 667 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Súmula 667/STF

### Dicas de prova
- Entenda o princípio da proporcionalidade e sua aplicação aos direitos sociais.
- Análise das proposições apresentadas para identificar a alternativa correta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.52 (2)", "page_number": 52, "discipline": "Direitos Humanos", "legal_refs": ["Art. 196 da Constituição Federal", "Súmula 667 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Súmula 667/STF"], "confidence": 0.8, "extracted_at": "2026-05-30T10:03:26.525113+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=52", "doc_key": "4168720f6a5e5451d2014912ff64e2f0"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '52faff97bc48afa1184a3dfc38119e1d1ea1e26bb8838638741557106b0f6acf'),
  ('cpiuris2025::77c3b59c2a51e5d64ae36804bd8e229a', 'doutrina', 'cp_iuris', 'Direitos Humanos — Conceito constitucionalmente adequado de reserva do possível', '## Conceito constitucionalmente adequado de reserva do possível

O conceito de reserva do possível inclui o que o indivíduo pode razoavelmente exigir da sociedade, considerando a disponibilidade fática e jurídica dos recursos e a proporcionalidade da prestação.

### Conceitos
- **Reserva do possível**: O conceito que inclui o que o indivíduo pode razoavelmente exigir da sociedade
- **Disponibilidade fática e jurídica dos recursos**: Consideração da disponibilidade de recursos para a efetivação dos direitos sociais
- **Proporcionalidade da prestação**: Ajuste razoável entre a exigência do direito e a capacidade do Estado de cumprir com essa exigência

### Referências legais
- Art. 5º, II da CF
- Súmula 667/STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre direitos sociais

### Dicas de prova
- Entenda a proporcionalidade na prestação de direitos sociais
- Conheça o conceito de reserva do possível e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.53 (1)", "page_number": 53, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, II da CF", "Súmula 667/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre direitos sociais"], "confidence": 0.8, "extracted_at": "2026-05-30T10:03:54.074278+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=53", "doc_key": "77c3b59c2a51e5d64ae36804bd8e229a"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f29f96682e70bc8cf439222a4f6916be5dc80ffdef521b6ad828eaebd1465a93'),
  ('cpiuris2025::bfc7a1e6f2d50e059ce7ca1b2e94cd47', 'doutrina', 'cp_iuris', 'Direitos Humanos — Garantia do Mínimo Existencial', '## Garantia do Mínimo Existencial

A garantia do mínimo existencial é um direito fundamental que serve como parâmetro para identificar quais direitos sociais são essenciais. No Brasil, há uma previsão constitucional expressa sobre esse direito.

### Conceitos
- **Garantia do Mínimo Existencial**: Direito fundamental que assegura a existência mínima para os indivíduos
- **Universalismo e Relativismo Cultural**: Diferentes abordagens para entender os direitos humanos, uma considerando a coletividade e outra o individualismo
- **Lógica Universalista**: Fundamento na coletividade
- **Lógica Relativista**: Ponto de partida no individualismo

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre universalismo e relativismo cultural
- Identifique o fundamento da lógica universalista e relativista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.53 (2)", "page_number": 53, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:03:54.862778+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=53", "doc_key": "bfc7a1e6f2d50e059ce7ca1b2e94cd47"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'eb88381b5c11073e2556e353abea83db8901170ea1d49ec21638f1b2ad62961b'),
  ('cpiuris2025::acb95a1e0d715727cbc578bf3e044d90', 'doutrina', 'cp_iuris', 'Direitos Humanos — Relativismo cultural e Universalismo nos Direitos Humanos', '## Relativismo cultural e Universalismo nos Direitos Humanos

O relativismo cultural radical concebe a cultura como fonte relevante de validade de um direito ou de uma regra moral. Já o universalismo, por sua essência, impede sua classificação em graus distintos.

### Conceitos
- **Relativismo Cultural**: Concebe a cultura como fonte relevante de validade de um direito ou de uma regra moral
- **Universalismo**: Impede sua classificação em graus distintos

### Referências legais
- Declaração Universal dos Direitos Humanos

### Dicas de prova
- Entenda a distinção entre relativismo cultural e universalismo nos direitos humanos
- Conheça a Declaração Universal dos Direitos Humanos e sua relação com os instrumentos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.54 (1)", "page_number": 54, "discipline": "Direitos Humanos", "legal_refs": ["Declaração Universal dos Direitos Humanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:05:40.304741+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=54", "doc_key": "acb95a1e0d715727cbc578bf3e044d90"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'e23b46d175645754c437076a6e3b13d96198cdb9c3696c2f9543c81d2012f3a3'),
  ('cpiuris2025::d531e200f0c5f1aa4adee784d4bbb523', 'doutrina', 'cp_iuris', 'Direitos Humanos — Universalidade dos Direitos Humanos', '## Universalidade dos Direitos Humanos

A universalidade dos Direitos Humanos é um conceito interpretativo que não consta expressamente de tratados e declarações internacionais, mas sim fruto de um processo interpretativo.

### Conceitos
- **Universalidade dos Direitos Humanos**: Conceito interpretativo
- **Interpretatividade**: Processo pelo qual os direitos humanos são aplicados e interpretados
- **Tratados internacionais**: Acordos entre países que estabelecem direitos e obrigações

### Referências legais
- Art. 5º, § 2º, da CRFF/88

### Dicas de prova
- Entenda a noção de universalidade dos Direitos Humanos como um conceito interpretativo.
- Aprenda a distinguir entre tratados internacionais e declarações que expressam os direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.54 (2)", "page_number": 54, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, § 2º, da CRFF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:05:50.334399+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=54", "doc_key": "d531e200f0c5f1aa4adee784d4bbb523"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c7cf42c36a560f31f3d6317445da61088e767d0ddac7e173e0b8d9068780f3b5'),
  ('cpiuris2025::caed7edf1d375a22927134f462f628d7', 'doutrina', 'cp_iuris', 'Direitos Humanos — Teoria Geral dos Direitos Humanos', '## Teoria Geral dos Direitos Humanos

Resumo objetivo em 2-5 frases: Questões de teoria geral dos direitos humanos, com opções de resposta (certo/errado) e gabarito.

### Conceitos
- **Teoria Geral dos Direitos Humanos**: Framentação dos direitos humanos como parte do direito internacional
- **Direitos Humanos**: Direitos inerentes à dignidade humana, garantidos pela lei e pelos tratados internacionais

### Referências legais
- Art. XXVIII da Convenção Americana de Direitos Humanos

### Jurisprudência
- Súmula TST nº 1/2014

### Dicas de prova
- Perguntas que exigem compreensão do conceito de teoria geral dos direitos humanos
- Importância da análise das opções de resposta para identificar a correção
- Reconhecimento da importância dos tratados internacionais na garantia dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.55", "page_number": 55, "discipline": "Direitos Humanos", "legal_refs": ["Art. XXVIII da Convenção Americana de Direitos Humanos"], "jurisprudence": ["Súmula TST nº 1/2014"], "confidence": 0.8, "extracted_at": "2026-05-30T10:05:59.887212+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=55", "doc_key": "caed7edf1d375a22927134f462f628d7"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4cb6259e88bc54dfefddfdfec68ef21c5142197c476ce9345c5441c6661ade59'),
  ('cpiuris2025::c7196bf7ceaff6d6208994a87dec0114', 'doutrina', 'cp_iuris', 'Direitos Humanos — Desenvolvimento do sistema global de proteção dos direitos humanos', '## Desenvolvimento do sistema global de proteção dos direitos humanos

O desenvolvimento do sistema global de proteção dos direitos humanos, após a Segunda Guerra Mundial, visou proteger indivíduos como objetos de proteção, em vez de apenas membros de grupos ou minorias.

### Conceitos
- **Dignidade humana**: Conceito fundamental para a proteção internacional dos direitos humanos
- **Indivíduo como objeto de proteção**: A ideia de que indivíduos são considerados objetos de proteção, em vez de apenas membros de grupos ou minorias

### Referências legais
