  ('cpiuris2025::b9762e9bed844a1d98b2ee180e5e28b4', 'doutrina', 'cp_iuris', 'Direitos Humanos — Internacionalização da Proteção dos Direitos Humanos', '## Internacionalização da Proteção dos Direitos Humanos

A proteção internacional dos direitos humanos teve seu início nos Estados-nações, alcançando a proteção constitucional com a implementação do Bill of Rights na Constituição Americana. No âmbito internacional, os precedentes da proteção internacional dos direitos humanos são datados de meados do Século XIX.

### Conceitos
- **Direito Humanitário**: direito aplicado na hipótese de guerra, gerando limites à liberdade dos Estados
- **Liga das Nações**: organização internacional que buscou reforçar a proteção do ser humano
- **Organização Internacional do Trabalho (OIT)**: instituto que visava proteger os direitos dos trabalhadores

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Dicas de prova
- Entenda a evolução do Direito Internacional e sua relação com os direitos humanos.
- Reconheça a importância dos institutos da Liga das Nações e da OIT na proteção dos direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:07:59.793223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=57", "doc_key": "b9762e9bed844a1d98b2ee180e5e28b4"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '7cbc154ddae5ef26ac3fb9a9af357e524fb003cf4a332498ab617a3553129ab7'),
  ('cpiuris2025::90605988e5d20ee34936dc592679f5eb', 'doutrina', 'cp_iuris', 'Direitos Humanos — Declaração Universal dos Direitos Humanos', '## Declaração Universal dos Direitos Humanos

A Declaração Universal dos Direitos Humanos foi elaborada pela Comissão de Direitos Humanos (CDH) do Conselho Econômico e Social (ECOSOC), com a finalidade de garantir os direitos humanos internacionais.

### Conceitos
- **Declaração Universal dos Direitos Humanos**: instrumento internacional que estabelece os direitos fundamentais das pessoas
- **Comissão de Direitos Humanos (CDH)**: órgão responsável pela elaboração e promoção dos direitos humanos internacionais
- **Conselho Econômico e Social (ECOSOC)**: órgão da ONU que promove a cooperação econômica e social entre os Estados

### Referências legais
- Art. X da Carta da ONU
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o papel do ECOSOC na promoção dos direitos humanos
- Conheça a importância da Declaração Universal dos Direitos Humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Carta da ONU", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T10:09:29.968239+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=58", "doc_key": "90605988e5d20ee34936dc592679f5eb"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a4fc0d4e01652e7ddf045b83c1b505e0e91e737ab5beee94be9b15b9ba8be6d7'),
  ('cpiuris2025::a76d1bfd12a841a2d014d63fc2d40021', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

Grupos de países se opuseram à ampliação do artigo 56 da Carta ONU, buscando limitar a interferência da ONU nos assuntos internos dos Estados. A autodeterminação dos povos foi declarada expressamente na Carta, mas apenas como um princípio para guiar a ONU.

### Conceitos
- **América Latina**: Grupos de países da região
- **Autodeterminação dos povos**: Direito do povo a decidir seu próprio destino
- **Carta ONU**: Convenção que estabelece as regras para a cooperação internacional
- **Cláusula de tutela da soberania Estatal**: Regra que limita a interferência da ONU nos assuntos internos dos Estados
- **Cooperação internacional**: Ação conjunta entre países para alcançar objetivos comuns
- **Interferência da ONU**: Ação da Organização das Nações Unidas em assuntos internos de um Estado
- **Princípio de igualdade de direitos**: Regra que estabelece a igualdade de tratamento para todos os países
- **Respeito à soberania Estatal**: Ação que reconhece o direito dos Estados de governar seus assuntos internos

### Referências legais
- Art. 56 da Carta ONU
- Art. 1º, parágrafo 2º da Carta ONU
- Art. 55 da Carta ONU
- Art. 2º, parágrafo 7 da Carta ONU

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância da cooperação internacional e do respeito à soberania Estatal
- Conheça os princípios de igualdade de direitos e autodeterminação dos povos
- Análise a cláusula de tutela da soberania Estatal e sua limitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Direitos Humanos", "legal_refs": ["Art. 56 da Carta ONU", "Art. 1º, parágrafo 2º da Carta ONU", "Art. 55 da Carta ONU", "Art. 2º, parágrafo 7 da Carta ONU"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T10:09:48.133211+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=58", "doc_key": "a76d1bfd12a841a2d014d63fc2d40021"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'e2d7ffbcad1d00f7fd3c3ad04eb1d05a41cdf0a8f20ee1c3282082bf84bb6ad3'),
  ('cpiuris2025::9a808fe50ee40b68aa111cc74faaab12', 'doutrina', 'cp_iuris', 'Direitos Humanos — Declaração Universal dos Direitos Humanos', '## Declaração Universal dos Direitos Humanos

A Declaração Universal dos Direitos Humanos foi adotada pela Assembleia Geral da ONU em 1948, após 81 encontros e 168 emendas. Ela teve a função de encontrar o mínimo denominador comum entre as formas de relação entre Estados e indivíduos.

### Conceitos
- **Declaração Universal dos Direitos Humanos**: documento da ONU que estabelece os direitos fundamentais dos seres humanos
- **Assembleia Geral da ONU**: órgão da ONU responsável por adotar resoluções e declarações internacionais
- **Vinculação aos Estados**: a questão de saber se a Declaração Universal dos Direitos Humanos é vinculante para os Estados
- **Costumes internacionais**: práticas e normas comuns entre os Estados que podem ser consideradas como fonte do direito internacional
- **Status de costume internacional**: o status de uma prática ou norma internacional que é aceita e respeitada pelos Estados

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a noção de vinculação aos Estados e como ela se relaciona com a Declaração Universal dos Direitos Humanos
- Conheça as diferentes correntes sobre o tema da vinculação da DUDH aos Estados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.59 (1)", "page_number": 59, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-30T10:10:49.645324+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=59", "doc_key": "9a808fe50ee40b68aa111cc74faaab12"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c5867d35a56f054f34e2ac8823e71be938038b1f25052b85d4c63afc195d4384'),
  ('cpiuris2025::cf16c1efbcf8e0f291e5bdaec0ef3318', 'doutrina', 'cp_iuris', 'Direitos Humanos — Instrumento pré-jurídico e normas da Declaração Universal dos Direitos Humanos (DUDH)', '## Instrumento pré-jurídico e normas da Declaração Universal dos Direitos Humanos (DUDH)

A DUDH é um instrumento pré-jurídico não dotado de força jurídica, mas tem caráter vinculante segundo a doutrina majoritária.

### Conceitos
- **Instrumento pré-jurídico**: Um documento ou acordo que antecede o desenvolvimento do direito e não é considerado juridicamente vinculante.
- **Normas da DUDH**: As normas contidas na Declaração Universal dos Direitos Humanos
- **Jus cogens**: Normas cogentes e inderrogáveis pelos Estados

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre a forma como a DUDH foi produzida e sua vinculação propriamente dita.
- Entender o conceito de instrumento pré-jurídico e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.59 (2)", "page_number": 59, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T10:11:30.532941+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=59", "doc_key": "cf16c1efbcf8e0f291e5bdaec0ef3318"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '9ed1e8b38e9c20868ebe17b12494aed0712ed32a3a5d55ed6406b282a9990273'),
  ('cpiuris2025::195755bfffad4a6c8897c31c34d15ed0', 'doutrina', 'cp_iuris', 'Direitos Humanos — Declaração Universal dos Direitos Humanos', '## Declaração Universal dos Direitos Humanos

A DUDH é uma declaração internacional que formula um conceito unitário e universalmente reconhecido de valores a serem defendidos por todos os Estados em seus ordenamentos internos. Ela consolida a ideia de uma ética universal, proclamando a indivisibilidade dos direitos humanos.

### Conceitos
- **Declaração Universal dos Direitos Humanos**: declaração internacional que formula um conceito unitário e universalmente reconhecido de valores
- **Carta Internacional de Direitos Humanos**: conjunto da DUDH e dos Pactos Internacionais sobre Direito Civil e Políticos e sobre Direitos Econômicos, Sociais e Culturais
- **indivisibilidade dos direitos humanos**: a ideia de que os direitos humanos são incompatíveis com a divisão em categorias

### Referências legais
- Art. 3 da DUDH

### Dicas de prova
- Entenda a importância da DUDH e sua relação com a Carta Internacional de Direitos Humanos
- Conheça as três partes da DUDH: fundamentos filosóficos, princípios gerais e direitos em espécie', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.60 (1)", "page_number": 60, "discipline": "Direitos Humanos", "legal_refs": ["Art. 3 da DUDH"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:12:05.791494+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=60", "doc_key": "195755bfffad4a6c8897c31c34d15ed0"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '373dd69141f6fb011b70e12469fb03506bd4383933ebe61369e95f54c56a6383'),
  ('cpiuris2025::58de5b89fb19dd64c005d4dcef6b67e1', 'doutrina', 'cp_iuris', 'Direitos Humanos — Cobrança de Direitos Humanos e Pactos de Direitos Humanos', '## Cobrança de Direitos Humanos e Pactos de Direitos Humanos

A cobrança de direitos humanos é necessária para garantir a implementação dos dispositivos. Os Pactos de Direitos Humanos foram elaborados com vinculação normativa aos Estados, mas com diferentes realidades entre os Estados, foi necessário cisão em quatro pontos.

### Conceitos
- **Direitos Sociais**: direitos que devem ser implementados progressivamente
- **Direitos Econômicos**: direitos que demandam esforços da população e de seus governantes para a implementação
- **Direitos Culturais**: direitos que exigem esforços da população e de seus governantes para a implementação
- **Reconhecimento Normativo**: procedimento pelo qual os direitos são reconhecidos em textos normativos
- **Implementação Progressiva**: adotção de medidas de implementação dos direitos sociais de forma progressiva
- **Monitoramento Diverso**: sistema de monitoramento diverso para os diferentes tipos de direitos

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre direitos sociais e econômicos culturais
- Conheça o sistema de monitoramento diverso para os diferentes tipos de direitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.60 (2)", "page_number": 60, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T10:13:15.467605+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=60", "doc_key": "58de5b89fb19dd64c005d4dcef6b67e1"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '39515fea8339bc88dc1464a35e82dd2b452fca132981030c2db4260e6631b8f4'),
  ('cpiuris2025::037ac462c95b09db58a91fd5a5f54a7b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Pacto Internacional sobre Direitos Civis e Políticos (PIDCP)', '## Pacto Internacional sobre Direitos Civis e Políticos (PIDCP)

O PIDCP é um tratado internacional que estabelece direitos civis e políticos para os indivíduos, com uma estrutura de seis partes. O tratado é dividido em duas categorias: liberdades negativas (direitos de primeira geração) e liberdades positivas (direitos de segunda geração).

### Conceitos
- **Direitos Civis e Políticos**: Direitos individuais que garantem a liberdade e a segurança dos cidadãos
- **Liberdades Negativas**: Direitos de primeira geração que protegem a liberdade individual, como a liberdade de expressão e a liberdade de reunião
- **Liberdades Positivas**: Direitos de segunda geração que garantem o bem-estar dos indivíduos, como o direito à educação e à saúde
- **Pacto Internacional sobre Direitos Civis e Políticos (PIDCP)**: Tratado internacional que estabelece direitos civis e políticos para os indivíduos

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre o Pacto Internacional sobre Direitos Civis e Políticos (PIDCP)

### Dicas de prova
- Entenda a distinção entre liberdades negativas e positivas
- Conheça as seis partes do PIDCP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.61 (1)", "page_number": 61, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre o Pacto Internacional sobre Direitos Civis e Políticos (PIDCP)"], "confidence": 0.8, "extracted_at": "2026-05-30T10:14:21.644283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=61", "doc_key": "037ac462c95b09db58a91fd5a5f54a7b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4dfd7ce9f67c56e219def7216d8e302102b5e33ebded3ed163d177421b7e7cdb'),
  ('cpiuris2025::e80a341194298019575037594158ea8e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direitos previstos no tratado e interpretação das cláusulas', '## Direitos previstos no tratado e interpretação das cláusulas

Resumo do artigo 3 a 6 do tratado, destacando a constituição do Comitê de Direitos Humanos e a interpretação das cláusulas.

### Conceitos
- **Direitos previstos no tratado**: Os direitos especificados no tratado internacional
- **Interpretação das cláusulas**: O processo de compreensão e aplicação das regras do tratado
- **Comitê de Direitos Humanos**: Entidade responsável por receber relatórios sobre medidas adotadas pelos Estados
- **Autodeterminação dos povos**: Direito dos povos a decidir seu próprio destino e desenvolvimento
- **Desenvolvimento**: O processo de crescimento e melhoria da condição humana

### Referências legais
- Art. 6 a 27 do Tratado Internacional
- Art. 3 do Pacto de Direitos Civis e Políticos

### Dicas de prova
- Entenda que os direitos previstos no tratado são específicos e devem ser interpretados com cuidado
- Conheça a importância da interpretação das cláusulas para evitar abusos de direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.61 (2)", "page_number": 61, "discipline": "Direitos Humanos", "legal_refs": ["Art. 6 a 27 do Tratado Internacional", "Art. 3 do Pacto de Direitos Civis e Políticos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:14:22.122159+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=61", "doc_key": "e80a341194298019575037594158ea8e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '5320155939afc4bf0d69edc233452d9e413e24c95a6dc94691d0e5ec4ff71385'),
  ('cpiuris2025::cbdbbaa4b90b75faa79167dbf9dfd89c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direitos Humanos Internacionais', '## Direitos Humanos Internacionais

Resumo do artigo 4 da DUDH, que detalha os direitos insuscetíveis de suspensão e prevê limites para a suspensão de outros direitos em caso de estado de emergência.

### Conceitos
- **DUDH**: Declaração Universal dos Direitos Humanos
- **PIDCP**: Pacto Internacional sobre Direitos Civis e Políticos
- **Direito à vida**: O direito de viver sem ameaça ou violência
- **Vedação à tortura**: Proibição de práticas cruéis, desumanas ou degradantes
- **Princípio da anterioridade penal**: O direito de ser julgado justo e imparcial

### Referências legais
- Art. 4 da DUDH

### Dicas de prova
- Entenda a diferença entre os direitos insuscetíveis de suspensão e aqueles que podem ser suspenso em caso de estado de emergência.
- Leia atentamente o artigo 4 da DUDH para identificar os limites impostos pela suspensão de direitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.62 (1)", "page_number": 62, "discipline": "Direitos Humanos", "legal_refs": ["Art. 4 da DUDH"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:15:30.612673+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=62", "doc_key": "cbdbbaa4b90b75faa79167dbf9dfd89c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '33f5923505ae5f38fd72a8aba7f1f11a0c74c4a26ad12e774fa27978a9f8a432'),
  ('cpiuris2025::e2a96856a2fc4e398b9abd8854c4069d', 'doutrina', 'cp_iuris', 'Direitos Humanos — Excepcionalidades e medidas de suspensão das obrigações do Pacto', '## Excepcionalidades e medidas de suspensão das obrigações do Pacto

Os Estados Partes podem adotar medidas para suspender as obrigações do Pacto em situações excepcionais que ameacem a existência da nação, desde que não sejam incompatíveis com outras obrigações internacionais e não discriminem certos grupos.

### Conceitos
- **situaciónes excepcionales**: ocorrências imprevistas que ameaçam a existência de um Estado
- **medidas de suspensión**: ações temporárias para reduzir as obrigações do Pacto
- **obrigações decorrentes**: deveres e responsabilidades derivadas do Pacto
- **Direito Internacional**: conjunto de regras e normas que regem relações entre Estados
- **discriminação**: tratamento desigual ou preferencial para certos grupos

### Referências legais
- Art. 15 do Pacto Internacional dos Direitos Civis e Políticos

### Dicas de prova
- Entenda a noção de ''situaciónes excepcionales'' e como elas podem justificar a suspensão das obrigações do Pacto.
- Reconheça a importância de garantir que as medidas adotadas não sejam incompatíveis com outras obrigações internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.62 (2)", "page_number": 62, "discipline": "Direitos Humanos", "legal_refs": ["Art. 15 do Pacto Internacional dos Direitos Civis e Políticos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:16:18.519038+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=62", "doc_key": "e2a96856a2fc4e398b9abd8854c4069d"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '130b588ead2f1e6ee8528108a3f4de5c2f732db5e0359c990e4ff532dc7e3f03'),
  ('cpiuris2025::24cadc6b772d00238d506ede825dd87c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direito à vida e Direitos Insusceptíveis de Suspensão no PIDCP', '## Direito à vida e Direitos Insusceptíveis de Suspensão no PIDCP

O artigo 6 do PIDCP proíbe a tortura, penas ou tratamento cruéis, desumanos ou degradantes. O artigo 7 proíbe a escravidão e a servidão, enquanto o artigo 8 proíbe a prisão civil por descumprimento contratual. Além disso, o PIDCP estabelece princípios da anterioridade penal (art. 11) e protege direitos de personalidade jurídica (art. 15), liberdades de pensamento, consciência e religião (art. 16) e vida (art. 6).

### Conceitos
- **Tortura**: pena ou tratamento cruéis, desumanos ou degradantes
- **Escravidão**: condição em que uma pessoa é obrigada a trabalhar sem remuneração e contra sua vontade
- **Princípio da anterioridade penal**: princípio que estabelece que as penas devem ser proporcionais às infrações cometidas
- **Direitos de personalidade jurídica**: direitos inerentes à pessoa humana, como a liberdade e a dignidade
- **Liberdades de pensamento, consciência e religião**: direitos que protegem a liberdade de expressar opiniões, crenças e práticas religiosas

### Referências legais
- Art. 6 PIDCP
- Art. 7 PIDCP
- Art. 8 PIDCP
- Art. 11 PIDCP
- Art. 15 PIDCP
- Art. 16 PIDCP

### Dicas de prova
- Entenda a distinção entre tortura e outros tratamentos cruéis, desumanos ou degradantes.
- Conheça os principais direitos insusceptíveis de suspensão no PIDCP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.63 (1)", "page_number": 63, "discipline": "Direitos Humanos", "legal_refs": ["Art. 6 PIDCP", "Art. 7 PIDCP", "Art. 8 PIDCP", "Art. 11 PIDCP", "Art. 15 PIDCP", "Art. 16 PIDCP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:16:37.546395+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=63", "doc_key": "24cadc6b772d00238d506ede825dd87c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ab2e6016f4d79f6335a682ad29514aaf2abdd397e98f28c8d2ebc9ad06cff5a0'),
  ('cpiuris2025::4c1e0afadc7e8a03d521bb817f01b8da', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reservas ao Protocolo', '## Reservas ao Protocolo

O artigo 2º estabelece regras para reservas feitas por Estados em relação ao Protocolo, relacionando-se à pena de morte e ao estado de guerra.

### Conceitos
- **Protocolo**: Acordo internacional que estabelece direitos humanos
- **Pena de Morte**: Execução capital como punição
- **Estado de Guerra**: Situação de conflito armado

### Referências legais
- Art. 5º, XLVII da Constituição de 1988

### Dicas de prova
- Entenda a diferença entre pena de morte e execução capital
- Conheça as regras para reservas ao Protocolo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.63 (2)", "page_number": 63, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, XLVII da Constituição de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:18:17.168972+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=63", "doc_key": "4c1e0afadc7e8a03d521bb817f01b8da"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '23a773d26e0cee340c8d6e7146dc6988e6f0482931805d1fb7fe9f6f5625e71e'),
  ('cpiuris2025::a61145e50bbd73a701269965a2a44044', 'doutrina', 'cp_iuris', 'Direitos Humanos — Pacto Internacional sobre Direitos Econômicos, Sociais e Culturais (PIDESC)', '## Pacto Internacional sobre Direitos Econômicos, Sociais e Culturais (PIDESC)

O PIDESC é um tratado internacional que estabelece direitos econômicos, sociais e culturais, com implementação progressiva. Os Estados devem garantir a realização desses direitos e provar que tomaram medidas necessárias para sua implementação.

### Conceitos
- **Implementação Progressiva**: Obrigatória implementação dos direitos econômicos, sociais e culturais com um período de tempo definido
- **Vedação do Retrocesso Social**: Proibição de retrocessos sociais, garantindo a melhoria das condições de vida dos cidadãos
- **Direitos Econômicos e Sociais Culturais**: Direitos fundamentais que devem ser garantidos aos Estados para implementá-los progressivamente

### Referências legais
- Art. 6 a 15 do PIDESC

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre direitos individuais e deveres dos Estados em relação ao Pacto sobre Direitos Econômicos, Sociais e Culturais
- Conheça os artigos do PIDESC que estabelecem esses direitos e suas implementações progressivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.64", "page_number": 64, "discipline": "Direitos Humanos", "legal_refs": ["Art. 6 a 15 do PIDESC"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T10:19:03.946363+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=64", "doc_key": "a61145e50bbd73a701269965a2a44044"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '1bf8a91f7ace3a761b777028cfbe6e330555b1e09e98968e696a41e0808e4d29'),
  ('cpiuris2025::b6769bc8181ca76280a42060f1cb3242', 'doutrina', 'cp_iuris', 'Direitos Humanos — Implementação do Pacto Internacional de Direitos Econômicos, Sociais e Culturais (PIDESC)', '## Implementação do Pacto Internacional de Direitos Econômicos, Sociais e Culturais (PIDESC)

O PIDESC estabelece direitos econômicos, sociais e culturais que os Estados devem implementar progressivamente. O mecanismo inicial de implementação é o relatório anual dos Estados sobre as medidas adotadas para cumprir os direitos previstos no Pacto.

### Conceitos
- **Pacto Internacional de Direitos Econômicos, Sociais e Culturais (PIDESC)**: Convenção internacional que estabelece direitos econômicos, sociais e culturais
- **Implementação progressiva**: Ação realizada pelos Estados para cumprir os direitos previstos no PIDESC
- **Relatório anual**: Documento apresentado pelos Estados aos órgãos da ONU sobre as medidas adotadas para cumprir os direitos previstos no PIDESC

### Referências legais
- Art. X da Convenção Internacional de Direitos Econômicos, Sociais e Culturais

### Jurisprudência
- Súmula N do STF
- ...

### Dicas de prova
- Entenda a diferença entre direitos civis e políticos e direitos sociais, econômicos e culturais
- Conheça o mecanismo de implementação inicial do PIDESC (relatório anual)
- Aprenda com os protocolos adicionais ao PIDESC, como o Protocolo Facultativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.65 (1)", "page_number": 65, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Convenção Internacional de Direitos Econômicos, Sociais e Culturais"], "jurisprudence": ["Súmula N do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T10:19:29.560014+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=65", "doc_key": "b6769bc8181ca76280a42060f1cb3242"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '9340a82a43936712dc6588ebabcf710565f365509b7baae263d79629ac04a137'),
  ('cpiuris2025::54329cfdc1aa7ea0fc9222081dd078e3', 'doutrina', 'cp_iuris', 'Direitos Humanos — Origem das Conferências Interamericanas', '## Origem das Conferências Interamericanas

A Primeira Conferência Internacional Americana, realizada em Washington de outubro de 1889 a 1890, marcou o início das Conferências Interamericanas. Desde então, os Estados americanos se reuniram em sessões com intervalos variáveis.

### Conceitos
- **Conferência Internacional Americana**: Reunião de representantes dos Estados americanos
- **Conferências Interamericanas**: Sessões regulares das Conferências Internacionais Americanas

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância das Conferências Interamericanas na história dos Direitos Humanos
- Identifique o ano e local da Primeira Conferência Internacional Americana', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.65 (2)", "page_number": 65, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:19:52.650384+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=65", "doc_key": "54329cfdc1aa7ea0fc9222081dd078e3"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4a75952ff502b578ca123b502be676db2295c94ca1fc5bac42a4e86ef2852f96'),
  ('cpiuris2025::03b4fe0df5a93c589a8f2be6c1ea56fb', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

Reconhecimento da importância da proteção internacional dos direitos humanos, incluindo a harmonização da legislação social e o estímulo à educação, ciência, tecnologia e cultura.

### Conceitos
- **Legislação Social**: Regras e normas que regem as relações entre os trabalhadores e os empregadores.
- **Previdência Social**: Sistema de proteção social que fornece benefícios a trabalhadores e idosos.
- **Educação**: Processo pelo qual o indivíduo adquire conhecimento, habilidades e valores.

### Referências legais
- Art. 46 da Carta das Nações Unidas
- Art. 47 da Carta das Nações Unidas

### Dicas de prova
- Entenda a importância da harmonização da legislação social e do estímulo à educação.
- Conheça as diretrizes da Carta das Nações Unidas sobre os direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.67 (1)", "page_number": 67, "discipline": "Direitos Humanos", "legal_refs": ["Art. 46 da Carta das Nações Unidas", "Art. 47 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:21:49.521370+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=67", "doc_key": "03b4fe0df5a93c589a8f2be6c1ea56fb"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '082af90ccfa9dd782a5b9803d0e1e680e6eb9da0c31a405db03f2ea79d50e809'),
  ('cpiuris2025::431a72123390a66665cf41e519fb2449', 'doutrina', 'cp_iuris', 'Direitos Humanos — Princípios Fundamentais dos Direitos Humanos', '## Princípios Fundamentais dos Direitos Humanos

Os princípios fundamentais incluem igualdade de oportunidades e segurança econômica, bem-estar material e desenvolvimento espiritual, direito ao trabalho e liberdade para se associar.

### Conceitos
- **Direitos Humanos**: direitos inalienáveis de cada indivíduo
- **Igualdade de Oportunidades**: condição necessária para a igualdade de tratamento
- **Segurança Econômica**: proteção contra a pobreza e a desigualdade econômica
- **Bem-estar Material**: nível de vida digno e confortável
- **Desenvolvimento Espiritual**: opportunidade para o crescimento pessoal e intelectual
- **Direito ao Trabalho**: direito fundamental à busca por emprego e trabalho
- **Liberdade de Associação**: direito a se associar livremente com outros para promover interesses

### Referências legais
- Art. 1 da Constituição Federal

### Jurisprudência
- Súmula 326 do STF

### Dicas de prova
- Entenda o conceito de igualdade de oportunidades e sua importância nos direitos humanos.
- Identifique os princípios fundamentais dos direitos humanos e seus elementos essenciais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.66 (2)", "page_number": 66, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1 da Constituição Federal"], "jurisprudence": ["Súmula 326 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T10:22:01.055952+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=66", "doc_key": "431a72123390a66665cf41e519fb2449"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd1273dde9305e3aff861bee228ef3d5afd0a03de164343c465e198b2b81afcda'),
  ('cpiuris2025::46147d55352b80afff9f86982a8fcd7c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Promoção e Proteção dos Direitos Humanos na OEA', '## Promoção e Proteção dos Direitos Humanos na OEA

A promoção e proteção dos direitos humanos na OEA são regulamentadas por vários protocolos e a Carta da OEA, que não consagra explicitamente esses objetivos, mas faz referências a eles em seus artigos. A promoção dos direitos humanos é feita através de tratados e protocolos específicos, como o Protocolo de Buenos Aires, Cartagena das Índias, Washington e Manágua.

### Conceitos
- **Promoção dos Direitos Humanos**: Ação realizada pela OEA para proteger e promover os direitos humanos
- **Carta da OEA**: Instrumento fundamental que estabelece a estrutura e os princípios da OEA
- **Protocolo de Buenos Aires**: Protocolo de 1967 que estabeleceu as bases para a promoção dos direitos humanos na OEA
- **Direitos Fundamentais da Pessoa Humana**: Princípios fundamentais que devem ser respeitados pelos Estados americanos

### Referências legais
- Art. 3, l) da Carta da OEA
- Art. 17 da Carta da OEA
- Protocolo de Buenos Aires (1967)
- Protocolo de Cartagena das Índias (1985)
- Protocolo de Washington (1992)
- Protocolo de Manágua (1993)

### Jurisprudência
- RE 123456
- Tema repetitivo: Promoção e Proteção dos Direitos Humanos na OEA

### Dicas de prova
- Entenda a importância da promoção e proteção dos direitos humanos na OEA
- Conheça os protocolos e a Carta da OEA que regulamentam esses objetivos
- Destaque as referências às direitas fundamentais da pessoa humana na Carta da OEA', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.66 (1)", "page_number": 66, "discipline": "Direitos Humanos", "legal_refs": ["Art. 3, l) da Carta da OEA", "Art. 17 da Carta da OEA", "Protocolo de Buenos Aires (1967)", "Protocolo de Cartagena das Índias (1985)", "Protocolo de Washington (1992)", "Protocolo de Manágua (1993)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Promoção e Proteção dos Direitos Humanos na OEA"], "confidence": 0.8, "extracted_at": "2026-05-30T10:22:38.188481+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=66", "doc_key": "46147d55352b80afff9f86982a8fcd7c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c9279f2910df2d5aee7531808d7ab1977f3ff0e273cf553531a74900ee4e850e'),
  ('cpiuris2025::30e9114ac6b3309a5a088253fd706039', 'doutrina', 'cp_iuris', 'Direitos Humanos — Educação e Desenvolvimento', '## Educação e Desenvolvimento

Os Estados membros devem promover a educação, pesquisa científica e tecnológico para desenvolvimento integral, garantindo o direito à educação e acessibilidade à educação de grau superior.

### Conceitos
- **Direito à Educação**: O direito fundamental à educação
- **Educação Obligatoria**: O ensino obrigatório para todos os menores de idade escolar
- **Educação Gratuita**: O ensino ministrado pelo Estado é gratuito
- **Desenvolvimento Integral**: O desenvolvimento humano completo e equilibrado

### Referências legais
- Art. 49 da Convenção-Protocolo

### Dicas de prova
- Entenda a importância do direito à educação e como ele deve ser garantido aos Estados membros.
- Identifique os princípios que devem guiar a política educacional dos Estados membros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.67 (2)", "page_number": 67, "discipline": "Direitos Humanos", "legal_refs": ["Art. 49 da Convenção-Protocolo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:23:45.438835+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=67", "doc_key": "30e9114ac6b3309a5a088253fd706039"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a7c528188982ddeeb41c4992a75c62f74c74f8ffb1cd2a32c094ad64961f6956'),
  ('cpiuris2025::1cc17151c3399430a98264a70c910420', 'doutrina', 'cp_iuris', 'Direitos Humanos — Intercâmbio Cultural e Direitos Humanos', '## Intercâmbio Cultural e Direitos Humanos

O intercâmbio cultural é visto como um meio eficaz para consolidar a compreensão interamericana e reconhecer os programas de integração regional devem ser fortalecidos, especialmente nos setores da educação, ciência e cultura.

### Conceitos
- **Intercâmbio Cultural**: cooperação entre Estados para promover a compreensão interamericana
- **Programas de Integração Regional**: iniciativas que visam fortalecer a cooperação e o desenvolvimento regional
- **Educação**: área da ciência e cultura que visa promover o desenvolvimento integral

### Referências legais
- Art. 52 da Carta das Américas
- Protocolo de Buenos Aires (1970)

### Jurisprudência
- Cristina Figueiredo Terezo, Declaração sobre os Direitos Humanos na América do Sul

### Dicas de prova
- Entenda a importância do intercâmbio cultural para a promoção dos Direitos Humanos
- Conheça os programas de integração regional e sua relevância para o desenvolvimento regional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Direitos Humanos", "legal_refs": ["Art. 52 da Carta das Américas", "Protocolo de Buenos Aires (1970)"], "jurisprudence": ["Cristina Figueiredo Terezo, Declaração sobre os Direitos Humanos na América do Sul"], "confidence": 0.8, "extracted_at": "2026-05-30T10:24:24.712091+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=68", "doc_key": "1cc17151c3399430a98264a70c910420"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '1daf6bcda7fae454969334cb26fc027d4c8dcf5ff6bdc9fad4e81bcedd247f40'),
  ('cpiuris2025::ae3192ec7bfd85a1de5a214e2e598609', 'doutrina', 'cp_iuris', 'Direitos Humanos — Declaração Americana de Direitos e Deveres do Homem', '## Declaração Americana de Direitos e Deveres do Homem

A Declaração Americana foi redigida após a Conferência Internacional dos Estados Americanos em Lima (1938) e concluída em Bogotá (1948), com a adesão de 21 Estados, resultando na Carta da Organização dos Estados Americanos, Tratado Americano sobre Soluções Pacíficas e Declaração Americana dos Direitos e Deveres do Homem.

### Conceitos
- **Declaração Americana**: Carta que define os direitos e deveres dos indivíduos em âmbito americano
- **Conferência Internacional dos Estados Americanos**: Reunião de países americanos para discutir questões políticas e sociais
- **Pacto de Bogotá**: Tratado que estabelece a Organização dos Estados Americanos e suas missões
- **Carta da Organização dos Estados Americanos**: Documento que define as bases da organização e seus objetivos

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Dicas de prova
- Entenda a importância da Declaração Americana como base para os direitos humanos na América do Sul
- Conheça as diferentes conferências internacionais que contribuíram para sua redação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.68 (2)", "page_number": 68, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:25:04.506537+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=68", "doc_key": "ae3192ec7bfd85a1de5a214e2e598609"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '54058eae7a874ac7121951820f105b3fa680333c20cb6dea40402430d4a01939'),
  ('cpiuris2025::187c1c714cf83c57d18a363fd5443171', 'doutrina', 'cp_iuris', 'Direitos Humanos — Definição de Direitos Humanos', '## Definição de Direitos Humanos

O texto define os direitos humanos como inerentes à pessoa humana e abrangem direitos civis, políticos, econômicos, sociais e culturais.

### Conceitos
- **Direitos Humanos**: instituição criada para promover a observância e a defesa dos direitos humanos
- **Convenção Americana sobre Direitos Humanos**: instrumento internacional que define os direitos humanos
- **Declaração Americana de Direitos e Deveres do Homem**: declaração que consagra os direitos humanos

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre direitos civis e políticos, econômicos, sociais e culturais.
- Conheça as fontes de direitos humanos, como a Convenção Americana e a Declaração Americana.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.69 (2)", "page_number": 69, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:26:11.423587+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=69", "doc_key": "187c1c714cf83c57d18a363fd5443171"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '515c136c6458645f00798aeb441dcf4893176823b4c8be9b6986a30b33e1342c'),
  ('cpiuris2025::14522a06a1b22c2f2c2adfe43000c63f', 'doutrina', 'cp_iuris', 'Direitos Humanos — Declaração Americana de Direitos e Deveres do Homem (DADDH) e sua vinculação aos direitos humanos', '## Declaração Americana de Direitos e Deveres do Homem (DADDH) e sua vinculação aos direitos humanos

A Declaração Americana de Direitos e Deveres do Homem foi assinada pela OEA antes da DUDH, mas não é um tratado stricto sensu. A Corte Interamericana de Direitos Humanos entendeu que ela é fonte de obrigações aos Estados-membros da OEA.

### Conceitos
- **Declaração Americana de Direitos e Deveres do Homem (DADDH)**: documento assinado pela OEA antes da DUDH
- **Vinculação dos direitos humanos**: Questão sobre se a DADDH é fonte de obrigações vinculantes para os Estados-membros da OEA
- **Corte Interamericana de Direitos Humanos**: Entidade responsável por interpretar e aplicar os direitos humanos na região americana
- **Artigo 29 da CADH**: Disposição que prevê a Declaração como fonte de interpretação dos direitos
- **OEA**: Organização dos Estados Americanos, organização regional que promove os direitos humanos

### Referências legais
- Art. 29 da CADH
- Corte IDH, Opinião Consultiva nº 10

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a vinculação dos direitos humanos

### Dicas de prova
- Entenda a diferença entre tratado e resolução em relação à Declaração Americana
- Conheça o papel da Corte Interamericana de Direitos Humanos na interpretação dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.69 (1)", "page_number": 69, "discipline": "Direitos Humanos", "legal_refs": ["Art. 29 da CADH", "Corte IDH, Opinião Consultiva nº 10"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a vinculação dos direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T10:26:57.214415+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=69", "doc_key": "14522a06a1b22c2f2c2adfe43000c63f"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '7e0d0bdd0eda64b19633329308c3925a955f84852966ef9b14ffd5e82e61a6b6'),
  ('cpiuris2025::4b3ab048967385ed41b3304070242c78', 'doutrina', 'cp_iuris', 'Direitos Humanos — Convenção Americana de Direitos Humanos', '## Convenção Americana de Direitos Humanos

A Convenção Americana sobre Direitos Humanos foi celebrada em 1969 e internalizada pelo Brasil em 1992. É baseada nos Pactos de Direitos Humanos de 1966 e na Convenção Europeia dos Direitos do Homem de 1950.

### Conceitos
- **Convenção Americana**: Tratado internacional sobre direitos humanos
- **DUDH**: Declaração Universal dos Direitos Humanos
- **DADDH**: Declaração Americana dos Direitos e Dos Deveres Humanos
- **Carta da OEA**: Carta das Organizações Americanas
- **Protocolo de Buenos Aires**: Protocolo que reformou a Carta da OEA
- **Protocolo de San Salvador**: Protocolo sobre Direitos Sociais, Econômicos e Culturais

### Referências legais
- Artigo 26 da Convenção Americana

### Dicas de prova
- Entenda a relação entre a CADH e os Pactos de Direitos Humanos
- Conheça o Protocolo de San Salvador sobre Direitos Sociais, Econômicos e Culturais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.70 (1)", "page_number": 70, "discipline": "Direitos Humanos", "legal_refs": ["Artigo 26 da Convenção Americana"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:27:24.561491+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=70", "doc_key": "4b3ab048967385ed41b3304070242c78"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c47664fcb5c6a6980ff9c63f3fc8fe7323b6220e54b55b60f6d98fea4867ae12'),
  ('cpiuris2025::c83ac3bbaa97184a24eb6b81707ba641', 'doutrina', 'cp_iuris', 'Direitos Humanos — Suspensão de garantias em caso de emergência', '## Suspensão de garantias em caso de emergência

A Convenção das Nações Unidas sobre os Direitos Civis e Políticos (CADH) permite a suspensão de direitos humanos em caso de guerra, perigo público ou emergência que ameace a independência ou segurança do Estado Parte.

### Conceitos
- **Suspensão de garantias**: A possibilidade de adotar disposições que suspendam direitos humanos em caso de emergência.
- **Emergência**: Situação que ameace a independência ou segurança do Estado Parte.
- **Direito Internacional**: O conjunto das regras e normas que regem as relações entre os Estados.
- **Princípio da legalidade**: A ideia de que as ações dos governos devem ser baseadas em leis e não em decisões arbitrárias.
- **Discriminação**: Tratamento desigual ou preferencial com base em características como raça, cor, sexo, idioma, religião ou origem social.

### Referências legais
- Art. 27 da CADH

### Dicas de prova
- Entenda a distinção entre suspensão de garantias e discriminação.
- Conheça as exceções mencionadas no artigo 27, nº 2.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.70 (2)", "page_number": 70, "discipline": "Direitos Humanos", "legal_refs": ["Art. 27 da CADH"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:28:35.869707+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=70", "doc_key": "c83ac3bbaa97184a24eb6b81707ba641"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '66b008281947d1dfb98c6f4fe750e37666798af1465bb74651c195f2df099d8d'),
  ('cpiuris2025::7013276ea335dbdbb46a86520cb8f433', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reconhecimento de Direitos Humanos', '## Reconhecimento de Direitos Humanos

O texto destaca a importância do reconhecimento dos direitos humanos, destacando as alterações feitas na Convenção Europeia de Direitos do Homem após a reforma de 1998.

### Conceitos
- **Reconhecimento de Direitos Humanos**: O direito de uma pessoa ser reconhecida perante a lei
- **Direito à Nacionalidade**: O direito de um cidadão de manter sua nacionalidade
- **Pena de Morte**: A proibição da pena de morte em determinados países

### Referências legais
- Art. 76 e 77 do Código Civil
- ...

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Direitos Humanos ...

### Dicas de prova
- Entenda a importância do reconhecimento dos direitos humanos
- Destaque as alterações feitas na Convenção Europeia de Direitos do Homem após a reforma de 1998', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.71 (2)", "page_number": 71, "discipline": "Direitos Humanos", "legal_refs": ["Art. 76 e 77 do Código Civil", "..."], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Direitos Humanos ..."], "confidence": 0.8, "extracted_at": "2026-05-30T10:28:56.707741+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=71", "doc_key": "7013276ea335dbdbb46a86520cb8f433"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4316cbc0da01559023319e99841056788eedfda37d2f407805deaa87d370fb1b'),
  ('cpiuris2025::78a36b8ccd171a20bc041d1ae0dcb5f2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos e Correlação entre Deveres e Direitos', '## Proteção Internacional dos Direitos Humanos e Correlação entre Deveres e Direitos

O tratado discute a proteção internacional dos direitos humanos, incluindo a suspensão de sua aplicação em determinadas circunstâncias. Além disso, destaca-se a correlação entre deveres e direitos, bem como a cláusula de abertura para a interpretação dos direitos previstos.

### Conceitos
- **Retroatividade**: A aplicação imediata de uma lei ou tratado posterior a sua promulgação
- **Liberdade de consciência e religião**: O direito de cada indivíduo de exercer sua fé sem interferência do Estado
- **Proteção da família**: A proteção dos direitos e interesses da família, incluindo a proteção contra a violência doméstica
- **Direito ao nome**: O direito de cada indivíduo de manter seu nome e identidade pessoal
- **Deveres das pessoas com a família, comunidade e humanidade**: Os deveres que cada pessoa tem em relação à sua família, comunidade e à humanidade
- **Correlação entre deveres e direitos**: A ideia de que os direitos de um indivíduo estão limitados pelos direitos dos demais e pelas justas exigências do bem comum

### Referências legais
- Artigo 32 da CADH
- Artigo 29 da CADH

### Dicas de prova
- Entenda a noção de retroatividade e sua aplicação nos tratados internacionais
- Identifique os direitos humanos protegidos pela Convenção Americana dos Direitos Humanos
- Aprenda a correlação entre deveres e direitos em um contexto internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.71 (1)", "page_number": 71, "discipline": "Direitos Humanos", "legal_refs": ["Artigo 32 da CADH", "Artigo 29 da CADH"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:29:17.279705+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=71", "doc_key": "78a36b8ccd171a20bc041d1ae0dcb5f2"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '2588dfd83272ae7e04c5ec85bb44da4f5c29e4f9135a734a74251a908c2502ad'),
  ('cpiuris2025::8b73f17917ff867a4cbdf65c3a9c7a51', 'doutrina', 'cp_iuris', 'Direitos Humanos — Princípio de não detenção por dívidas', '## Princípio de não detenção por dívidas

O princípio de não detenção por dívidas é um direito humano fundamental, salvo em casos específicos como inadimplemento de obrigação alimentar ou responsabilidade pelo depositário infiel.

### Conceitos
- **Princípio de não detenção por dívidas**: Direito humano que proíbe a detenção de uma pessoa por dívidas
- **Obrigação alimentar**: Obrigação que visa garantir o sustento de uma pessoa necessitada
- **Depositário infiel**: Pessoa responsável pela manutenção de bens ou valores de outra pessoa

### Referências legais
- Art. 5º, LXVII da Constituição

### Dicas de prova
- Entenda a distinção entre prisão civil por dívida e responsabilidade pelo depositário infiel
- Conheça o conceito de obrigação alimentar e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.72 (2)", "page_number": 72, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, LXVII da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:31:13.774541+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=72", "doc_key": "8b73f17917ff867a4cbdf65c3a9c7a51"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ba8a87bb69ddff2441fe9c623ba2f6964ef62e16b9bf98718f31335a27e26f96'),
  ('cpiuris2025::8a5b1d45c6d9c7481090d6564397fa32', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Convenção Americana sobre os Direitos Humanos (CADH) adota a teoria concepcionista, protegendo o direito à vida desde a concepção. No entanto, a Corte Interamericana de Direitos Humanos interpreta que a ''concepção'' ocorre apenas no segundo estágio do desenvolvimento embrionário.

### Conceitos
- **Teoria Concepcionista**: Protege o direito à vida desde a concepção
- **Teoria Natalista**: Não protege o direito à vida desde a concepção
- **Código Civil Brasileiro**: Aponta que o início da personalidade começa com o nascimento com vida
- **Artigo 2º do Código Civil Brasileiro**: Salva os direitos do nascituro desde a concepção

### Referências legais
- Art. 2º do Código Civil Brasileiro
- ADI 3.510/STF

### Jurisprudência
- Caso Artavia Murillo e outros vs. Costa Rica (Corte Interamericana de Direitos Humanos, 2012)

### Dicas de prova
- Interpretação das assertivas para fins de concurso
- Distinção entre a teoria concepcionista e a teoria natalista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.72 (1)", "page_number": 72, "discipline": "Direitos Humanos", "legal_refs": ["Art. 2º do Código Civil Brasileiro", "ADI 3.510/STF"], "jurisprudence": ["Caso Artavia Murillo e outros vs. Costa Rica (Corte Interamericana de Direitos Humanos, 2012)"], "confidence": 0.8, "extracted_at": "2026-05-30T10:31:49.168664+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=72", "doc_key": "8a5b1d45c6d9c7481090d6564397fa32"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '05a74a662deca5a750af1c38c34814847a91a738b066fde440b18053c949bf65'),
  ('cpiuris2025::c54dd3d57f93295e1d52eeba6e5d118d', 'doutrina', 'cp_iuris', 'Direitos Humanos — Audiência de Custódia e sua compatibilidade com a CADH', '## Audiência de Custódia e sua compatibilidade com a CADH

O artigo 7, item 5, da CADH estabelece que uma pessoa detida ou retada deve ser conduzida à presença de um juiz, com direito a ser julgada dentro de um prazo razoável ou posta em liberdade.

### Conceitos
- **Audiência de Custódia**: Condução da pessoa detida ou retada à presença de um juiz
- **CADH**: Código de Direitos do Adolescente
- **Direito à Liberdade Pessoal**: O direito de uma pessoa ser conduzida à presença de um juiz sem demora

### Referências legais
- Art. 5º, §3º da Constituição
- Art. 7, item 5, da CADH
- Código Eleitoral, Art. 236
- Estatuto da Criança e do Adolescente

### Jurisprudência
- RE 349.703
- Súmula Vinculante nº 25

### Dicas de prova
- Entenda a teoria monista nacionalista moderada sobre os tratados internacionais de direitos humanos
- Destaque a importância da audiência de custódia e sua compatibilidade com a CADH', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.73 (1)", "page_number": 73, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, §3º da Constituição", "Art. 7, item 5, da CADH", "Código Eleitoral, Art. 236", "Estatuto da Criança e do Adolescente"], "jurisprudence": ["RE 349.703", "Súmula Vinculante nº 25"], "confidence": 0.8, "extracted_at": "2026-05-30T10:32:03.409156+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=73", "doc_key": "c54dd3d57f93295e1d52eeba6e5d118d"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '9cd216ad42279c023624879ea4c72402571381bbf8a243c3811a70ddd674701f'),
  ('cpiuris2025::5e6ac11ca64c7cf58b67f3350f7ea2b5', 'doutrina', 'cp_iuris', 'Direitos Humanos — Requisito de apresentação do preso em flagrante às autoridades judiciárias', '## Requisito de apresentação do preso em flagrante às autoridades judiciárias

O adolescente apreendido deve ser encaminhado à autoridade judiciária, enquanto o preso em flagrante deve ser apresentado à autoridade judicial competente no prazo de 24 horas.

### Conceitos
- **Prisão em Flagrante**: Ato de prisão realizada em flagrante delito, sem necessidade de ordem judicial prévia
- **Autoridade Judiciária**: Entidade responsável pela aplicação da lei e pela proteção dos direitos individuais
- **Autoridade Policial**: Entidade responsável pela execução das leis e pela manutenção da ordem pública

### Referências legais
- Art. 171 do Código de Processo Penal
- Art. 172 do Código de Processo Penal
- Provimento Conjunto 03/2015
- Resolução nº 213/15 do Conselho Nacional de Justiça

### Jurisprudência
- RE 5240
- ADPF/MC 347

### Dicas de prova
- Distinção entre prisão em flagrante e encaminhamento à autoridade judiciária
- Importância do prazo de apresentação ao juiz competente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.73 (2)", "page_number": 73, "discipline": "Direitos Humanos", "legal_refs": ["Art. 171 do Código de Processo Penal", "Art. 172 do Código de Processo Penal", "Provimento Conjunto 03/2015", "Resolução nº 213/15 do Conselho Nacional de Justiça"], "jurisprudence": ["RE 5240", "ADPF/MC 347"], "confidence": 0.8, "extracted_at": "2026-05-30T10:33:42.380003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=73", "doc_key": "5e6ac11ca64c7cf58b67f3350f7ea2b5"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '2831fcd787d674ed7f4e587d7fec9dd56a95e2af994aa2a574d3505de041c576'),
  ('cpiuris2025::3893aaded88895e38b2d937ea1483cbf', 'doutrina', 'cp_iuris', 'Direitos Humanos — Audiência de Custódia e Direitos do Homem', '## Audiência de Custódia e Direitos do Homem

O texto discute a audiência de custódia, um direito humano fundamental, e sua implementação no Código de Processo Penal. Alega-se que a associação dos Delegados de Polícia tem legitimidade para propor ação direta de inconstitucionalidade para exigir a realização da audiência de custódia.

### Conceitos
- **Audiência de Custódia**: procedimento judicial que visa garantir o direito do preso à liberdade em determinado período
- **Direitos Humanos Fundamentais**: direitos inalienáveis e universais, como a liberdade e a segurança pessoal
- **Legislação Federal Estrita**: interpretação rigorosa da legislação federal para garantir os direitos humanos

### Referências legais
- Art. 5º, inciso II, da Constituição Federal
- Art. 22, inciso I, da Constituição Federal
- Art. 103, inciso IX, da CRFB
- Lei nº 13.964/2019

### Jurisprudência
- ADI 5240
- ADPF 347 MC

### Dicas de prova
- Entenda a importância da audiência de custódia no contexto dos direitos humanos.
- Conheça a legislação federal estrita e sua aplicação na prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.74 (2)", "page_number": 74, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, inciso II, da Constituição Federal", "Art. 22, inciso I, da Constituição Federal", "Art. 103, inciso IX, da CRFB", "Lei nº 13.964/2019"], "jurisprudence": ["ADI 5240", "ADPF 347 MC"], "confidence": 0.8, "extracted_at": "2026-05-30T10:34:38.878194+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=74", "doc_key": "3893aaded88895e38b2d937ea1483cbf"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '483d6f558c559441d9ebc2e77dc4e6056bb6f279709fe8a7bfbf3d67361c1a0b'),
  ('cpiuris2025::5dde4ac702f80c5b95628fdbfdefdb1c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Audiência de Custódia e Habeas Corpus', '## Audiência de Custódia e Habeas Corpus

Audiência de custódia é um procedimento legal que envolve a apresentação do preso ao juiz para aferir a legalidade da prisão. O habeas corpus é o direito de apresentação do preso ao juiz, que pode ser impugnado por meio de ação direta de inconstitucionalidade.

### Conceitos
- **Audiência de Custódia**: Procedimento legal que envolve a apresentação do preso ao juiz
- **Habeas Corpus**: Direito de apresentação do preso ao juiz para aferir a legalidade da prisão
- **Ação Direta de Inconstitucionalidade**: Mecanismo jurídico utilizado para impugnar a constitucionalidade de uma lei ou ato administrativo
- **Procedimento Legal**: Série de atos e procedimentos realizados em um processo judicial
- **Reserva de Lei ou Norma Constitucional**: Direito do Estado de manter a autonomia para regulamentar determinadas áreas

### Referências legais
- Art. 7º, item 5 da Convenção Americana sobre Direitos do Homem
- Art. 656 do Código de Processo Penal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre audiência de custódia e habeas corpus
- Conheça o procedimento legal para a apresentação do preso ao juiz
- Avalie a importância da reserva de lei ou norma constitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.74 (1)", "page_number": 74, "discipline": "Direitos Humanos", "legal_refs": ["Art. 7º, item 5 da Convenção Americana sobre Direitos do Homem", "Art. 656 do Código de Processo Penal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T10:34:50.121134+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=74", "doc_key": "5dde4ac702f80c5b95628fdbfdefdb1c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '6451ba2c2ad5b7e8831e914765d5eec7c41ee1298f39b8b4e7e925d6284c9449'),
  ('cpiuris2025::3ba978210950868aa29b9bb7b118177a', 'doutrina', 'cp_iuris', 'Direitos Humanos — Garantia do duplo grau de jurisdição', '## Garantia do duplo grau de jurisdição

A garantia do duplo grau de jurisdição é um direito fundamental que permite a revisão da decisão condenatória com cognição ampla, garantindo a igualdade e a eficácia dos recursos. A Corte IDH considerou que os recursos devem ser ordinários, acessíveis, eficazes e permitir a revisão integral da decisão recorrida.

### Conceitos
- **Duplo grau de jurisdição**: Garantia que permite a revisão da decisão condenatória com cognição ampla
- **Garantias judiciais**: Direitos mínimos garantidos ao acusado durante o processo
- **Recorrer da sentença**: Direito de recorrer a uma decisão condenatória para um tribunal superior

### Referências legais
- Art. 8.2, h, da CADH
- Lei nº 13.964/2019

### Jurisprudência
- Caso Norín Catrimán e outros vs. Chile
- Caso Cabrera García e Montiel Flores vs. México
- Caso Irmãos Landaeta Mejías e outros vs. Venezuela
- Amrheim e outros vs. Costa Rica

### Dicas de prova
- Entenda a garantia do duplo grau de jurisdição e suas implicações no processo penal
- Análise das garantias judiciais mínimas garantidas ao acusado
- Revisão da decisão condenatória com cognição ampla', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Direitos Humanos", "legal_refs": ["Art. 8.2, h, da CADH", "Lei nº 13.964/2019"], "jurisprudence": ["Caso Norín Catrimán e outros vs. Chile", "Caso Cabrera García e Montiel Flores vs. México", "Caso Irmãos Landaeta Mejías e outros vs. Venezuela", "Amrheim e outros vs. Costa Rica"], "confidence": 0.8, "extracted_at": "2026-05-30T10:36:35.170375+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=75", "doc_key": "3ba978210950868aa29b9bb7b118177a"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4ba15cd2b1bbd7a7731f82f1c8fec91c4d85f65e394fbfe5dd73f4af59ad36b8'),
  ('cpiuris2025::e632dabd78d7c898f1e6eb39279c7142', 'doutrina', 'cp_iuris', 'Direitos Humanos — Recurso em Sentença', '## Recurso em Sentença

O recurso deve ser ordinário, acessível e eficaz, permitindo um exame integral da sentença recorrida e respeitando as garantias processuais mínimas.

### Conceitos
- **Recurso Ordinário**: Garantia de direito de interpor recurso contra a sentença antes que ela adquira qualidade de coisa julgada.
- **Recurso Acessível**: Presentação não deve requerer maiores complexidades que tornem ilusório este direito.
- **Recurso Eficaz**: Deve permitir resultados ou respostas, conforme a finalidade para a qual foi concebido.
- **Análise Integral da Sentença**: Deve garantir a possibilidade de um exame integral da decisão recorrida.

### Referências legais
- Art. 5º, LIV, da CF/88

### Jurisprudência
- Súmula 656/2012 (STJ)

### Dicas de prova
- Distinção entre recurso ordinário e acessível
- Importância do recurso eficaz para a correção de condenações equivocadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, LIV, da CF/88"], "jurisprudence": ["Súmula 656/2012 (STJ)"], "confidence": 0.8, "extracted_at": "2026-05-30T10:36:52.828131+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=75", "doc_key": "e632dabd78d7c898f1e6eb39279c7142"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '2ac31b12f37c113552eaea9832ee63a9a58e1f944fcc8e6a7afec18534e00969'),
  ('cpiuris2025::d2075840b682da472af88f9a33cce9a9', 'doutrina', 'cp_iuris', 'Direitos Humanos — Recurso ao alcance e garantia processual', '## Recurso ao alcance e garantia processual

O direito a recorrer da sentença não pode ser efetivo se não garantir a todo aquele que é condenado, garantindo também as garantias processuais mínimas.

### Conceitos
- **Recurso ao alcance**: Ação que visa revisar e corrigir aspectos da sentença condenatória
- **Garantia processual**: Direito fundamental garantido pelo Estado para proteger os direitos do recorrente
- **Duplicidade de grau de jurisdição**: O direito de ter um juízo de segunda instância para revisar a decisão de primeiro grau
- **Garantia constitucional**: Direito fundamental garantido pela Constituição para proteger os direitos do cidadão

### Referências legais
- Art. 8 da Convenção sobre Direitos Humanos

### Jurisprudência
- RHC 79.785
- AI 248761 AgR

### Dicas de prova
- Entenda a diferença entre recurso ao alcance e garantia processual
- Conheça o conceito de duplicidade de grau de jurisdição e sua importância
- Aprenda a distinguir entre garantias constitucionais e processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.76 (1)", "page_number": 76, "discipline": "Direitos Humanos", "legal_refs": ["Art. 8 da Convenção sobre Direitos Humanos"], "jurisprudence": ["RHC 79.785", "AI 248761 AgR"], "confidence": 0.8, "extracted_at": "2026-05-30T10:37:14.679447+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=76", "doc_key": "d2075840b682da472af88f9a33cce9a9"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '19ae9d77ecc2431f781ecee0fa41dc3031c643f2bf83bf8f743a5d5d1f041f35'),
  ('cpiuris2025::641874325de4b061632333b88c6a17c6', 'doutrina', 'cp_iuris', 'Direitos Humanos — Requisitos recursais e direito à recorrência no processo penal internacional', '## Requisitos recursais e direito à recorrência no processo penal internacional

A Corte IDH destaca a importância do direito de apresentação de recursos por parte dos indivíduos, mesmo em tribunal internacional. A competência do tribunal superior não é inconvencional, mas o acusado deve ter oportunidade de recurso, mesmo no mesmo órgão. A ausência de um recurso significou que a condenação fosse definitiva.

### Conceitos
- **Direito à recorrer**: O direito do indivíduo de apresentar recursos contra uma decisão judicial
- **Processo penal internacional**: O processo em que um Estado é acusado de cometer um crime contra a humanidade ou outro crime grave
- **Competência do tribunal superior**: A capacidade do tribunal superior de julgar um caso
- **Garantia mínima do devido processo**: O direito fundamental de ter um processo justo e imparcial

### Referências legais
- Art. 8.2.h) da Convenção Americana
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: direito à recorrer na Justiça Internacional

### Dicas de prova
- Entenda a importância do direito de apresentação de recursos no processo penal internacional
- Diferencie entre competência do tribunal superior e garantia mínima do devido processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.76 (2)", "page_number": 76, "discipline": "Direitos Humanos", "legal_refs": ["Art. 8.2.h) da Convenção Americana", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: direito à recorrer na Justiça Internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T10:39:20.042528+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=76", "doc_key": "641874325de4b061632333b88c6a17c6"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '1dccab0eb7d74ddf164543a1c7e18509bdf8d04413810be92fae3188b4271347'),
  ('cpiuris2025::ee3f376d79b0b107e58e8fa7a5077c5a', 'doutrina', 'cp_iuris', 'Direitos Humanos — Presunção de Inocência e Execução Provisória da Pena Fronte ao CADH', '## Presunção de Inocência e Execução Provisória da Pena Fronte ao CADH

O artigo 8.2 da CADH estabelece a presunção de inocência até que se comprove legalmente a culpa, evitando condenas informais. No Brasil, o art. 5º LVII prevê que ninguém será considerado culpado até o trânsito em julgado de sentença penal condênatoria.

### Conceitos
- **Presunção de Inocência**: Direito que assegura à pessoa acusada a não ser considerada culpada até que se comprove sua culpa
- **Execução Provisória da Pena**: Prática que pode levar à condenação de alguém antes da formação da culpa
- **Artigo 8.2 da CADH**: Dispositivo que estabelece a presunção de inocência até que se comprove a culpa
- **Artigo 5º LVII do Código Penal Brasileiro**: Previsão que assegura à pessoa acusada o direito à presunção de inocência até o trânsito em julgado de sentença penal condênatoria
- **Cantoral Venavides vs. Peru**: Casos da Corte IDH que citam a exposição de indivíduos como terroristas antes da comprovação de sua culpa
- **Duplo Grau de Jurisdição**: Prática que pode levar à responsabilização internacional do Brasil por violação ao artigo 8.2, h, da CADH
- **Jurisprudência da Corte IDH**: Posição divergente em relação à presunção de inocência e execução provisória da pena

### Referências legais
- Art. 8.2 da CADH
- Art. 5º LVII do Código Penal Brasileiro

### Jurisprudência
- Cantoral Venavides vs. Peru
- RE 123456

### Dicas de prova
- Entenda a importância da presunção de inocência e como ela se relaciona com a execução provisória da pena
- Conheça o dispositivo do artigo 8.2 da CADH e como ele se compara com o art. 5º LVII do Código Penal Brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.77 (2)", "page_number": 77, "discipline": "Direitos Humanos", "legal_refs": ["Art. 8.2 da CADH", "Art. 5º LVII do Código Penal Brasileiro"], "jurisprudence": ["Cantoral Venavides vs. Peru", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T10:40:54.591877+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=77", "doc_key": "ee3f376d79b0b107e58e8fa7a5077c5a"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c9f3cdce53bd54a22a21e923f13e277da7f1a958666f159d7063f10568ccc2a1'),
  ('cpiuris2025::3c02646e175c957ec356f6a964275821', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A proteção internacional dos direitos humanos não tem um marco claro para determinar a culpa, mas o dispositivo constitucional é de clareza e deve ser adotado. A execução provisória da pena é impedida pelo Supremo Tribunal Federal antes do trânsito em julgado da decisão penal condenatória.

### Conceitos
- **Proteção Internacional dos Direitos Humanos**: Direito de proteger os direitos humanos em todo o mundo
- **Culpa**: Ato ou omissão que pode ser considerado como responsável por um dano
- **Princípio da Nona Culpabilidade**: Princípio que impede a execução provisória da pena antes do trânsito em julgado da decisão penal condenatória
- **Execução Provisória**: Execução imediata de uma pena sem o trânsito em julgado da decisão penal condenatória
- **Garantia Versada**: Direito garantido pela Constituição Federal que impede a prender alguém sem prova concreta
- **Censura Prévia**: Restrição à liberdade de expressão antes de uma obra ser publicada ou difundida
- **Responsabilidades Uteriores**: Limitações à liberdade de expressão para proteger direitos ou interesses específicos

### Referências legais
- Art. 283 do Código de Processo Penal
- ADC 54, Relator(a): MARCO AURÉLIO

### Jurisprudência
- RE 123456
- Tema repetitivo: Proteção Internacional dos Direitos Humanos

### Dicas de prova
- Entenda o princípio da não culpabilidade e sua aplicação na execução provisória de penas
- Destaque a importância da garantia versada e do direito à liberdade de pensamento e expressão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.78 (1)", "page_number": 78, "discipline": "Direitos Humanos", "legal_refs": ["Art. 283 do Código de Processo Penal", "ADC 54, Relator(a): MARCO AURÉLIO"], "jurisprudence": ["RE 123456", "Tema repetitivo: Proteção Internacional dos Direitos Humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T10:42:33.013666+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=78", "doc_key": "3c02646e175c957ec356f6a964275821"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd2d57f5a16a7e4269977b568a95c45f50de3be70b71b7da52da4978c38fb9037'),
  ('cpiuris2025::c346c249dddeae2c7db33bacf79b29ca', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência para revisar sentença condenatória', '## Competência para revisar sentença condenatória

A Corte Interamericana de Direitos Humanos estabelece que, em ausência de um tribunal superior, a competência para revisar uma sentença condenatória pode ser exercida por um órgão colegiado superior com composição diferente da que conheceu a causa originalmente.

### Conceitos
- **Competência**: A capacidade do Estado de julgar um caso
- **Revisão de sentença**: O processo de reavaliação de uma sentença condenatória
- **Corte Interamericana de Direitos Humanos**: Entidade que protege os direitos humanos em nível internacional
- **Órgão colegiado superior**: Um órgão jurisdicional com composição diferente da que conheceu a causa originalmente
- **Plenário**: O conjunto de membros do órgão jurisdicional mais elevado

### Referências legais
- Art. 5º, LIV, da Constituição Brasileira
- Súmula 287/STF

### Jurisprudência
- Ação Penal 470 (Mensalão)
- Emenda Regimental nº 49/2014

### Dicas de prova
- Entenda a noção de competência e revisão de sentença
- Conheça a estrutura da Corte Interamericana de Direitos Humanos
- Aprenda com o caso Ação Penal 470 (Mensalão)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.77 (1)", "page_number": 77, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, LIV, da Constituição Brasileira", "Súmula 287/STF"], "jurisprudence": ["Ação Penal 470 (Mensalão)", "Emenda Regimental nº 49/2014"], "confidence": 0.8, "extracted_at": "2026-05-30T10:43:03.900820+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=77", "doc_key": "c346c249dddeae2c7db33bacf79b29ca"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f1f1691b777bf93131055c044147b0ae4cc9b3fd9f6a0d874aaf2fae00d55d21'),
  ('cpiuris2025::6f6062ac50887f35ce26240e1e484636', 'doutrina', 'cp_iuris', 'Direitos Humanos — Limites da liberdade de expressão', '## Limites da liberdade de expressão

A Declaração de princípios sobre liberdade de expressão da Comissão Interamericana de Direitos Humanos afirma que as leis que punem a expressão ofensiva contra funcionários públicos atentam contra a liberdade de expressão e o direito à informação. A Corte IDH considerou que a legislação sobre desacato aplicada ao autor do caso Palamara Iribarne estabelecia sanções desproporcionais.

### Conceitos
- **Liberdade de expressão**: Direito fundamental que permite a liberdade de pensamento e de opinião
- **Desacato**: Lei que punem a expressão ofensiva contra funcionários públicos
- **Corte IDH**: Comissão Interamericana de Direitos Humanos
- **Declaração de princípios sobre liberdade de expressão**: Documento que estabelece os limites da liberdade de expressão

### Referências legais
- Art. XXVIII da CADH
- Súmula 288 do STF

### Jurisprudência
- Palamara Iribarne vs. Chile

### Dicas de prova
- Entenda a distinção entre liberdade de expressão e desacato
- Conheça a jurisprudência da Corte IDH sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.78 (2)", "page_number": 78, "discipline": "Direitos Humanos", "legal_refs": ["Art. XXVIII da CADH", "Súmula 288 do STF"], "jurisprudence": ["Palamara Iribarne vs. Chile"], "confidence": 0.8, "extracted_at": "2026-05-30T10:43:37.242088+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=78", "doc_key": "6f6062ac50887f35ce26240e1e484636"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd04d5f0ba3b10398f41a6885e5cf5105cfb9ccea1693c8ec385be91bbb4ac1c6'),
  ('cpiuris2025::449a4aa617f33fd36bfdcdadb84ddcc8', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A proteção internacional dos direitos humanos é discutida no contexto da conformidade com a Convenção Americana de Direitos Humanos e a recepção pela Constituição de 1988 do art. 331 do Código Penal, que tipifica o crime de desacato.

### Conceitos
- **Desacato**: crime que pode ser punido ou não, dependendo da jurisprudência
- **Liberdade de Expressão**: direito absoluto que pode ser limitado em casos de grave abuso
- **Função Pública**: exercida por agentes públicos, protegida pela lei penal

### Referências legais
- Art. 331 do Código Penal
- Convenção Americana de Direitos Humanos
- ADPF 496/STF

### Jurisprudência
- REsp 1.640.084
- HC 379.269/MS
- Súmula N da STF

### Dicas de prova
- Distinção entre liberdade de expressão e proteção de outros interesses
- Conceito de função pública e sua proteção pela lei penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.80 (1)", "page_number": 80, "discipline": "Direitos Humanos", "legal_refs": ["Art. 331 do Código Penal", "Convenção Americana de Direitos Humanos", "ADPF 496/STF"], "jurisprudence": ["REsp 1.640.084", "HC 379.269/MS", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-30T10:44:41.956466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=80", "doc_key": "449a4aa617f33fd36bfdcdadb84ddcc8"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '8cf063577ae6b79e3122978c9e1ae6c95b6e611903dc48f1a119513a2654b6ef'),
  ('cpiuris2025::5ec2c0b48ed588f5aa2195b12556250a', 'doutrina', 'cp_iuris', 'Direitos Humanos — Desacato e Proteção Internacional dos Direitos Humanos', '## Desacato e Proteção Internacional dos Direitos Humanos

O texto discute o desacato no Brasil e sua comparação com o Código Penal Chileno, considerado pela decisão da Corte IDH. Além disso, é apresentada a legislação brasileira sobre desacato, incluindo as penas para injurias graves e leves contra autoridades.

### Conceitos
- **Desacato**: Ato de injuriar ou ameaçar alguém em atos públicos
- **Código Penal Chileno**: Legislação que regula o desacato no Chile
- **Injúria**: Ato de injuriar alguém
- **Multa**: Sancionamento financeiro imposto por infrações penais
- **Reclusão**: Pena de prisão
- **Autoridade**: Pessoa que detém poder e competência para tomar decisões
- **Desacato contra autoridade**: Ato de perturbar ou injuriar alguém em exercício de função pública

### Referências legais
- Art. 263 do Código Penal Brasileiro
- Art. 264 do Código Penal Brasileiro
- Art. 331 do Código Penal Brasileiro

### Dicas de prova
- Distinção entre desacato e injúria
- Penalidades para desacato contra autoridade
- Importância da legislação internacional na proteção dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.79", "page_number": 79, "discipline": "Direitos Humanos", "legal_refs": ["Art. 263 do Código Penal Brasileiro", "Art. 264 do Código Penal Brasileiro", "Art. 331 do Código Penal Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:44:47.391014+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=79", "doc_key": "5ec2c0b48ed588f5aa2195b12556250a"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '7fc9829d7f6009efc746f297e375049d8c1c4195a18af491de7ba384b020b36f'),
  ('cpiuris2025::fad73c5599ad1d5a3da317053d97a8f7', 'doutrina', 'cp_iuris', 'Direitos Humanos — Recepção da norma do art. 331 do Código Penal no âmbito constitucional', '## Recepção da norma do art. 331 do Código Penal no âmbito constitucional

A Constituição de 1988 recebeu a norma do art. 331 do Código Penal, que tipifica o crime de desacato, e a ADPF 496 julgou procedente a recepção dessa norma.

### Conceitos
- **Desacato**: crime que não é punido com severidade em relação à reprovação e insatisfação
- **Recepção de norma constitucional**: processo pelo qual uma norma legal é incorporada ao texto constitucional
- **ADPF 496**: Ação Direta de Impugnação à Constituição

### Referências legais
- Art. 331 do Código Penal
- Constituição de 1988

### Jurisprudência
- ADPF 496
- Súmula N da STF

### Dicas de prova
- Entenda a diferença entre crime e norma constitucional
- Leia o tratado e considere a tendência textualista das bancas de concurso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.80 (2)", "page_number": 80, "discipline": "Direitos Humanos", "legal_refs": ["Art. 331 do Código Penal", "Constituição de 1988"], "jurisprudence": ["ADPF 496", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-30T10:46:50.468554+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=80", "doc_key": "fad73c5599ad1d5a3da317053d97a8f7"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '2d97eff35d8e4e68aaef9eb35cea76087e3b895ac4eb7fb8462949bf71a302ea'),
  ('cpiuris2025::10617f2f715688be20a8bf30499c53fd', 'doutrina', 'cp_iuris', 'Direitos Humanos — Dever de efetividade progressiva dos direitos humanos', '## Dever de efetividade progressiva dos direitos humanos

Os Estados Partes comprometem-se a adotar medidas necessárias para garantir a efetividade progressiva dos direitos reconhecidos neste Protocolo, considerando seu grau de desenvolvimento e levando em conta os recursos disponíveis.

### Conceitos
- **Dever de efetividade**: O dever de garantir a eficácia imediata e progressiva dos direitos humanos
- **Recursos disponíveis**: A consideração do limite dos recursos disponíveis para a implementação das medidas necessárias
- **Grau de desenvolvimento**: O fator que influencia a capacidade do Estado em adotar medidas eficazes

### Referências legais
- Art. 1 do Protocolo Adicional à Convenção Americana sobre Direitos Humanos

### Dicas de prova
- Entenda o conceito de dever de efetividade progressiva e sua importância nos direitos humanos
- Leia atentamente as restrições e limitações estabelecidas pelos Estados Partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.81 (1)", "page_number": 81, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1 do Protocolo Adicional à Convenção Americana sobre Direitos Humanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:46:51.154441+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=81", "doc_key": "10617f2f715688be20a8bf30499c53fd"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'cef01b05dc26a102f2206beb9b8431ef95bfc077f2f62264ce66661f30749341'),
  ('cpiuris2025::5eabe9cc78db06411003e7741bdc1e8f', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência da Corte Interamericana de Direitos Humanos', '## Competência da Corte Interamericana de Direitos Humanos

A competência da Corte Interamericana de Direitos Humanos é restrita aos direitos sindicais e à educação, mas pode conhecer ações relacionadas ao tema devido à dicção geral do artigo 26 da CADH.

### Conceitos
- **Competência**: A capacidade do Estado ou ente jurídico de processar uma ação
- **Corte Interamericana de Direitos Humanos**: Entidade internacional responsável por proteger os direitos humanos
- **CADH**: Convenção Americana sobre Direitos Humanos
- **Artigo 26**: Disposição do CADH que permite a aplicação de petições individuais

### Referências legais
- Art. 8 da CADH
- Art. 13 da CADH

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a noção de competência e como ela se aplica à Corte Interamericana de Direitos Humanos
- Identifique a importância do artigo 26 da CADH para a aplicação de petições individuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.81 (2)", "page_number": 81, "discipline": "Direitos Humanos", "legal_refs": ["Art. 8 da CADH", "Art. 13 da CADH"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T10:47:14.901618+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=81", "doc_key": "5eabe9cc78db06411003e7741bdc1e8f"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '3404fd2eb7e27742d83adeea38c54228ffc8468feb17a2ab5277ebb23234ea03'),
  ('cpiuris2025::37d9ab32d838d5b2c9f02042551c5f2c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Inspiração liberal e individualista na escolha dos direitos', '## Inspiração liberal e individualista na escolha dos direitos

A inspiração liberal e individualista pautou a escolha dos direitos, expressando os valores dominantes da Europa ocidental. Os direitos sociais, econômicos e culturais são considerados ''mais problemáticos'' e devem ter tratamento específico.

### Conceitos
- **Direito à educação**: O direito de todos à educação
- **Carta Social Europeia**: Instrumento regional que protege os direitos sociais, econômicos e culturais
- **CEDH (Convenção Europeia dos Direitos Humanos)**: Instrumento internacional que protege os direitos humanos em Europa

### Referências legais
- Artigo 2º da CEDH
- Protocolo Adicional à CEDH de 1952

### Dicas de prova
- Entenda a distinção entre direitos civis e políticos e direitos sociais, econômicos e culturais.
- Conheça a Carta Social Europeia e sua importância nos direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.82 (2)", "page_number": 82, "discipline": "Direitos Humanos", "legal_refs": ["Artigo 2º da CEDH", "Protocolo Adicional à CEDH de 1952"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:49:06.390944+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=82", "doc_key": "37d9ab32d838d5b2c9f02042551c5f2c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd9e39a986bfe1e52ea715d83b4d78c080cd64f4a5d02e970fc54cc4383b403b0'),
  ('cpiuris2025::600cbf04645d9815ae2614ea58dcbc97', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

Resumo do texto sobre a evolução da Proteção Internacional dos Direitos Humanos, incluindo a criação da CEDH e a expansão de seus poderes.

### Conceitos
- **CEDH**: Corte Europeia dos Direitos do Homem
- **Comissão Europeia dos Direitos do Homem**: Órgão de investigação e conciliação da CEDH
- **Proteção Internacional dos Direitos Humanos**: Direito que protege os direitos humanos em todo o mundo
- **Protocolo adicional nº 2**: Protocolo que expandiu as funções da Corte Europeia dos Direitos do Homem
- **Subsidiariedade**: Princípio que estabelece a necessidade de uma autorização nacional para a aplicação de leis estrangeiras

