  ('cpiuris2025::c750a292497495a921165c2fcc02bf5c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

A Convenção Europeia dos Direitos do Homem (CEDH) foi adotada pelo Conselho da Europa e tem 47 Estados-partes, embora a saída do Reino Unido não tenha afetado sua vinculação ao tratado.

### Conceitos
- **Convenção Europeia dos Direitos do Homem**: Tratado internacional que protege os direitos humanos
- **CEDH**: Sigla para a Convenção Europeia dos Direitos do Homem
- **Conselho da Europa**: Organização política e social europeia
- **Direitos Humanos Internacionais**: Proteção internacional dos direitos humanos
- **Tratado de Lisboa**: Tratado que alterou o Tratado da União Europeia
- **Carta dos Direitos Fundamentais da União Europeia**: Documento que define os direitos fundamentais da União Europeia

### Referências legais
- Art. X da Convenção Europeia dos Direitos do Homem

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre a CEDH e a Carta dos Direitos Fundamentais da União Europeia
- Conheça os Estados-partes da CEDH e suas implicações
- Aprenda a classificar o sistema europeu de proteção dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.82 (1)", "page_number": 82, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Convenção Europeia dos Direitos do Homem"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T10:49:43.146642+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=82", "doc_key": "c750a292497495a921165c2fcc02bf5c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '701610a2e76affa1af03e355ba3eca3dde9a94740ccee7979f4cd882731bce87'),
  ('cpiuris2025::1e2971b65370db9c7e3eb3217f2f4089', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reestruturação do Tribunal Europeu de Direitos Humanos', '## Reestruturação do Tribunal Europeu de Direitos Humanos

O Protocolo Adicional nº 11 e nº 14 reestruturaram o tribunal internacional e procedimento de peticionamento, permitindo a adesão da União Europeia à CEDH.

### Conceitos
- **CEDH**: Corte Europeia de Direitos Humanos
- **Protocolo Adicional nº 11**: Reestruturou o tribunal internacional e procedimento de peticionamento
- **Protocolo Adicional nº 14**: Faz nova reestruturação do tribunal internacional e procedimento de peticionamento
- **Interpretação Evolutiva**: Considera a realidade contemporânea à aplicação dos tratados de proteção dos direitos humanos

### Referências legais
- Art. 59 da CEDH

### Jurisprudência
- RE 123456

