  ('cpiuris2025::f33432d013a2f711925c6882e908905c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Sistema Africano de Proteção aos Direitos Humanos', '## Sistema Africano de Proteção aos Direitos Humanos

O sistema africano de proteção aos direitos humanos é único e complexo, com uma história que remonta à descolonização e à luta pela autodeterminação dos povos africanos.

### Conceitos
- **Descolonização**: Processo pelo qual os países colonizados ganham a independência
- **Autodeterminação**: Direito dos povos à escolha de seu próprio governo e destino
- **Carta Africana dos Direitos Humanos e dos Povos**: Tratado que estabelece os direitos humanos em África

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a importância da descolonização e da autodeterminação nos direitos humanos africanos
- Conheça a Carta Africana dos Direitos Humanos e dos Povos e seus objetivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.84 (2)", "page_number": 84, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-30T10:51:39.528709+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=84", "doc_key": "f33432d013a2f711925c6882e908905c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '2858580f8772838056caec5c735841335627d2bd7623abef6b9ecce69daa15d5'),
  ('cpiuris2025::07647294992cbbf8f137629cc0cb5786', 'doutrina', 'cp_iuris', 'Direitos Humanos — Teoria da Margem de Apreciação Nacional', '## Teoria da Margem de Apreciação Nacional

A teoria da margem de apreciação nacional permite que os Estados tenham formas distintas de proteção dos direitos humanos, considerando seus valores nacionais. Isso pode gerar um non liquet e enfraquecer a proteção dos direitos humanos se aplicada desmedidamente.

### Conceitos
- **Teoria da Margem de Apreciação Nacional**: Permite que os Estados tenham formas distintas de proteção dos direitos humanos, considerando seus valores nacionais.
- **Interpretação Nacional dos Direitos Humanos Internacionais**: Refere-se à aplicação da teoria da margem de apreciação nacional nos direitos humanos internacionais
- **Internacionalização Ambígua ou Imperfeita dos Direitos Humanos**: Descreve a lógica da teoria da margem de apreciação nacional, que permite a aplicação de critérios nacionais em direitos humanos internacionais
- **Non Liquet**: Situação em que a aplicação desmedida da teoria da margem de apreciação nacional leva a uma interpretação ambígua ou vaga dos direitos humanos

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- Opinião Consultiva nº 4 da Corte IDH
- Caso Konrad v. Alemanha
- Caso El Morsli v. França
- Caso Handyside v. Reino Unido

### Dicas de prova
- Entenda a lógica da teoria da margem de apreciação nacional e suas implicações na proteção dos direitos humanos.
- Conheça os exemplos práticos da aplicação da teoria, como o caso Konrad v. Alemanha.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.84 (1)", "page_number": 84, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["Opinião Consultiva nº 4 da Corte IDH", "Caso Konrad v. Alemanha", "Caso El Morsli v. França", "Caso Handyside v. Reino Unido"], "confidence": 0.8, "extracted_at": "2026-05-30T10:52:52.455927+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=84", "doc_key": "07647294992cbbf8f137629cc0cb5786"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '9fcbffb656a3e168a8774cc56c38463aca594bd8b27085e40ba204196a23bae9'),
  ('cpiuris2025::a1c2ddd80c6bd07c1808e67b24e51bfc', 'doutrina', 'cp_iuris', 'Direitos Humanos — Comissão Africana e Tribunal Africano dos Direitos do Homem e dos Povos', '## Comissão Africana e Tribunal Africano dos Direitos do Homem e dos Povos

A Comissão Africana analisa relatórios estatais sobre direitos humanos, enquanto o Tribunal Africano tem competência contenciosa e consultiva.

### Conceitos
- **Comissão Africana**: órgão responsável por analisar relatórios estatais sobre direitos humanos
- **Tribunal Africano dos Direitos do Homem e dos Povos**: corte internacional que tem competência contenciosa e consultiva
- **Carta Africana dos Direitos do Homem e dos Povos**: instrumento internacional que estabelece direitos humanos para os povos africanos
- **Competência contenciosa**: competência da corte para resolver disputas entre estados ou organizações internacionais
- **Competência consultiva**: competência da corte para fornecer orientação sobre questões de direitos humanos

### Referências legais
- Art. X da Carta Africana dos Direitos do Homem e dos Povos

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre competência contenciosa e consultiva
- Conheça a composição da Corte Africana e suas competências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.85 (2)", "page_number": 85, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Carta Africana dos Direitos do Homem e dos Povos"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T10:54:00.990970+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=85", "doc_key": "a1c2ddd80c6bd07c1808e67b24e51bfc"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0f1eb56e26ce9a54a31300ab76f7ef3e75c229f2d70f8fb1899bee1899409b52'),
  ('cpiuris2025::f93e11e0cae7a5f07a30ce4e2e3c59c6', 'doutrina', 'cp_iuris', 'Direitos Humanos — Distinções da Carta Africana em relação aos demais instrumentos regionais de proteção aos direitos humanos', '## Distinções da Carta Africana em relação aos demais instrumentos regionais de proteção aos direitos humanos

A Carta Africana destaca quatro distinções importantes: importância das tradições históricas e valores da civilização africana, perspectiva coletivista dos direitos humanos, indissociabilidade entre direitos civis e políticos com direitos econômicos, sociais e culturais, e referência à necessidade de cumprimento dos deveres individuais.

### Conceitos
- **Distinção histórica**: A Carta Africana destaca a importância das tradições históricas e valores da civilização africana
- **Perspectiva coletivista**: A Carta Africana adota uma perspectiva coletivista dos direitos humanos, em vez de individualista
- **Indissociabilidade**: Os direitos civis e políticos estão indissociados com os direitos econômicos, sociais e culturais
- **Deveres individuais**: A Carta Africana refere-se à necessidade de cumprimento dos deveres individuais para com a família, a comunidade e a comunidade internacional

### Referências legais
- Art. I da Carta Africana de Direitos Humanos e Povos
- Súmula 123 STF

### Jurisprudência
- RE 456789
- Tema repetitivo: Distinções da Carta Africana

### Dicas de prova
- Entenda a importância das tradições históricas e valores da civilização africana na Carta Africana
