  ('cpiuris2025::59ebf4c3de0e89b23b5adad79baab586', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência da Corte Africana de Direitos Humanos e dos Povos', '## Competência da Corte Africana de Direitos Humanos e dos Povos

A Corte Africana tem competência expressa para analisar os direitos sociais em sentido amplo. A União Africana decidiu fundir o Tribunal de Justiça com a Corte Africana de Direitos Humanos e dos Povos, mas ainda não há ratificação do protocolo.

### Conceitos
- **Competência**: A capacidade da Corte Africana de analisar casos relacionados aos direitos humanos
- **Corte Africana de Direitos Humanos e dos Povos**: Entidade responsável por proteger os direitos humanos na África
- **Protocolo de Criação**: Documento que estabelece a Corte Africana de Justiça e Direitos Humanos
- **Ratificação**: Ação pelo qual um Estado assinante do protocolo o ratifica

### Referências legais
- Art. 4º do Protocolo da Corte Africana de Direitos Humanos e dos Povos

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência da Corte Africana e como ela se relaciona com os direitos humanos
