  ('cpiuris2025::1d39ec28db8897ab959a5646c41e7fa4', 'doutrina', 'cp_iuris', 'Direitos Humanos — Integração Regional e Direitos Humanos', '## Integração Regional e Direitos Humanos

A integração regional do Brasil envolve dimensões econômicas, políticas e sociais, com o objetivo de tornar-se um mercado comum, garantindo a livre circulação de bens e serviços.

### Conceitos
- **Mercado Comum**: área geográfica onde não há barreiras comerciais
- **União Aduaneira**: acordo que elimina tarifas de importação entre os membros

### Referências legais
- Art. X da Lei Y

