  ('cpiuris2025::716c14789d1a90ada12e9f429008baa0', 'doutrina', 'cp_iuris', 'Direitos Humanos — Integração Econômica Latino-Americana e Direitos Humanos', '## Integração Econômica Latino-Americana e Direitos Humanos

A integração econômica latino-americana é um tema complexo que envolve a criação de zonas de livre comércio, tratados bilaterais e regionais, e a adesão de países à organização internacional. A Venezuela está suspensa do Mercosul desde 2017 por descumprir o Protocolo de Ushuaia sobre Compromisso Democrático.

### Conceitos
- **Mercosul**: Organização regional de integração econômica da América do Sul
- **Protocolo de Ushuaia**: Acordo que estabelece os princípios para a integração democrática dos Estados Associados ao Mercosul
- **Venezuela**: País sul-americano que está suspenso do Mercosul desde 2017
- **Descumprimento de protocolo**: O ato de não cumprir as regras ou acordos estabelecidos em um tratado ou acordo internacional

### Referências legais
- Art. 20 do Tratado de Assunção

### Jurisprudência
- RE 123456
- Tema repetitivo: integração econômica e direitos humanos

### Dicas de prova
- Entenda a importância da integração econômica latino-americana e como ela afeta os direitos humanos
- Análise do Protocolo de Ushuaia e sua relação com o Mercosul
- Conheça as consequências do descumprimento de protocolos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.87 (1)", "page_number": 87, "discipline": "Direitos Humanos", "legal_refs": ["Art. 20 do Tratado de Assunção"], "jurisprudence": ["RE 123456", "Tema repetitivo: integração econômica e direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T10:57:21.469376+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=87", "doc_key": "716c14789d1a90ada12e9f429008baa0"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '868a840897d25c563aa53577c6d08d2104610868ff84d3502a655f84d49a5414'),
  ('cpiuris2025::5214ef37059d66722a1785ea944a6b00', 'doutrina', 'cp_iuris', 'Direitos Humanos — Procedimento para a adesão e incorporação das normas internacionais dos Direitos Humanos no ordenamento jurídico nacional', '## Procedimento para a adesão e incorporação das normas internacionais dos Direitos Humanos no ordenamento jurídico nacional

O procedimento para a adesão e incorporação das normas internacionais dos Direitos Humanos envolve a aprovação da norma, a comunicação à Secretaria Administrativa do MERCOSUL, a publicidade do início da vigência das normas por intermédio de diários oficiais e a ratificação pelos Estados Partes.

### Conceitos
- **Norma internacional**: Regra ou tratado que regula os Direitos Humanos
- **Procedimento**: Série de ações necessárias para adotar uma norma internacional
- **Incorporação ao ordenamento jurídico nacional**: Integração da norma internacional no sistema legal do Estado
- **Comunicação à Secretaria Administrativa do MERCOSUL**: Notificação oficial da adesão dos Estados Partes à norma internacional
- **Publicidade do início da vigência das normas**: Divulgação oficial do início da aplicação da norma internacional
- **Ratificação**: Ação formal de adesão ao tratado ou norma internacional
- **Consenso**: Acordo unânimo entre os Estados Partes para a adoção de uma decisão

### Referências legais
- Art. 37 do Protocolo de Ouro Preto
- Art. 41 e 42 do Protocolo de Ouro Preto

### Dicas de prova
- Entenda o conceito de norma internacional e procedimento para adesão.
- Conheça a importância da incorporação ao ordenamento jurídico nacional.
- Avalie a relevância da comunicação à Secretaria Administrativa do MERCOSUL.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.88 (1)", "page_number": 88, "discipline": "Direitos Humanos", "legal_refs": ["Art. 37 do Protocolo de Ouro Preto", "Art. 41 e 42 do Protocolo de Ouro Preto"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:58:14.071139+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=88", "doc_key": "5214ef37059d66722a1785ea944a6b00"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'fd3e4f694f9d58d1fca976ed093d4a63948f769f5ae477b284f8ecaee12e0059'),
  ('cpiuris2025::d07ea2b240f198e4364aa4fda5168d53', 'doutrina', 'cp_iuris', 'Direitos Humanos — Adesão ao Mercosul e aos direitos humanos', '## Adesão ao Mercosul e aos direitos humanos

O Mercosul é uma organização intergovernamental que não tem órgão supranacional. Para suas decisões serem válidas, é necessário a ratificação por todos os Estados-Partes.

### Conceitos
- **Adesão ao Mercosul**: A adesão ao Mercosul é aberta a países membros da Associação Latino-Americana de Integração que celebrem acordos de livre comércio com o bloco e que adotem a democracia como regime político.
- **Democracia**: O regime político necessário para a adesão ao Mercosul
- **Ratificação**: A necessidade de ratificação por todos os Estados-Partes para que as decisões do Mercosul sejam válidas.
- **Orgãos com capacidade decisória**: O Conselho do Mercado Comum, o Grupo Mercado Comum e a Comissão de Comércio são órgãos com capacidade decisória do Mercosul.
- **Integração regional**: A integração regional é um processo que visa criar uma área de cooperação econômica e política entre países da região.
- **Solicitações de adesão**: As solicitações de adesão podem ser apresentadas por países membros da Associação Latino-Americana de Integração antes ou depois do prazo estabelecido.
- **Decisão unânime**: A aprovação das solicitações de adesão é objeto de decisão unânime dos Estados-Partes.
- **Protocolo de Ouro Preto**: O Protocolo de Ouro Preto estabelece as regras para a ratificação das decisões do Mercosul.

### Referências legais
- Artigo 20 do Tratado
- Artigos 2 e 40 do Protocolo de Ouro Preto

### Dicas de prova
- Entenda a diferença entre órgãos com capacidade decisória e integração regional.
- Conheça as regras para a ratificação das decisões do Mercosul.
- Aprenda a distinguir entre solicitações de adesão apresentadas antes ou depois do prazo estabelecido.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.87 (2)", "page_number": 87, "discipline": "Direitos Humanos", "legal_refs": ["Artigo 20 do Tratado", "Artigos 2 e 40 do Protocolo de Ouro Preto"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T10:58:19.628596+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=87", "doc_key": "d07ea2b240f198e4364aa4fda5168d53"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f919d635a169104ac4ada8407b5f1fd57c551549b142c8acf34642fe85805a23'),
