  ('cpiuris2025::33b64acb93aff905671f94f5b50f943b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção Internacional dos Direitos Humanos', '## Proteção Internacional dos Direitos Humanos

O Mercosul tem instrumentos que buscam a proteção dos direitos humanos, mas o Tratado de Assunção e o Protocolo de Ouro Preto não mencionam isso como objetivo.

### Conceitos
- **instituições democráticas**: presença de instituições democráticas é essencial ao desenvolvimento do processo de integração
- **ruptura democrática**: ocorrência de uma ruptura nas instituições democráticas
- **meios pacíficos**: métodos não violentos para resolver conflitos
- **suspensão do Estado**: fim temporário das atividades do Estado em questão
- **direitos humanos como Estado-membro**: direitos humanos que são suspensos ou revogados em caso de ruptura democrática

### Referências legais
- Art. 1 do Protocolo de Ushuaia
- Art. 5 do Protocolo de Ushuaia

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância das instituições democráticas no contexto da integração regional.
- Conheça as consequências de uma ruptura democrática e como elas afetam os direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.89 (1)", "page_number": 89, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1 do Protocolo de Ushuaia", "Art. 5 do Protocolo de Ushuaia"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T11:00:47.859187+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=89", "doc_key": "33b64acb93aff905671f94f5b50f943b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '9c56766d240a48e450d6aceb3806535837b362d2eaf24cab904ce1130b3b5fa2')
